var e=JSON.parse(`{"wrist-circles":{"name":"Putar Pergelangan Tangan","description":"Berdiri tegak dengan siku lembut dan lengan bawah di depan Anda. Gambar lingkaran lambat dengan kedua pergelangan tangan, empat hitungan satu arah dan empat lainnya, sambil menjaga jari-jari tetap rileks.","goodFor":"Memanaskan pergelangan tangan dan lengan bawah yang melakukan sebagian besar pekerjaan dalam setiap prop.","alignmentCues":["Siku tetap diam; hanya pergelangan tangan yang bergerak.","Jaga lingkaran tetap besar dan halus."],"commonMistakes":["Menggerakkan lingkaran terlalu cepat sehingga berubah menjadi gerakan cepat."]},"arm-circles":{"name":"Putar Lengan","description":"Kaki selebar pinggul, lengan panjang. Ayunkan kedua lengan dalam lingkaran besar ke depan selama empat hitungan, lalu ke belakang selama empat, biarkan tulang belikat meluncur.","goodFor":"Membuka bahu untuk putaran tongkat dan kerja hoop di atas kepala.","alignmentCues":["Rusuk tetap turun saat lengan melewati atas kepala.","Tarik napas saat ayunan ke bawah."]},"shoulder-rolls":{"name":"Gulungan Bahu","description":"Lengan rileks di sisi tubuh. Angkat bahu ke arah telinga, gulirkan ke belakang dan ke bawah, lalu ulangi dalam lingkaran lambat.","goodFor":"Menghilangkan ketegangan yang membuat lemparan kaku dan pendek."},"neck-rolls":{"name":"Gulungan Leher Setengah Lingkaran","description":"Turunkan dagu ke arah dada dan gerakkan perlahan dari satu bahu ke bahu lainnya dalam setengah lingkaran. Jaga agar kepala tidak miring ke belakang.","goodFor":"Mengurangi ketegangan leher sebelum melihat ke atas saat melempar dalam waktu lama.","avoidIf":["Cedera leher atau pusing saat menggerakkan kepala."]},"hip-circles":{"name":"Putar Pinggul","description":"Tangan di pinggul, lutut lembut. Putar pinggul perlahan satu arah selama dua bar dan arah lainnya selama dua, sambil menjaga kepala tetap sejajar.","goodFor":"Mempersiapkan pinggul untuk hoop di pinggang dan tubuh untuk gerakan yang lancar."},"torso-twists":{"name":"Putar Tubuh","description":"Kaki lebar, lengan rileks. Putar rusuk ke kiri dan kanan dan biarkan lengan berayun serta melilit di sekitar Anda seperti lengan baju kosong.","goodFor":"Membangunkan rotasi untuk tenunan tongkat dan lemparan hoop."},"knee-bounce":{"name":"Loncatan Lutut","description":"Berdiri dengan kaki di bawah pinggul dan ayunkan lutut dengan lembut pada setiap ketukan, lengan berayun bebas. Temukan irama di kaki Anda.","goodFor":"Menghadirkan ketukan ke dalam tubuh Anda sebelum Anda mengambil prop."},"one-ball-toss":{"name":"Lempar Satu Bola","description":"Pegang satu bola di tangan kanan pada ketinggian pinggang. Angkat bola ke dalam, lalu lemparkan dalam busur yang mencapai puncak tepat di atas ketinggian mata dan jatuh ke tangan kiri. Lemparkan kembali dengan cara yang sama. Jaga mata tetap pada puncak busur, bukan pada tangan Anda.","goodFor":"Membangun busur yang menjadi dasar dari setiap pola juggling.","alignmentCues":["Siku di sisi tubuh, lengan bawah sejajar.","Puncaknya sama tinggi setiap lemparan.","Tangkap pada ketinggian pinggang dan biarkan tangan sedikit bergerak."],"commonMistakes":["Melempar ke depan sehingga Anda harus melangkah setelah bola.","Melihat tangan alih-alih puncak busur."]},"two-ball-exchange":{"name":"Pertukaran Dua Bola","description":"Satu bola di setiap tangan. Lemparkan bola kanan dalam busur; saat mencapai puncak, lemparkan bola kiri di bawahnya dari dalam. Tangkap keduanya dan berhenti sejenak. Kemudian mulai dengan tangan kiri.","goodFor":"Mengajarkan pertukaran: lemparan kedua dilakukan saat lemparan pertama mencapai puncak.","alignmentCues":["Lemparan kedua pada puncak, tidak pernah terlalu dini.","Lempar bola kedua di dalam bola pertama."],"commonMistakes":["Mengoper bola kedua melintasi alih-alih melemparkannya.","Melempar keduanya sekaligus."]},"cascade":{"name":"Tiga-Bola Cascade","description":"Dua bola di tangan kanan, satu di tangan kiri. Lemparkan dari tangan kanan; saat mencapai puncak, lemparkan dari tangan kiri; saat mencapai puncak, lemparkan dari tangan kanan lagi. Setiap lemparan sesuai dengan ketukan, melintasi ke tangan lain dalam busur berbentuk angka 8.","goodFor":"Pola dasar juggling.","modifications":["Latih flash: tiga lemparan, tiga tangkapan, berhenti."],"deepen":["Juggling dengan tempo lebih cepat dengan puncak yang lebih rendah.","Hitung 20 tangkapan tanpa terjatuh."],"alignmentCues":["Lempar dari dalam, tangkap dari luar.","Puncak sejajar, pada ketinggian mata.","Berdiri di dekat dinding jika Anda terus berjalan ke depan."],"commonMistakes":["Melempar ke depan dan mengejar pola.","Terburu-buru segera setelah satu lemparan salah."]},"reverse-cascade":{"name":"Kaskade Terbalik","description":"Cascade terbalik: setiap bola dilempar dari luar, melewati atas pola, dan jatuh ke tengah ke tangan lainnya.","goodFor":"Melatih lemparan dari luar dan membuka trik seperti Mills Mess.","alignmentCues":["Lemparan melingkari bola yang masuk.","Tangkap di tengah."]},"siteswap-423":{"name":"423","description":"Pola tiga bola: lemparan tinggi ke arah diri sendiri (4), bola yang dipegang (2), lalu lemparan cascade (3). Angka 4 naik di sisi yang sama; angka 2 hanya dipegang selama satu ketukan.","goodFor":"Trik siteswap pertama Anda: mengajarkan lemparan tinggi dan pegangan."},"siteswap-441":{"name":"441","description":"Dua lemparan tinggi yang tetap di sisi masing-masing (4, 4) diikuti dengan lemparan cepat (1) dari tangan ke tangan.","goodFor":"Membangun ketepatan waktu antara lemparan tinggi dan lemparan cepat."},"two-in-one":{"name":"Dua dalam Satu Tangan","description":"Juggling dua bola dalam satu tangan dalam kolom berdampingan atau lingkaran kecil ke luar, satu lemparan pada setiap ketukan. Latih setiap tangan.","goodFor":"Bahan dasar juggling empat bola."},"siteswap-531":{"name":"531","description":"Lemparan silang yang sangat tinggi (5), lemparan cascade (3), dan lemparan cepat (1). Angka 5 naik sementara dua bola lainnya terus bekerja di bawahnya.","goodFor":"Kontrol ketinggian dan trik tiga bola yang menarik."},"shower":{"name":"Tiga-Bola Hujan","description":"Bola bergerak dalam lingkaran: tangan kanan melempar setiap bola tinggi ke tangan kiri, dan tangan kiri mengembalikan setiap bola langsung ke tangan kanan.","goodFor":"Pola melingkar klasik; melatih lemparan cepat dari tangan ke tangan."},"mills-mess":{"name":"Mills Mess","description":"Cascade tiga bola di mana lengan terus saling melintasi dan membuka, sehingga setiap lemparan datang dari sisi tubuh yang berlawanan. Jalur bola membentuk pola tenun.","goodFor":"Penghibur yang terkenal yang mempertajam koordinasi."},"four-ball-fountain":{"name":"Air Mancur Empat Bola","description":"Setiap tangan menjuggling dua bola di kolomnya sendiri, tangan bergantian melempar sehingga polanya tidak pernah saling bersilangan.","goodFor":"Pola juggling empat bola pertama Anda."},"sync-fountain":{"name":"Air Mancur Sinkron","description":"Empat bola dengan kedua tangan melempar pada saat yang tepat bersamaan, masing-masing ke sisi sendiri.","goodFor":"Membangun simetri dan mengarah ke trik sinkron."},"five-ball-cascade":{"name":"Kaskade Lima Bola","description":"Cascade dengan lima bola: lemparan tinggi dan cepat dalam pola silang yang tinggi. Harapkan berbulan-bulan latihan.","goodFor":"Pencapaian penting bagi para juggling yang berdedikasi."},"tennis":{"name":"Tenis","description":"Cascade di mana satu bola, \\"bola tenis\\", selalu melintas di atas pola alih-alih melalui tengah. Tangan mana pun yang memegangnya melemparkannya dari luar sehingga melambung melintasi atas seperti pukulan balik di atas net.","goodFor":"Langkah pertama ke dalam lemparan luar sambil waktu tetap cascade biasa.","alignmentCues":["Jaga satu bola tetap terlihat sebagai bola tenis.","Lempar dari luar, dengan ketinggian yang sama dengan yang lain."],"commonMistakes":["Kehilangan jejak bola mana yang melewati atas.","Melempar bola yang melewati lebih tinggi dari yang lain."]},"half-shower":{"name":"Setengah Pancuran","description":"Satu tangan melempar setiap bola di atas sementara tangan lain melempar setiap bola di bawah. Dua busur terpisah menjadi jalur luar yang tinggi dan jalur dalam yang rendah, dan bola-bola saling mengejar dalam lingkaran.","goodFor":"Memisahkan tangan menjadi dua peran sambil ritme tetap merata.","alignmentCues":["Tangan atas melempar dari luar dan sedikit lebih tinggi.","Tangan bawah menjaga lemparannya rapat dan di dalam."],"commonMistakes":["Kedua tangan bergerak kembali ke lemparan cascade biasa.","Tumbukan di tengah saat busur memiliki ketinggian yang sama."]},"claw-cascade":{"name":"Kaskade Cakar","description":"Kaskade menangkap telapak tangan menghadap ke bawah. Setiap tangan menjangkau ke atas dan menangkap bola dari udara dari atas, lalu menarik ke bawah dan membalik untuk melempar. Tangan terlihat seperti sedang meraih bola.","goodFor":"Membangun tangkapan aktif dan putaran pergelangan tangan yang kuat.","alignmentCues":["Jangkau ke atas untuk menangkap bola, jari-jari terbuka.","Tarik ke bawah dan putar pergelangan tangan dalam satu gerakan."],"commonMistakes":["Menangkap terlambat sehingga bola mengenai bagian belakang tangan.","Melempar terlalu rendah karena putaran terlalu lama."]},"chops":{"name":"Pemotong","description":"Setelah setiap tangkapan, tangan membawa bola tinggi melintasi tubuh dan memotong ke bawah, melempar dari sisi yang berlawanan. Lengan berayun melewati satu sama lain seperti memotong, dan bola jatuh ke dalam kaskade yang rapat di bawah.","goodFor":"Pembawaan lengan besar dengan waktu kaskade masih di bawah.","alignmentCues":["Tangkap tinggi, bawa melintasi, potong ke bawah dan lempar.","Lempar dari sisi berlawanan tubuh Anda."],"commonMistakes":["Membawa terlalu jauh sehingga tangkapan berikutnya terlambat.","Lengan saling bertabrakan di tengah."]},"penguin-cascade":{"name":"Kaskade Penguin","description":"Lengan tergantung lurus di sisi tubuh dengan telapak tangan menghadap ke bawah. Setiap tangkapan terjadi rendah dan ke samping, dan lemparan meluncur ke atas dari pinggul. Anda terlihat seperti penguin yang mengibaskan sayap mengikuti irama.","goodFor":"Lemparan dan tangkapan yang didorong pergelangan tangan jauh dari posisi tangan biasa.","alignmentCues":["Siku lurus, tangan di sisi pinggul.","Luncurkan dari pergelangan tangan, telapak tangan menghadap ke belakang."],"commonMistakes":["Membengkokkan siku ke belakang menjadi kaskade normal.","Lemparan melayang ke depan karena pergelangan tangan terlalu miring."]},"under-the-leg":{"name":"Di Bawah Kaki","description":"Kaskade di mana setiap lemparan keenam melewati bawah kaki kanan. Angkat lutut saat bola tiba, jangkau di bawah paha dan lempar ke atas dari luar, lalu letakkan kaki untuk tangkapan berikutnya.","goodFor":"Lemparan tubuh pertama: angkat kaki dan jangkauan lengan diatur waktu pada satu ketukan.","alignmentCues":["Angkat lutut sebelum lempar, bukan saat melempar.","Lempar sedikit lebih tinggi untuk menutup jangkauan ekstra."],"commonMistakes":["Membungkuk ke arah kaki alih-alih mengangkat lutut.","Terburu-buru melakukan lemparan berikutnya setelah kaki turun."]},"behind-the-back":{"name":"Di Belakang Punggung","description":"Setiap lemparan keenam, tangan kanan mengayunkan bola ke belakang pinggang dan melemparkannya ke atas di atas bahu yang berlawanan, lalu mendarat kembali dalam pola di depan. Lemparan lainnya tetap menjadi cascade biasa.","goodFor":"Melempar secara buta ke dalam pola yang tidak bisa dilihat.","alignmentCues":["Ayunkan tangan ke belakang lebih awal, saat bola mendarat.","Arahkan ke atas bahu yang jauh, sedikit lebih tinggi dari biasanya."],"commonMistakes":["Melempar terlalu jauh ke depan sehingga bola mendarat di depan Anda.","Mengputar seluruh batang tubuh."]},"over-the-shoulder":{"name":"Di Atas Bahu","description":"Setiap lemparan keenam, tangan kanan mengirim bola tinggi dari depan, ke atas dan ke belakang di atas bahu kiri. Tangan kiri mengayunkan ke belakang pinggul dan menangkapnya secara buta, lalu memantulkan bola berikutnya ke atas dari samping pinggul. Semua yang lain adalah cascade biasa.","goodFor":"Menangkap secara buta di belakang punggung, diatur oleh perasaan bukan penglihatan.","alignmentCues":["Lemparkan cukup tinggi untuk melewati kepala, tepat di belakang bahu kiri.","Dapatkan tangan penangkap di belakang pinggul lebih awal, telapak tangan menghadap ke atas."],"commonMistakes":["Memutar kepala untuk mencari bola.","Melempar terlalu rendah sehingga bola menyentuh kepala atau bahu."]},"knee-bounce-cascade":{"name":"Goyangkan lutut","description":"Setiap lemparan keenam, tangan kanan menjatuhkan bola ke lutut kanan saat lutut naik. Bola memantul dari bagian atas paha, ke atas dan melintasi ke tangan kiri, lalu kaki turun kembali untuk tangkapan berikutnya.","goodFor":"Menyeimbangkan diri di satu kaki sementara lutut bergabung dengan pola pada ketukan.","alignmentCues":["Angkat lutut untuk menyambut bola, setinggi paha.","Jatuhkan bola, jangan lemparkan ke bawah."],"commonMistakes":["Menendang bola sehingga terbang ke depan.","Membungkuk ke arah lutut alih-alih mengangkatnya."]},"head-bounce-cascade":{"name":"Head Bounce","description":"Setiap lemparan keenam melewati kepala Anda. Miringkan kepala ke belakang sehingga bola mendarat di dahi Anda, lalu angguk ke bawah dan ke depan ke tangan kiri. Lemparan lainnya tetap menjadi cascade biasa di bawahnya.","goodFor":"Melacak bola tepat di atas Anda sambil tangan terus menjalankan cascade.","alignmentCues":["Miringkan kepala ke belakang lebih awal dan tetap fokus pada bola.","Lenturkan lutut sedikit untuk melunakkan pantulan."],"commonMistakes":["Memukul bola dengan kepala alih-alih membiarkannya jatuh.","Kehilangan cascade saat melihat ke atas."]},"crossed-arm-cascade":{"name":"Cascade Lengan Silang","description":"Silangkan lengan depan dengan tangan kanan di sisi kiri dan pertahankan posisi silang. Juggling cascade dari posisi tersebut. Lemparan terasa terpantul meskipun polanya terlihat normal.","goodFor":"Memutus kebiasaan di mana masing-masing tangan berada.","alignmentCues":["Pertahankan silangan di pergelangan tangan, bukan siku.","Lemparan mencapai puncak pada ketinggian mata seperti biasa."],"commonMistakes":["Membuka silangan di antara lemparan.","Tangan saling bertabrakan saat bertukar sisi."]},"burkes-barrage":{"name":"Serangan Burke","description":"Dibangun berdasarkan 423. Bola dilempar sebagai 4, diambil dan dibawa melintasi, 2 adalah angkat pendek di tangan yang sama, dan 3 dipotong ke dalam pola. Lengan saling berjalin dalam gerakan yang sibuk.","goodFor":"Menggabungkan membawa dan mengambil bola di atas siteswap yang sudah Anda ketahui.","alignmentCues":["Pelajari waktu 423 terlebih dahulu, lalu tambahkan membawa.","Lemparan 2 hampir tidak meninggalkan tangan."],"commonMistakes":["Melempar 2 terlalu tinggi sehingga mengganggu ritme.","Lupa memotong pada 3."]},"rubensteins-revenge":{"name":"Balas Dendam Rubenstein","description":"Kekacauan membawa bola di atas 52233. Lemparan tinggi membeli waktu sambil tangan mengambil, memotong, dan saling melintasi, lalu pola kembali terurai menjadi cascade. Pelajari secara perlahan, satu tangan pada satu waktu.","goodFor":"Pertunjukan yang melatih membawa, mengambil, dan saling melintasi lengan secara bersamaan.","alignmentCues":["Lemparan 5 adalah satu-satunya lemparan tinggi.","Pelajari lintasan tangan dengan bola tinggi ditinggalkan."],"commonMistakes":["Panik selama membawa dan melempar terlalu dini.","Lemparan tinggi melayang ke depan."]},"siteswap-42":{"name":"Dua-Bola 42","description":"Dua bola: masing-masing tangan melempar satu bola tinggi ke arah dirinya sendiri dan menahan yang lain selama satu ketukan. Bola-bola tinggi naik dalam kolom di masing-masing sisi sambil tangan bergantian. Cara yang tenang untuk belajar melempar ke arah diri sendiri.","goodFor":"Melempar ke arah diri sendiri pada ketinggian empat, dasar dari dua bola dalam satu tangan.","alignmentCues":["Lemparan tetap di sisi masing-masing.","Tahan bola 2 tetap di telapak tangan."],"commonMistakes":["Lemparan melayang melintasi tengah.","Melempar bola yang dipegang secara tidak sengaja."]},"snake":{"name":"Ular","description":"Tiga bola dilempar sebagai lima silang tinggi dengan satu ketukan kosong setelah masing-masing. Bola-bola mengikuti satu demi satu di sepanjang busur tinggi yang sama, seperti ular meluncur di atas kepala Anda.","goodFor":"Lemparan tinggi yang konsisten tanpa tekanan ritme lima bola penuh.","alignmentCues":["Semua lemparan lima memiliki ketinggian yang sama.","Gunakan ketukan kosong untuk mengatur ulang tangan."],"commonMistakes":["Lemparan lima melayang ke depan.","Melempar pada ketukan kosong karena kebiasaan."]},"grace":{"name":"Grace","description":"Sebuah multiplex lembut: satu tangan melempar dua bola sekaligus, satu lemparan silang normal dan satu lemparan kecil langsung ke tangan lainnya. Kemudian satu ketukan dipegang dan kembali ke cascade.","goodFor":"Pengenalan lembut terhadap melempar dua bola dari satu tangan.","alignmentCues":["Lepaskan kedua bola secara bersamaan.","Bola kecil hampir tidak naik."],"commonMistakes":["Melepaskan kedua bola pada waktu yang berbeda.","Melempar bola kecil terlalu tinggi."]},"orinoco-flow":{"name":"Aliran Orinoco","description":"Dua putaran 42 dengan lemparan cascade yang disambungkan di akhir, sehingga lemparan ke arah diri sendiri berganti sisi setiap putaran. Ini bergerak bergelombang antara kolom dan cascade.","goodFor":"Peralihan yang lancar antara lemparan ke arah diri sendiri dan lemparan silang.","alignmentCues":["Lemparan empat lurus ke atas di samping Anda.","3 adalah lemparan cascade biasa."],"commonMistakes":["Empat condong ke dalam.","Kehilangan hitungan siklus lemparan lima."]},"relfs-rhythm":{"name":"Ritme Relf","description":"Sebuah lemparan sendiri dan pegangan, lalu tiga lemparan cascade. Karena siklusnya ganjil, lemparan sendiri mendarat di tangan lain setiap putaran.","goodFor":"Memasukkan trik ke dalam cascade yang sedang berjalan di kedua sisi.","alignmentCues":["Cascade terlebih dahulu, lalu turunkan 42.","Pertahankan empat di sisi sendiri."],"commonMistakes":["Hanya melakukannya di tangan yang kuat.","Cascade menjadi lebih cepat setelahnya."]},"frostbite":{"name":"Frostbite","description":"Dua empat cepat, lemparan cepat melintasi, lalu dua lemparan cascade. Lepasan menyelinap di bawah sementara empat menggantung di atas.","goodFor":"Mencampur lemparan cepat dengan lemparan tinggi dalam satu siklus.","alignmentCues":["1 adalah lemparan langsung melintasi.","Empat tetap vertikal."],"commonMistakes":["Melempar 1 alih-alih melewatkan.","Lupa empat kedua."]},"siteswap-52512":{"name":"52512","description":"Dua lima tinggi dipisahkan oleh satu ketukan yang dipegang, lalu lima, lemparan cepat, dan pegangan. Pola ini mencampur lemparan lintas tinggi dengan lemparan rendah pendek.","goodFor":"Kontrol tinggi-rendah yang presisi dengan tiga bola.","alignmentCues":["Semua lima mencapai ketinggian yang sama.","Dua tetap di tangan."],"commonMistakes":["Melempar 2.","Lima tidak merata."]},"high-low-shower":{"name":"Shower Tinggi-Rendah","description":"Percikan air dengan sentuhan khusus: satu bola naik sangat tinggi sementara yang lainnya melintas cepat di bawah. Ritme terdengar seperti langkah kuda.","goodFor":"Perbedaan ketinggian besar dan tangan cepat dalam pola tiga bola.","alignmentCues":["Tujuh naik tinggi dan lurus.","Satu adalah lemparan datar."],"commonMistakes":["Tujuh melayang ke depan.","Satu melengkung terlalu tinggi."]},"siteswap-612":{"name":"612","description":"Lemparan tinggi sendiri, lemparan cepat, dan tahanan. Angka enam naik di samping Anda di sisi yang sama, sementara dua bola lainnya saling bertukar di bawah.","goodFor":"Lemparan tinggi sendiri yang dicampur dengan lemparan rendah cepat.","alignmentCues":["Angka enam tetap di sisinya.","Lempar angka 1 datar dan cepat."],"commonMistakes":["Angka enam melintasi.","Menahan terlalu lama pada angka 2."]},"three-in-one":{"name":"Tiga dalam Satu Tangan","description":"Tiga bola dijuggling hanya dengan tangan kanan dalam kolom tinggi atau air mancur kecil. Setiap lemparan tinggi sehingga ada waktu untuk menangkap dan melempar lagi.","goodFor":"Kontrol satu tangan dan konsistensi ketinggian.","alignmentCues":["Lemparan mencapai puncak jauh di atas kepala.","Jaga tangan bergerak dalam lingkaran kecil."],"commonMistakes":["Lemparan melayang ke luar.","Lemparan terlalu rendah untuk menjaga tiga bola tetap berjalan."]},"columns":{"name":"Kolom","description":"Tiga bola naik dalam kolom vertikal. Kedua tangan melempar bola luar secara bersamaan, lalu tangan kanan melempar bola tengah sendiri. Naik, naik, naik, seperti piston.","goodFor":"Lemparan simultan pertama dan dasar untuk banyak trik sinkron.","alignmentCues":["Kolom luar naik bersamaan.","Kolom tengah naik lurus dari tengah."],"commonMistakes":["Kolom miring sehingga bola-bola bertabrakan.","Waktu yang tidak merata pada pasangan."]},"infinity":{"name":"Infinity","description":"Pola kolom di mana lemparan tunggal melintasi alih-alih ke atas secara langsung, sehingga bola tengah bertukar sisi setiap kali. Bola-bola membentuk angka delapan.","goodFor":"Mengalihkan pola sinkron antar sisi.","alignmentCues":["Pasangan ke atas, tunggal melintas.","Sisi bergantian setiap siklus."],"commonMistakes":["Lemparan tunggal ke atas secara langsung karena kebiasaan.","Pasangan melayang."]},"rainbow-cross":{"name":"Silang Pelangi","description":"Dua bola saling melintasi dalam pasangan, lalu satu bola meluncur ke atas di tengah. Busur lintasan membentuk pelangi di atas kepala Anda.","goodFor":"Lemparan sinkron yang saling melintasi tanpa tabrakan.","alignmentCues":["Satu lemparan melintas sedikit di depan yang lain.","Lemparan tengah ke atas secara langsung."],"commonMistakes":["Bola yang saling melintas saling bertabrakan.","Lemparan tengah miring."]},"crossunder":{"name":"Crossunder","description":"Setiap lemparan melintasi: pasangan melintas, lalu lemparan tunggal melintas yang mengganti sisi setiap siklus. Bola-bola berputar di atas dan di bawah satu sama lain.","goodFor":"Kontrol sinkron semua lemparan melintasi.","alignmentCues":["Jaga agar lemparan melintas berada di bidang yang sedikit berbeda.","Ketinggian yang merata sepanjang waktu."],"commonMistakes":["Tabrakan di tengah.","Lemparan tunggal terlalu pendek."]},"yo-yo":{"name":"Yo-Yo","description":"Satu tangan melempar kolom sementara tangan lainnya memegang bola dan bergerak naik turun di bawah salah satunya, seolah-olah kedua bola dihubungkan oleh tali.","goodFor":"Ilusi yang mengajarkan bola yang dipegang bergerak di sepanjang sebuah kolom.","alignmentCues":["Bola yang dipegang mengikuti bayangan bola kolom.","Kolom tetap vertikal."],"commonMistakes":["Bola yang dipegang tertinggal.","Kolom bergerak menjauh."]},"box":{"name":"Kotak","description":"Bola membentuk persegi. Satu tangan melempar bola ke atas secara langsung sementara tangan lainnya mengoper bola secara melintang, kemudian peran saling bertukar. Sisi tinggi, atas dan bawah datar.","goodFor":"Pola sinkronisasi klasik yang melatih operan horizontal.","alignmentCues":["Operan melintang lurus pada ketinggian tangan.","Vertikal naik lurus ke atas."],"commonMistakes":["Operan melengkung terlalu tinggi.","Kolom miring ke dalam."]},"broken-box":{"name":"Kotak Pecah","description":"Sebuah kotak yang berganti sisi setiap lemparan: lemparan vertikal dan operan melintang bergantian tangan, sehingga persegi terus melipat pada dirinya sendiri.","goodFor":"Pertukaran peran sinkronisasi cepat.","alignmentCues":["Ganti vertikal setiap ketukan.","Operan datar dan cepat."],"commonMistakes":["Mengulangi vertikal di sisi yang sama.","Terburu-buru dalam operan."]},"als-slide":{"name":"Al's Slide","description":"Lemparan tinggi saling bersilangan dipasangkan dengan operan datar, lalu pegangan dan lemparan tinggi saling bersilangan lainnya. Bola meluncur di bagian atas dan bawah dalam bentuk bergulir yang halus.","goodFor":"Lemparan bersilangan sinkron yang dicampur dengan operan dan pegangan.","alignmentCues":["Empat bersilangan mencapai puncak bersama.","Pegang 2 tetap."],"commonMistakes":["Melempar bola yang dipegang.","Benturan di tengah."]},"factory":{"name":"Pabrik","description":"Satu tangan bekerja seperti sabuk pengangkut, membawa bola melintasi di tingkat pinggang, sementara tangan lainnya melempar kolom. Bola berputar dalam siklus seperti mesin.","goodFor":"Koordinasi membawa dan melempar dalam ritme sinkron.","alignmentCues":["Tangan yang membawa bergerak dalam lingkaran lebar.","Kolom tetap tegak."],"commonMistakes":["Tangan membawa menjatuhkan bola ke dalam kolom.","Kolom miring."]},"broken-shower":{"name":"Shower Rusak","description":"Percikan sinkron: tangan kanan melempar tinggi ke sisi lain sementara tangan kiri melempar rendah ke sisi lain pada saat yang sama. Bola berputar dalam lingkaran yang rapat.","goodFor":"Versi sinkron dari lingkaran percikan.","alignmentCues":["Kedua tangan melepaskan secara bersamaan.","Busur tinggi untuk tangan kanan, lemparan datar untuk tangan kiri."],"commonMistakes":["Melepaskan satu demi satu.","Lemparan melengkung ke atas menuju bola tinggi."]},"crossed-arm-shower":{"name":"Shower Lengan Silang","description":"Percikan yang dijuggling dengan lengan terlipat. Lemparan tinggi datang dari sisi kiri tubuh Anda dan lemparan cepat kembali di bawah.","goodFor":"Kontrol percikan dalam posisi lengan yang tidak biasa.","alignmentCues":["Tetap terlipat sepanjang waktu.","Lemparan dekat dengan tubuh."],"commonMistakes":["Membuka lipatan untuk melakukan tangkapan.","Lemparan terlalu tinggi."]},"siteswap-534":{"name":"534","description":"Pola empat bola yang mencampurkan lemparan silang lima, cascade tiga, dan lemparan diri empat. Rasanya seperti 423 empat bola dan terhubung dengan baik ke fountain.","goodFor":"Trik empat bola yang paling populer, dan cara masuk ke siteswap yang lebih tinggi.","alignmentCues":["Lima tertinggi, tiga terendah.","Empat tetap di sisinya."],"commonMistakes":["Menyebabkan ketinggian merata.","Terburu-buru pada tiga."]},"siteswap-552":{"name":"552","description":"Dua lima bersilangan dan satu pegangan. Empat bola dijuggling dengan ritme lima bola dengan satu ketukan untuk bernapas.","goodFor":"Lemparan tinggi lima dengan waktu pemulihan.","alignmentCues":["Kedua lima identik.","Pegang 2 tetap."],"commonMistakes":["Melempar pegangan.","Lima melayang ke depan."]},"siteswap-5551":{"name":"5551","description":"Tiga lima berturut-turut dan satu lemparan cepat. Langkah yang baik menuju kaskade lima bola.","goodFor":"Berlatih serangkaian lima dengan empat bola.","alignmentCues":["Lima semua ketinggiannya sama.","Lemparan cepat datar untuk 1."],"commonMistakes":["Lima turun perlahan.","Melempar 1 terlalu tinggi."]},"siteswap-55550":{"name":"55550","description":"Empat lima dan satu tangan kosong. Kaskade lima bola dengan satu bola hilang, yang menjadikannya latihan lima bola yang bagus.","goodFor":"Langkah terakhir sebelum kaskade lima bola.","alignmentCues":["Gunakan celah untuk menetap.","Lima konsisten."],"commonMistakes":["Melempar ke dalam celah.","Lima melayang."]},"siteswap-633":{"name":"633","description":"Lemparan diri tinggi lalu dua lemparan kaskade. Angka enam menggantung di atas sementara kaskade berjalan di bawah.","goodFor":"Lemparan diri tinggi yang dijalin ke dalam ritme empat bola.","alignmentCues":["Angka enam tetap di atas tangan sendiri.","Angka tiga tetap rendah."],"commonMistakes":["Angka enam melayang.","Angka tiga terlalu tinggi."]},"siteswap-53":{"name":"53","description":"Satu tangan melempar tinggi lintas lima sementara yang lain melempar rendah tiga kaskade. Hujan setengah-ke-setengah dari empat bola.","goodFor":"Kontrol ketinggian antara kedua tangan.","alignmentCues":["Tangan kanan tinggi, tangan kiri rendah.","Ritme merata."],"commonMistakes":["Ketinggian menyatu.","Terburu-buru melempar tiga."]},"wimpy":{"name":"Pola Wimpy","description":"Empat bola dengan setiap pasangan saling bersilangan pada saat yang sama. Busur saling bertukar sisi setiap ketukan dalam pola silang lebar.","goodFor":"Sinkronisasi bersilangan pada empat bola.","alignmentCues":["Satu tangan melempar sedikit di depan.","Lepas bersamaan."],"commonMistakes":["Benturan di tengah.","Melepas secara bergantian."]},"four-ball-shower":{"name":"Pertunjukan Empat Bola","description":"Empat bola dalam lingkaran: lemparan sangat tinggi dari satu tangan dan operan datar dari tangan lainnya.","goodFor":"Konsistensi lemparan tinggi pada empat bola.","alignmentCues":["Angka tujuh lurus dan tinggi.","Lemparan cepat dan datar."],"commonMistakes":["Sevens melayang ke depan.","Lemparan naik."]},"tsunami":{"name":"Tsunami","description":"Sebuah tujuh tinggi, sebuah pegangan, sebuah empat sendiri, sebuah lemparan, dan sebuah enam sendiri tinggi. Gelombang tinggi menerjang pola ini.","goodFor":"Kontrol empat bola tingkat lanjut dengan ketinggian campuran.","alignmentCues":["Pelajari lemparan secara perlahan sesuai urutan.","Tujuh dan enam keduanya dilempar tinggi."],"commonMistakes":["Ketinggian tidak konsisten.","Kehilangan hitungan."]},"siteswap-645":{"name":"645","description":"Versi lima bola dari 534: sebuah enam sendiri tinggi, sebuah empat sendiri, dan sebuah lima silang.","goodFor":"Trik pertama dari kaskade lima bola.","alignmentCues":["Enam paling tinggi.","Empat tetap di sisinya."],"commonMistakes":["Mengurangi ketinggian.","Melayang."]},"siteswap-744":{"name":"744","description":"Sebuah tujuh silang yang sangat tinggi diikuti oleh dua empat sendiri.","goodFor":"Penyisipan lemparan tinggi dalam lima bola.","alignmentCues":["Tujuh lurus dan tinggi.","Empat vertikal."],"commonMistakes":["Tujuh melayang.","Empat saling silang."]},"five-ball-shower":{"name":"Pancuran Lima Bola","description":"Lima bola dalam lingkaran: sembilan tinggi dari satu tangan dan lemparan datar kembali di bawah.","goodFor":"Ketinggian dan ketepatan di tingkat tertinggi.","alignmentCues":["Sembilan lurus dan konsisten.","Lemparan datar."],"commonMistakes":["Sembilan melenceng.","Lemparan naik."]},"five-ball-half-shower":{"name":"Shower Setengah Lima Bola","description":"Lemparan silang sinkron, satu tangan lebih tinggi dari yang lain, dengan lima bola.","goodFor":"Kontrol lemparan silang sinkron pada lima bola.","alignmentCues":["Kanan lebih tinggi, kiri lebih rendah.","Lepas bersamaan."],"commonMistakes":["Ketinggian menyatu.","Benturan."]},"martins-one-count":{"name":"Pola Martin","description":"Multiplex: enam tinggi dan bola yang dipegang dilepaskan bersamaan, lalu pegangan dan lima silang.","goodFor":"Waktu multiplex pada lima bola.","alignmentCues":["Multiplex dilepaskan dengan bersih.","Lima silang."],"commonMistakes":["Memisahkan multiplex.","Enam meluncur."]},"six-ball-fountain":{"name":"Air Terjun Enam Bola","description":"Tiga bola di setiap tangan, dijuggling dalam air mancur tinggi berdampingan.","goodFor":"Milestone jumlah enam bola.","alignmentCues":["Setiap tangan menjalankan air mancur sendiri.","Lemparan tinggi dan konsisten."],"commonMistakes":["Air mancur saling mendekat.","Lemparan terlalu rendah."]},"club-swing":{"name":"Putaran Klub Tunggal","description":"Pegang satu klub di pegangannya, ujungnya terjepit di telapak tangan. Ayunkan dari pinggang sehingga klub berputar sekali di udara dan tiba dengan pegangan terlebih dahulu di tangan lainnya. Lemparkan kembali dengan cara yang sama.","goodFor":"Mempelajari putaran tunggal yang menjadi dasar dari setiap pola klub.","alignmentCues":["Angkat dari siku, biarkan pergelangan tangan memutar klub.","Tangkap pegangan pada ketinggian pinggang."],"commonMistakes":["Memutar pergelangan tangan sehingga klub berputar terlalu cepat.","Melempar ke depan sehingga pegangan mendarat jauh."]},"club-exchange":{"name":"Pertukaran Dua Klub","description":"Satu klub di setiap tangan. Lemparkan satu putaran dari tangan kanan; saat mencapai puncak, lemparkan klub kiri di bawahnya. Tangkap keduanya dengan pegangannya dan berhenti sejenak, lalu mulai dengan tangan yang lain.","goodFor":"Mengatur waktu dua klub berputar tanpa tabrakan.","alignmentCues":["Klub kedua berada di puncak yang pertama.","Lempar klub kedua di dalam klub pertama."],"commonMistakes":["Klub saling bertabrakan di tengah.","Putaran tidak merata antar tangan."]},"club-cascade":{"name":"Kaskade Tiga Klub","description":"Kaskade dengan klub, masing-masing berputar sekali. Lemparan datang dari bagian dalam tubuh dan bergerak melintasi, dengan pegangan klub diarahkan ke arah Anda.","goodFor":"Pola dasar untuk semua juggling klub.","alignmentCues":["Lempar dari siku, jaga pergelangan tangan tetap lembut.","Klub tetap sejajar dengan dada Anda."],"commonMistakes":["Klub miring sehingga berputar secara horizontal.","Berputar terlalu cepat dan menangkap tubuh."]},"club-doubles":{"name":"Klub Ganda","description":"Kaskade tiga klub di mana setiap klub berputar dua kali di udara. Lemparan lebih tinggi dan lebih lambat, serta klub berputar dalam lingkaran besar.","goodFor":"Kontrol putaran dan ketinggian yang dibutuhkan untuk empat klub.","alignmentCues":["Angkat lebih dari lengan, bukan pergelangan tangan.","Jaga agar putaran ganda tetap halus dan merata."],"commonMistakes":["Membalik pergelangan tangan dan memutar terlalu cepat.","Melempar ganda terlalu rendah."]},"club-flats":{"name":"Club Flats","description":"Sebuah kaskade di mana klub tidak berputar sama sekali. Setiap klub melayang melintasi pegangan ke bawah, didorong ke atas oleh pergelangan tangan yang lurus, dan ditangkap tegak.","goodFor":"Kontrol pergelangan tangan, dan perbandingan yang mudah dengan lemparan berputar.","alignmentCues":["Kunci pergelangan tangan dan dorong dari siku.","Klub tetap tegak sepanjang perjalanan."],"commonMistakes":["Putaran setengah yang tidak disengaja.","Melempar terlalu tinggi sehingga klub goyah."]},"club-under-leg":{"name":"Club Di Bawah Kaki","description":"Sebuah kaskade klub di mana setiap lemparan keenam dilewatkan di bawah kaki kanan. Angkat lutut, ayunkan klub di bawah paha dan biarkan berputar ke dalam pola.","goodFor":"Lemparan tubuh pertama dengan klub.","alignmentCues":["Lutut ke atas lebih awal.","Sedikit ketinggian ekstra pada lemparan kaki."],"commonMistakes":["Mengenai kaki dengan klub.","Membungkuk daripada mengangkat lutut."]},"club-behind-back":{"name":"Club Di Belakang Punggung","description":"Sebuah kaskade klub di mana setiap lemparan keenam digerakkan di belakang pinggang dan dikirim ke atas bahu yang berlawanan ke dalam pola.","goodFor":"Lemparan klub buta di belakang tubuh.","alignmentCues":["Ayunkan lengan di belakang lebih awal.","Arahkan ke atas bahu yang jauh."],"commonMistakes":["Klub mendarat terlalu jauh di depan.","Memutar batang tubuh."]},"club-four-fountain":{"name":"Empat-Klub Air Mancur","description":"Dua klub di setiap tangan, masing-masing tangan melempar ganda dalam aliran sendiri. Klub tidak pernah melintasi tengah.","goodFor":"Pencapaian empat-klub.","alignmentCues":["Ganda di sisi masing-masing.","Tangan bergantian secara merata."],"commonMistakes":["Klub melayang ke tengah.","Berputar tidak merata antar tangan."]},"ring-cascade":{"name":"Tiga-Cincin Cipratan","description":"Aliran dengan cincin dipegang tepi ke depan, seperti kemudi yang dilihat dari sisi. Setiap cincin terbang melalui pola tanpa berputar, sehingga tepi memotong udara dengan bersih.","goodFor":"Cara sederhana untuk mencoba cincin dan merasakan bagaimana mereka melayang.","alignmentCues":["Pegang cincin tepi ke arah Anda.","Lepaskan dengan pergelangan tangan lurus."],"commonMistakes":["Cincin bergoyang karena pergelangan tangan miring.","Melempar menghadap ke depan sehingga tertangkap angin."]},"ring-pancakes":{"name":"Cincin Pancake","description":"Aliran cincin di mana setiap cincin berputar datar di bagian atas lemparan dan kembali ke posisi tepi untuk penangkapan, seperti pancake yang diputar di wajan.","goodFor":"Kontrol pergelangan tangan dan hiasan cincin yang menarik.","alignmentCues":["Putar pergelangan tangan cepat saat melepas.","Tangkap cincin tepi ke depan lagi."],"commonMistakes":["Terlalu banyak memutar.","Melempar rendah sehingga cincin tidak bisa berputar."]},"ring-four-fountain":{"name":"Empat-Cincin Air Mancur","description":"Dua cincin di setiap tangan, dijuggling dalam aliran terpisah, tepi memotong ke atas dan ke bawah secara lurus.","goodFor":"Empat benda dengan alat yang ringan dan melayang.","alignmentCues":["Cincin tetap posisi tepi.","Setiap tangan menjalankan kolomnya sendiri."],"commonMistakes":["Cincin saling bersentuhan di tengah.","Lemparan melayang ke depan."]},"hoop-juggle-single":{"name":"Lempar Cincin Tunggal","description":"Pegang sebuah hoop di tepinya, menggantung di samping Anda. Lemparkan dengan busur lembut ke tangan lainnya sehingga bergerak tepi ke depan dan tiba pada ketinggian yang sama saat berangkat.","goodFor":"Belajar bagaimana hoop ukuran penuh terbang sebelum menambahkan lebih banyak.","alignmentCues":["Jaga hoop tetap posisi tepi ke arah dada Anda.","Lempar dari bahu, bukan dari pergelangan tangan."],"commonMistakes":["Melemparkannya menghadap ke depan sehingga melayang pergi.","Lemparan rendah dan menangkap."]},"hoop-juggle-exchange":{"name":"Pertukaran Dua Cincin","description":"Satu hoop di setiap tangan. Lemparkan hoop kanan; saat mencapai puncak, lemparkan hoop kiri di bawahnya. Hoop saling melewati dekat, satu di depan yang lain.","goodFor":"Waktu dua hoop dan menjaga hoop agar tidak saling bertabrakan.","alignmentCues":["Hoop kedua di puncak yang pertama.","Lempar yang kedua sedikit ke depan."],"commonMistakes":["Hoop saling bertabrakan.","Lemparan keduanya terlalu cepat."]},"hoop-juggle-cascade":{"name":"Kaskade Tiga Cincin","description":"Cascading dengan hoop ukuran penuh. Tangan tetap lebar, lemparan besar dan lambat, dan setiap hoop berputar posisi tepi dalam pola.","goodFor":"Pola dasar untuk juggling hoop.","alignmentCues":["Lengan lebar, siku lembut.","Setiap hoop berada di bidang yang sama."],"commonMistakes":["Hoop melayang ke depan.","Terburu-buru dalam melempar."]},"hoop-juggle-reverse":{"name":"Kaskade Hoop Terbalik","description":"Cincin dilempar dari luar ke atas dan ditangkap di dalam, cascade terbalik dalam skala besar.","goodFor":"Lemparan dari luar dengan cincin.","alignmentCues":["Lempar dari luar, ke atas.","Tangkap di dekat tengah."],"commonMistakes":["Cincin mendarat terlalu lebar.","Busur tidak merata."]},"hoop-juggle-shower":{"name":"Hoop Shower","description":"Tiga cincin dalam lingkaran: lemparan tinggi dari satu tangan dan serah terima cepat di bawah.","goodFor":"Ketinggian dan kendali lemparan dengan cincin.","alignmentCues":["Lemparan tinggi lurus ke atas dan melintasi.","Serah terima dekat tubuh."],"commonMistakes":["Lemparan tinggi melayang.","Serah terima naik."]},"hoop-juggle-two-in-one":{"name":"Dua Hoop dalam Satu Tangan","description":"Dua cincin dijuggling hanya dengan tangan kanan, naik dalam kolom di samping Anda.","goodFor":"Kendali cincin satu tangan.","alignmentCues":["Kolom tetap vertikal.","Lempar tinggi untuk membeli waktu."],"commonMistakes":["Cincin melayang keluar.","Terlalu rendah."]},"hoop-juggle-423":{"name":"Hoop 423","description":"Siteswap 423 dengan tiga cincin: empat self, dua dipegang, dan tiga melintas.","goodFor":"Variasi siteswap dengan cincin.","alignmentCues":["Empat tetap di sisi sendiri.","Tahan angka 2."],"commonMistakes":["Melempar angka 2.","Empat bergerak menjauh."]},"hoop-juggle-441":{"name":"Hoop 441","description":"Dua empat sendiri dan serah terima cepat dengan lingkaran. Serah terima tergelincir di bawah pasangan tinggi.","goodFor":"Serah terima cepat antara lemparan lingkaran tinggi.","alignmentCues":["Empat vertikal.","Serah terima datar."],"commonMistakes":["Serah terima dilempar tinggi.","Empat bergerak menjauh."]},"hoop-juggle-four":{"name":"Empat-Hoop Fountain","description":"Dua lingkaran di setiap tangan, dijuggling dalam bentuk air terjun berdampingan.","goodFor":"Milestone empat lingkaran.","alignmentCues":["Setiap sisi terpisah.","Ritme merata."],"commonMistakes":["Lingkaran bergerak bersama.","Lemparan terlalu rendah."]},"hoop-juggle-under-leg":{"name":"Hoop di Bawah Kaki","description":"Tangkapan lingkaran dengan setiap lemparan keenam dilewati di bawah kaki kanan yang terangkat.","goodFor":"Lemparan tubuh dengan alat besar.","alignmentCues":["Angkat lutut tinggi.","Lempar sedikit lebih tinggi."],"commonMistakes":["Lingkaran menangkap kaki.","Membungkuk ke depan."]},"hoop-juggle-back-throw":{"name":"Lemparan Hoop ke Belakang","description":"Sebuah cascade hoop di mana setiap lemparan keenam dilakukan di belakang punggung dan di atas bahu yang jauh.","goodFor":"Lemparan buta dengan hoop.","alignmentCues":["Ayunkan ke belakang lebih awal.","Di atas bahu yang jauh."],"commonMistakes":["Hoop mendarat di depan.","Membelit."]},"hoop-juggle-body-hoop":{"name":"Juggling Saat Menggunakan Hoop Pinggang","description":"Pertahankan satu hoop berputar di pinggang sambil menjuggling tiga lagi dalam cascade. Pinggul menjaga ritme mereka sendiri di bawah lengan.","goodFor":"Membagi perhatian antara body hooping dan juggling.","alignmentCues":["Pinggul menggerakkan body hoop, lengan tetap independen.","Pertahankan bidang juggling di depan body hoop."],"commonMistakes":["Body hoop melambat saat Anda fokus pada juggling.","Lengan jatuh ke dalam body hoop."]},"pass-one-ball":{"name":"Pass Satu Bola","description":"Berdiri menghadap pasangan Anda sekitar dua setengah meter jaraknya. Lempar satu bola dari tangan kanan Anda dalam busur lembut ke tangan kiri mereka. Mereka menyerahkannya ke tangan kanan mereka dan melemparkannya kembali ke tangan kiri Anda, lalu Anda menyerahkannya ke tangan kanan Anda lagi.","goodFor":"Mempelajari ketinggian dan jarak lemparan sebelum menjuggling.","alignmentCues":["Lempar lurus ke arah lawan, jangan saling melintasi.","Puncaknya sedikit di atas tinggi kepala, di tengah-tengah antara Anda.","Lihat pasangan Anda, bukan bola di tangan Anda."],"commonMistakes":["Lempar ke wajah pasangan alih-alih ke atas dalam busur.","Mengarahkan ke tangan kanan mereka, sehingga lemparan saling melintasi."]},"pass-hand-across":{"name":"Pass Dua Bola","description":"Masing-masing dua bola. Kalian berdua melempar dari tangan kanan pada saat yang sama. Setiap tangan kiri menangkap lemparan yang datang dan menyerahkannya langsung ke tangan kanan, siap untuk lemparan berikutnya. Tidak ada yang dilempar ke diri sendiri, jadi ini semua tentang sinkronisasi lemparan bersama.","goodFor":"Lemparan pada irama bersama sebelum menambahkan cascade.","alignmentCues":["Lempar bersama: tangan kanan pada hitungan.","Tangkap dengan tangan kiri, lewat rendah dan cepat."],"commonMistakes":["Salah satu dari kalian melewatkan terlalu awal sehingga lemparan saling bersilangan di udara pada waktu yang berbeda.","Melempar tangan secara melintang alih-alih menyerahkannya."]},"pass-six-count":{"name":"Enam-Kali","description":"Kalian berdua menjuggling tiga bola dalam pola cascade dan lempar setiap lemparan keenam, selalu dari tangan kanan ke tangan kiri pasangan kalian. Di antara lemparan, kalian memiliki lima lemparan sendiri untuk menyeimbangkan pola.","goodFor":"Pola lemparan penuh pertama: banyak waktu di antara lemparan.","alignmentCues":["Hitung dengan keras: lempar, dua, tiga, empat, lima, enam.","Jaga agar lemparan sendiri memiliki ketinggian yang sama dengan lemparan.","Lihat pasangan kalian, bukan tangan kalian sendiri."],"commonMistakes":["Kehilangan hitungan dan melempar pada ketukan yang salah.","Melempar terlalu pendek sehingga pasangan kalian harus melompat."]},"pass-four-count":{"name":"Empat-Kali","description":"Lepas setiap lemparan keempat, setiap lemparan tangan kanan. Lepas, lempar sendiri, lempar sendiri, lempar sendiri, lalu lepas lagi. Ini adalah pemanasan lemparan klub standar dan dasar untuk sebagian besar variasi.","goodFor":"Pola lemparan sehari-hari; sebagian besar trik dimulai dari sini.","alignmentCues":["Tangan kanan melempar bersamaan.","Tiga lemparan sendiri, lalu lemparan datang lagi."],"commonMistakes":["Menghancurkan lemparan sendiri untuk membuat waktu bagi lemparan.","Memutar bahu untuk melempar alih-alih menggunakan lengan bawah."]},"pass-three-count":{"name":"Tiga-Kali","description":"Lepas setiap lemparan ketiga, sehingga lemparan bergantian tangan: kanan, lalu kiri, lalu kanan. Setiap lemparan tangan kiri langsung melintasi ke tangan kanan pasangan kalian.","goodFor":"Lepas dari kedua tangan dan menangkap lemparan dengan kedua tangan.","alignmentCues":["Lemparan tangan kiri melintas langsung, seperti tangan kanan.","Jaga ketinggian lemparan tetap sama dari kedua tangan."],"commonMistakes":["Lemparan tangan kiri yang lemah yang jatuh pendek.","Melintasi lemparan kiri ke tangan kiri mereka."]},"pass-two-count":{"name":"Dua-Kali","description":"Setiap lemparan tangan kanan adalah lemparan, dan setiap lemparan tangan kiri adalah lemparan sendiri. Pass, self, pass, self. Dua kali lebih banyak lemparan dibandingkan empat hitungan dengan teknik kaki yang sama.","goodFor":"Ritme lemparan yang cepat dan merata; pintu gerbang menuju pola tujuh objek.","alignmentCues":["Tangan kanan melempar, tangan kiri melempar sendiri.","Jaga agar lemparan sendiri di dalam, di bawah lemparan yang datang."],"commonMistakes":["Membiarkan lemparan sendiri semakin rendah.","Menangkap lemparan terlalu dekat dengan tubuh."]},"pass-left-two-count":{"name":"Dua-Kali dengan Tangan Kiri","description":"Dua hitungan yang terbalik: setiap lemparan tangan kiri adalah lemparan, langsung ke tangan kanan pasangan Anda, dan tangan kanan melempar sendiri.","goodFor":"Menyamakan kekuatan tangan lempar yang lebih lemah.","alignmentCues":["Lemparan kiri langsung ke seberang, tidak saling silang.","Tinggi dan dorongan yang sama dengan lemparan tangan kanan Anda."],"commonMistakes":["Lemparan pendek dari tangan yang lemah.","Beralih kembali ke lemparan tangan kanan karena kebiasaan."]},"pass-ultimates":{"name":"Ultimates","description":"Setiap lemparan adalah lemparan. Tangan kanan melempar langsung ke tangan kiri, dan tangan kiri melempar langsung ke tangan kanan; tidak ada yang melempar sendiri. Bola membentuk aliran konstan di antara Anda.","goodFor":"Akurasi dan ritme lemparan di bawah tekanan.","alignmentCues":["Setiap lemparan melintasi: kanan, kiri, kanan, kiri.","Tangkap dan lempar dalam satu gerakan yang mengalir."],"commonMistakes":["Memegang bola dan memutus aliran.","Lemparan menjadi lebih datar saat tempo meningkat."]},"club-pass-four-count":{"name":"Empat-Kali Klub","description":"Empat hitungan dengan klub. Setiap lemparan adalah satu putaran yang dilempar dari tangan kanan ke tangan kiri pasangan Anda, tiba dengan pegangan terlebih dahulu. Tiga lemparan sendiri tunggal di antara lemparan.","goodFor":"Awal standar untuk setiap sesi lempar klub.","alignmentCues":["Lempar dari samping pinggul kanan dengan ayunan lurus ke depan.","Satu putaran: pegangan harus mendarat di tangan pasangan Anda."],"commonMistakes":["Terlalu banyak putaran sehingga lemparan tiba dengan ujung pegangan terlebih dahulu.","Melempar melintasi tubuh ke kanan pasangan Anda."]},"club-pass-two-count":{"name":"Club Dua-Kali","description":"Setiap lemparan tangan kanan adalah satu lemparan tunggal dan setiap lemparan tangan kiri adalah satu lemparan sendiri. Ritme inti dari lemparan klub.","goodFor":"Ritme lemparan klub yang stabil.","alignmentCues":["Lempar, lempar sendiri, lempar, lempar sendiri, pada ketukan genap.","Jaga lemparan kiri tetap rapat dan di dalam."],"commonMistakes":["Menghentikan putaran pada lemparan kiri.","Lemparan bergerak ke kiri dan kanan."]},"club-pass-three-count":{"name":"Club Tiga-Kali","description":"Lemparan klub setiap lemparan ketiga, sehingga bergantian tangan. Lemparan tangan kiri langsung melintasi ke kanan pasangan Anda.","goodFor":"Lemparan klub dari tangan yang lemah.","alignmentCues":["Ayunan yang sama dari kedua tangan.","Kanan lalu kiri lalu kanan: hitunglah."],"commonMistakes":["Lemparan tangan kiri dengan putaran yang terlalu sedikit.","Memutar tubuh untuk lemparan kiri."]},"club-pass-doubles":{"name":"Club Empat-Kali dengan Doubles","description":"Satu empat-ketukan di mana setiap lemparan adalah putaran ganda, dilempar lebih tinggi sehingga mendarat satu ketukan kemudian. Untuk memberi ruang, tangan kiri menahan klubnya selama satu ketukan setelah lemparan alih-alih melempar.","goodFor":"Lemparan ganda, langkah pertama menuju lemparan tujuh klub.","alignmentCues":["Lemparan ganda lebih tinggi dan lebih lambat: dua putaran penuh.","Tahan klub kiri selama lemparan, lalu lanjutkan."],"commonMistakes":["Melempar ganda secepat lemparan tunggal, sehingga berputar berlebihan.","Melempar klub kiri alih-alih menahannya."]},"club-pass-ultimates":{"name":"Club Ultimates","description":"Setiap lemparan adalah satu lemparan klub tunggal, bergantian kanan dan kiri. Enam klub mengalir di antara Anda tanpa lemparan ke diri sendiri.","goodFor":"Akurasi lemparan klub pada kecepatan penuh.","alignmentCues":["Tangkap dan lempar dalam satu ayunan.","Lemparan lurus: kanan ke kiri, kiri ke kanan."],"commonMistakes":["Lemparan melayang ke tengah dan bertabrakan.","Memegang klub dan memutus aliran."]},"club-pass-seven-doubles":{"name":"Tujuh-Club Crossing Doubles","description":"Tujuh klub di antara Anda. Tangan kanan Anda melempar ganda silang ke tangan kanan pasangan Anda pada setiap lemparan bergantian, dan tangan kiri mereka menjawab satu lemparan kemudian dengan ganda silang ke tangan kiri Anda. Lemparan tunggal mengisi celah.","goodFor":"Pola tujuh klub pertama, dibangun dari ganda.","alignmentCues":["Ganda Anda melintasi ke tangan kanan pasangan.","Tangkap ganda mereka di tangan kiri Anda, segera setelah lemparan Anda sendiri."],"commonMistakes":["Melempar lurus alih-alih melintasi.","Ganda terlalu rendah untuk menyelesaikan dua putaran."]},"staff-wheel-spin":{"name":"Putaran Roda Dua Tangan","description":"Pegang tongkat di tengah dengan kedua tangan, telapak tangan ke bawah, pada ketinggian dada. Putar di sisi Anda seperti roda dengan memindahkan putaran antar tangan, sambil menjaga tongkat tetap di samping tubuh.","goodFor":"Putaran tongkat pertama; membangun pegangan dan rotasi pergelangan tangan.","alignmentCues":["Tongkat tetap sejajar dengan tubuh Anda, jangan pernah miring.","Pegangan lembut: biarkan bergulir melalui jari-jari."],"props":["tongkat"],"commonMistakes":["Menggenggam terlalu erat sehingga putaran terhenti.","Miringkan bidang ke depan."]},"staff-front-spin":{"name":"Angin Topan Depan","description":"Putar tongkat di depan Anda seperti baling-baling, dalam bidang dinding, dengan memindahkannya dengan lancar dari tangan ke tangan di sekitar pusatnya.","goodFor":"Menambahkan bidang dinding dan pemindahan tangan demi tangan.","props":["tongkat"]},"staff-figure-8":{"name":"Tenun Angka 8","description":"Putar tongkat di bidang roda di sisi kanan Anda, lalu salurkan ke sisi kiri dan putar di sana, membentuk angka 8 di depan Anda.","goodFor":"Menghubungkan kedua sisi tubuh; tulang punggung dari aliran tongkat.","alignmentCues":["Ganti sisi saat ujung tongkat melewati lantai.","Putar tubuh sedikit dengan setiap sisi."],"props":["tongkat"]},"staff-pass-through":{"name":"Lewati","description":"Putar di bidang dinding tetapi lepaskan setiap setengah putaran: satu tangan melepaskan tongkat dan tangan lainnya menangkapnya di tengah, sehingga tongkat melewati antara kedua tangan Anda.","goodFor":"Mengajarkan waktu melepaskan dan menangkap.","props":["tongkat"]},"staff-one-hand-spin":{"name":"Putar Satu Tangan","description":"Putar tongkat di depan Anda dengan satu tangan, gulirkan di bagian belakang tangan dan melalui jari-jari. Latih kedua tangan.","goodFor":"Kekuatan jari dan pergelangan tangan; membebaskan tangan lain untuk trik.","props":["tongkat"]},"staff-helicopter":{"name":"Helikopter Atas Kepala","description":"Angkat tongkat di atas kepala dan putar secara datar di bidang lantai dengan satu tangan, seperti baling-baling helikopter.","goodFor":"Memperkenalkan bidang lantai.","props":["tongkat"]},"staff-butterfly":{"name":"Kupu-Kupu","description":"Putar di depan Anda, lalu lipat tongkat di belakang bahu Anda dan keluarkan kembali, bergantian depan dan belakang di setiap sisi seperti sayap.","goodFor":"Mobilitas bahu dan transisi alir dari depan ke belakang.","props":["tongkat"]},"staff-behind-back-pass":{"name":"Lewat di Belakang Punggung","description":"Salurkan tongkat yang berputar dari satu tangan ke tangan lainnya di belakang punggung Anda di bagian bawah putaran, lalu bawa ke depan.","goodFor":"Sirkuit tubuh dan saluran tampilan.","props":["staff"]},"staff-isolation":{"name":"Isolasi Tongkat","description":"Pegang tongkat di dekat salah satu ujungnya dan putar tangan Anda di sekitar tengah tongkat, sehingga tengahnya tampak tetap diam di udara sementara tongkat berputar di sekitarnya.","goodFor":"Pekerjaan ilusi dan lintasan tangan yang presisi.","props":["staff"]},"staff-antispin-flower":{"name":"Empat-Petal Antispin","description":"Putar tangan Anda ke satu arah sementara tongkat berputar ke arah berlawanan tiga kali lebih cepat, sehingga tongkat menggambar bunga empat kelopak.","goodFor":"Bunga VTG khas; kontrol waktu yang mendalam.","props":["staff"]},"staff-neck-roll":{"name":"Gulungan Leher","description":"Lepaskan tongkat ke bagian belakang bahu Anda dan biarkan berguling melintasi leher ke tangan lainnya. Mulailah perlahan dengan tongkat yang berbantalan.","goodFor":"Tongkat kontak: tongkat bergerak di tubuh tanpa tangan.","avoidIf":["Nyeri leher."],"props":["staff"]},"staff-reverse-wheel":{"name":"Putaran Roda Terbalik","description":"Putaran roda berlawanan arah: ujung depan tongkat naik dan bergerak ke belakang di atas. Kedua tangan tetap di tengah dan menggulungnya, persis seperti dalam putaran maju.","goodFor":"Menyeimbangkan kedua arah putaran sehingga setiap gerakan selanjutnya berfungsi dalam kedua arah.","alignmentCues":["Roda datar yang sama di samping Anda, hanya arahnya yang berubah.","Pimpin dengan buku jari yang berguling ke belakang."],"props":["staff"],"commonMistakes":["Bidang bergeser melintasi tubuh Anda.","Beralih kembali ke maju tanpa menyadarinya."]},"staff-reverse-front-spin":{"name":"Putaran Depan Terbalik","description":"Putaran depan dua tangan yang berjalan berlawanan arah. Ujung atas jatuh ke arah kanan Anda bukan ke kiri.","goodFor":"Kedua arah putaran depan sebelum melewatkan atau menenun.","alignmentCues":["Jaga agar tongkat tetap persegi di depan dada.","Tangan bertukar dengan cara yang sama, hanya terbalik."],"props":["tongkat"],"commonMistakes":["Ujung tongkat miring ke arah Anda.","Kehilangan irama saat bertukar tangan."]},"staff-one-hand-wheel":{"name":"Putaran Roda Satu Tangan","description":"Putar tongkat di samping Anda dalam bidang roda dengan hanya satu tangan, gulirkan di bagian belakang tangan dan melalui jari-jari.","goodFor":"Kontrol satu tangan di samping tubuh: dasar dari isolasi roda dan tongkat ganda.","alignmentCues":["Tongkat melewati tepat di luar pinggul.","Siku tetap dekat dengan tulang rusuk."],"props":["tongkat"],"commonMistakes":["Ujung tongkat menyentuh kaki.","Pergelangan tangan kaku."]},"staff-wheel-pass":{"name":"Pass Roda","description":"Putaran roda yang mengganti tangan setiap setengah putaran. Setiap tangan mengambil tongkat saat berada di posisi datar, membawanya berputar, dan menyerahkannya.","goodFor":"Pergantian tangan yang halus di samping tubuh.","alignmentCues":["Tangkap saat posisi datar.","Tangan yang bebas menunggu di dekatnya."],"props":["tongkat"],"commonMistakes":["Mengambil sebelum tongkat berada di posisi datar.","Bidang bergerak tidak stabil setiap kali diserahkan."]},"staff-two-hand-helicopter":{"name":"Helikopter Dua Tangan","description":"Tongkat berputar datar di atas kepala Anda dengan kedua tangan di atasnya, melewati satu tangan di atas yang lain seperti rotor.","goodFor":"Pandangan pertama yang lembut pada bidang lantai.","alignmentCues":["Lengan rileks, tongkat tepat di atas kepala.","Tangan bertukar di depan wajah."],"props":["staff"],"commonMistakes":["Staff miring ke depan.","Bahu mengerut."]},"staff-overhead-pass":{"name":"Pass Atas","description":"Helikopter dilewatkan dari tangan ke tangan di atas kepala, masing-masing tangan membawanya setengah putaran.","goodFor":"Perubahan tangan di bidang lantai.","alignmentCues":["Lewatkan saat staff mengarah ke depan dan belakang.","Jaga siku tetap lembut."],"props":["staff"],"commonMistakes":["Mengjatuhkan staff di belakang kepala.","Mengambil terlalu dini."]},"staff-one-hand-reverse":{"name":"Putaran Terbalik Satu Tangan","description":"Putaran satu tangan ke depan berputar ke arah yang berlawanan, berguling di sisi ibu jari terlebih dahulu.","goodFor":"Kontrol satu tangan ke kedua arah.","alignmentCues":["Bidang yang sama, kecepatan yang sama, terbalik.","Jari-jari rileks saat staff berguling."],"props":["staff"],"commonMistakes":["Pergelangan tangan tegang.","Putaran melambat di satu bagian."]},"staff-reverse-helicopter":{"name":"Helikopter Terbalik","description":"Helikopter satu tangan berputar ke arah yang berlawanan di atas kepala.","goodFor":"Kedua arah di atas kepala.","alignmentCues":["Baling-baling sejajar.","Tangan tetap di atas dahi."],"props":["tongkat"],"commonMistakes":["Miring ke depan.","Lengan terlalu lurus."]},"staff-extension":{"name":"Ekstensi","description":"Pegang tongkat di dekat salah satu ujungnya dan biarkan berputar membentuk lingkaran besar di sekitar tangan Anda, yang hampir tidak bergerak. Ujung yang jauh menggambar lingkaran besar di depan Anda.","goodFor":"Bentuk besar dan gerakan pergelangan tangan yang diperlukan untuk isolasi.","alignmentCues":["Tangan adalah pusat lingkaran.","Putar pergelangan tangan, jangan ayunkan lengan."],"props":["tongkat"],"commonMistakes":["Mengayunkan dari bahu.","Lingkaran menjadi oval."]},"staff-wheel-extension":{"name":"Ekstensi Roda","description":"Perpanjangan di samping tubuh: tongkat berputar membentuk roda besar di sekitar tangan pada ketinggian pinggul.","goodFor":"Lingkaran datar roda besar.","alignmentCues":["Jaga agar lingkaran tetap di luar kaki.","Pergelangan tangan berputar, lengan tetap diam."],"props":["tongkat"],"commonMistakes":["Menyentuh kaki.","Membungkuk menjauh dari tongkat."]},"staff-floor-extension":{"name":"Ekstensi Atas Kepala","description":"Perpanjangan datar di atas kepala: tongkat berputar di sekitar tangan yang terangkat seperti bilah rotor panjang.","goodFor":"Jangkauan di atas kepala dan bentuk datar lantai yang dramatis.","alignmentCues":["Tangan di atas kepala.","Bilah tetap sejajar."],"props":["tongkat"],"commonMistakes":["Staff tenggelam ke belakang.","Lengan melayang ke depan."]},"staff-wheel-isolation":{"name":"Isolasi Roda","description":"Isolasi di samping tubuh: pusat staff tetap diam sementara tangan berputar di sekitarnya.","goodFor":"Kontrol isolasi di bidang kedua.","alignmentCues":["Pilih titik di samping pinggul Anda sebagai pusat.","Tangan bergerak dalam lingkaran kecil."],"props":["staff"],"commonMistakes":["Pusat bergerak tak menentu.","Bidang miring."]},"staff-floor-isolation":{"name":"Isolasi Atas Kepala","description":"Isolasi datar di atas kepala, staff berputar di titik tetap sementara tangan berputar.","goodFor":"Isolasi di atas kepala.","alignmentCues":["Titik tetap di atas Anda.","Lingkaran tangan kecil."],"props":["staff"],"commonMistakes":["Pusat bergeser.","Lingkaran tangan membesar."]},"staff-isolation-pass":{"name":"Pass Isolasi","description":"Isolasi yang dilewatkan antar tangan setiap setengah putaran, sehingga titik tetap tetap diam sementara tangan saling bertukar.","goodFor":"Kontrol isolasi dua tangan.","alignmentCues":["Lewati di bagian bawah lingkaran.","Jaga pusat tetap diam selama lewat."],"props":["staff"],"commonMistakes":["Pusat melompat saat lewat.","Tangan bertabrakan."]},"staff-antispin-3":{"name":"Tiga-Petal Antispin","description":"Lingkaran tangan berputar satu arah sementara tongkat berputar ke arah berlawanan, menggambar bunga dengan tiga kelopak.","goodFor":"Bunga antispin pertama.","alignmentCues":["Lingkaran tangan lambat dan bulat.","Tongkat berputar berlawanan arah."],"props":["tongkat"],"commonMistakes":["Kelopak tidak rata.","Lingkaran tangan runtuh."]},"staff-antispin-5":{"name":"Lima-Petal Antispin","description":"Bunga antispin yang lebih halus dengan lima kelopak, tangan berputar lebih lambat melawan putaran.","goodFor":"Waktu antispin yang presisi.","alignmentCues":["Hitung kelopaknya.","Tangan bergerak perlahan."],"props":["tongkat"],"commonMistakes":["Kelopak menyatu.","Terburu-buru dengan tangan."]},"staff-wheel-antispin":{"name":"Roda Antispin","description":"Bunga antispin yang digambar di samping tubuh dalam bidang roda.","goodFor":"Bunga dalam bidang kedua.","alignmentCues":["Bidang tegak.","Kelopak merata."],"props":["tongkat"],"commonMistakes":["Bidang miring.","Kelopak melayang ke depan."]},"staff-floor-antispin":{"name":"Antispin Atas","description":"Bunga antispin yang digambar rata di atas kepala.","goodFor":"Bunga di atas kepala.","alignmentCues":["Bidang datar.","Tangan di atas kepala."],"props":["tongkat"],"commonMistakes":["Miring.","Kelopak tidak rata."]},"staff-inspin-3":{"name":"Tiga-Bunga Inspin","description":"Tangan berputar dengan arah yang sama seperti putaran, tetapi lebih lambat, dan tongkat menggambar tiga kelopak yang mengarah ke dalam.","goodFor":"Bunga paling lembut untuk dipelajari.","alignmentCues":["Tangan dan tongkat berputar ke arah yang sama.","Lingkaran tangan lebar dan lambat."],"props":["tongkat"],"commonMistakes":["Tangan mempercepat untuk menyamakan dengan tongkat.","Kelopak tidak seimbang."]},"staff-inspin-4":{"name":"Empat-Petal Inspin","description":"Bunga inspin dengan empat kelopak yang mengarah ke dalam.","goodFor":"Kontrol inspin yang lebih baik.","alignmentCues":["Hitung empat kelopak.","Tangan stabil."],"props":["tongkat"],"commonMistakes":["Kelopak menyatu.","Tangan meluncur."]},"staff-wheel-inspin":{"name":"Wheel Inspin","description":"Sebuah inspin tiga kelopak yang digambar di samping tubuh.","goodFor":"Inspins di bidang roda.","alignmentCues":["Bidang tegak.","Tangan lambat."],"props":["staff"],"commonMistakes":["Miring.","Menyentuh kaki."]},"staff-reverse-figure-8":{"name":"Figure 8 Terbalik","description":"Angka 8 yang berputar ke arah lain: tongkat naik di depan dan turun di belakang di setiap sisi.","goodFor":"Kedua arah tenunan.","alignmentCues":["Silang di depan tubuh.","Setiap sisi vertikal."],"props":["staff"],"commonMistakes":["Bidang runtuh di titik silang.","Tubuh kaku."]},"staff-front-weave":{"name":"Weave Depan","description":"Sebuah spin depan yang melayang dari satu sisi tubuh ke sisi lainnya setiap putaran, dada berputar bersamanya.","goodFor":"Memindahkan spin melintasi tubuh.","alignmentCues":["Dada mengikuti staff.","Spin tetap tegak lurus terhadap Anda."],"props":["staff"],"commonMistakes":["Kaki berputar terlalu.","Bidang miring di titik silang."]},"staff-overhead-weave":{"name":"Weave Atas","description":"Sebuah helikopter dua tangan yang berayun dari satu sisi kepala ke sisi lainnya setiap putaran.","goodFor":"Menyusun di bidang lantai.","alignmentCues":["Pisau tetap sejajar sepanjang waktu.","Tubuh berputar bersama tongkat."],"props":["tongkat"],"commonMistakes":["Menurun di satu sisi.","Kepala menghalangi."]},"staff-fountain":{"name":"Air Mancur","description":"Susunan waktu terpisah di bidang roda: ujung-ujungnya menyembur ke atas dan ke sisi berlawanan seperti air dari air mancur.","goodFor":"Penyusunan waktu terpisah di samping tubuh.","alignmentCues":["Ujung-ujungnya naik di sisi yang bergantian.","Jaga agar silangannya cepat."],"props":["tongkat"],"commonMistakes":["Runtuh menjadi angka 8 datar.","Bidang miring."]},"staff-reel":{"name":"Reel","description":"Angka 8 yang berganti tangan di setiap persilangan, tongkat berputar dari satu sisi ke sisi lain.","goodFor":"Menggabungkan susunan dan lemparan.","alignmentCues":["Lepas di persilangan.","Setiap sisi tegak."],"props":["tongkat"],"commonMistakes":["Mengambil terlalu dini.","Tubuh kaku."]},"staff-wall-wheel-hybrid":{"name":"Hybrid Dinding-Roda","description":"Setiap putaran, putaran berganti antara bidang depan dan bidang roda di samping Anda, berubah saat tongkat tegak.","goodFor":"Mengubah bidang tanpa berhenti.","alignmentCues":["Ganti saat tongkat menunjuk lurus ke atas.","Pergelangan tangan berputar seperempat."],"props":["tongkat"],"commonMistakes":["Mengganti saat sejajar.","Kehilangan kecepatan saat pergantian."]},"staff-floor-wall-hybrid":{"name":"Hybrid Dinding-Lantai","description":"Putaran bergantian antara di depan Anda dan di atas kepala, berganti setiap kali tongkat berada pada posisi sejajar.","goodFor":"Menghubungkan putaran depan dan helikopter.","alignmentCues":["Ganti saat sejajar.","Angkat lengan dengan lancar."],"props":["tongkat"],"commonMistakes":["Mengganti saat vertikal.","Siku terkunci."]},"staff-floor-wheel-hybrid":{"name":"Hybrid Lantai-Roda","description":"Sebuah helikopter yang turun ke roda di samping Anda dan naik kembali setiap putaran.","goodFor":"Seluruh rangkaian perubahan bidang.","alignmentCues":["Lengan naik dan turun dengan lancar.","Bidang bersih."],"props":["tongkat"],"commonMistakes":["Bidang tengah yang kabur.","Kecepatan menurun."]},"staff-under-leg-pass":{"name":"Pass di Bawah Kaki","description":"Sebuah lewat yang menyelip di bawah kaki kanan yang terangkat setiap lewat kedua.","goodFor":"Menambahkan kaki ke gerakan lewat.","alignmentCues":["Angkat lutut tinggi ke arah tongkat.","Lipat di pinggul dengan punggung panjang dan duduk ke arah lutut yang berdiri.","Kembali ke posisi atas saat tongkat melewati kaki."],"props":["tongkat"],"commonMistakes":["Membungkuk punggung untuk meraih ke bawah alih-alih melipat di pinggul.","Meninggalkan lutut rendah sehingga tongkat harus masuk di bawahnya.","Terburu-buru melakukan lewat di bawah kaki."]},"staff-reverse-behind-back":{"name":"Pass Balik di Belakang Punggung","description":"Lewatan di belakang punggung yang bergerak ke arah berlawanan di sekitar tubuh, putaran berjalan terbalik.","goodFor":"Membawa tongkat mengelilingi tubuh dalam kedua arah.","alignmentCues":["Tangan di belakang menunggu di posisi rendah.","Pertahankan putaran di belakang."],"props":["tongkat"],"commonMistakes":["Kehilangan bidang di belakang.","Menghentikan putaran."]},"staff-fishtail":{"name":"Fishtail","description":"Tongkat bergoyang bolak-balik di atas telapak tangan terbuka seperti ikan yang mengibaskan ekornya, tidak pernah benar-benar berputar penuh.","goodFor":"Kontrol telapak tangan terbuka dan mengubah arah putaran.","alignmentCues":["Bergeser di antara ibu jari dan jari.","Goyangan pergelangan tangan kecil membalikkan ayunan."],"props":["tongkat"],"commonMistakes":["Menggenggam terlalu erat.","Ayunan menjadi terlalu besar."]},"staff-wheel-fishtail":{"name":"Fishtail Roda","description":"Fishtail di samping tubuh dalam bidang roda.","goodFor":"Fishtail dalam bidang kedua.","alignmentCues":["Bidang tegak.","Tangan terbuka."],"props":["staff"],"commonMistakes":["Miring.","Menggenggam."]},"staff-steering-wheel":{"name":"Roda Kemudi","description":"Putar staff dengan tangan terbuka, seperti memutar setir besar di depan Anda.","goodFor":"Tangan rileks dan kontak telapak tangan terbuka.","alignmentCues":["Telapak tangan rata, jari-jari lembut.","Tangan di atas."],"props":["tongkat"],"commonMistakes":["Menggenggam bukan memandu.","Siku menjalar."]},"staff-palm-spin":{"name":"Putar Telapak Tangan","description":"Seimbangkan bagian tengah staff di atas telapak tangan yang terangkat dan biarkan berputar seperti baling-baling.","goodFor":"Keseimbangan dan sentuhan ringan di atas.","alignmentCues":["Telapak tangan rata dan sejajar.","Lingkaran kecil menjaga putarannya."],"props":["tongkat"],"commonMistakes":["Telapak tangan miring.","Mendorong bukan menekan."]},"staff-hand-roll":{"name":"Hand Roll","description":"Staff berguling di atas punggung tangan terbuka dan di sekitar ibu jari tanpa digenggam.","goodFor":"Gulingan kontak pertama yang sejati.","alignmentCues":["Tangan terbuka dan lembut.","Biarkan tongkat melakukan pekerjaannya."],"props":["tongkat"],"commonMistakes":["Menutup jari-jari.","Tangan bergerak terlalu banyak."]},"staff-forearm-roll":{"name":"Roll Lengan Bawah","description":"Lepaskan putaran ke lengan bawah, biarkan tongkat berputar di atasnya, lalu ambil kembali ke putaran tangan.","goodFor":"Memindahkan putaran ke lengan dan kembali.","alignmentCues":["Lengan bawah rata dan tetap.","Buka tangan saat mendarat."],"props":["tongkat"],"commonMistakes":["Lengan bawah miring.","Mengambil terlalu cepat."]},"staff-elbow-roll":{"name":"Roll Siku","description":"Putaran bergerak ke siku yang ditekuk, berputar di sana dengan tangan terangkat, dan kembali ke tangan.","goodFor":"Kontrol kontak tingkat lanjut.","alignmentCues":["Lengan bawah tegak.","Siku tetap."],"props":["tongkat"],"commonMistakes":["Siku turun.","Tongkat tergelincir."]},"staff-shoulder-roll":{"name":"Roll Bahu","description":"Putaran roda diangkat ke atas bahu, di mana ia berputar di samping kepala sebelum jatuh kembali ke tangan.","goodFor":"Putaran kontak tinggi di tubuh.","alignmentCues":["Bahu sedikit terangkat.","Kepala miring menjauh."],"props":["tongkat"],"commonMistakes":["Kepala menghalangi.","Bahu turun."]},"staff-chest-roll":{"name":"Guling Dada","description":"Staff berguling sejajar di atas dada dari satu tangan ke tangan lainnya, lalu kembali lagi.","goodFor":"Kontak tubuh di bagian depan.","alignmentCues":["Dada terangkat.","Staff tetap sejajar."],"props":["tongkat"],"commonMistakes":["Dada kendur.","Staff miring."]},"staff-angel-roll":{"name":"Guling Malaikat","description":"Lengan terbuka lebar dan staff berguling di bagian belakang bahu serta sepanjang kedua lengan dari satu tangan ke tangan lainnya.","goodFor":"Gulingan kontak yang menarik.","alignmentCues":["Lengan sejajar, telapak tangan menghadap ke atas.","Pisau bahu ditekan."],"props":["tongkat"],"commonMistakes":["Lengan turun.","Kepala ke depan."]},"staff-toss":{"name":"Lempar Tongkat","description":"Lepaskan putaran satu tangan pada posisi sejajar, biarkan berputar sekali di udara, lalu tangkap kembali ke dalam putaran yang sama.","goodFor":"Melepas dan menangkap staff yang berputar.","alignmentCues":["Lepaskan saat sejajar.","Tangkap di tengah."],"props":["tongkat"],"commonMistakes":["Melempar ke depan.","Menangkap ujung."]},"staff-double-toss":{"name":"Lempar Ganda","description":"Lemparan lebih tinggi dengan dua putaran penuh sebelum ditangkap.","goodFor":"Kontrol ketinggian dan putaran di udara.","alignmentCues":["Lebih banyak angkat, putaran sama.","Pandangan pada bagian tengah."],"props":["tongkat"],"commonMistakes":["Terlalu banyak putaran.","Menggeser ke depan."]},"staff-flat-toss":{"name":"Lempar Datar","description":"Lempar helikopter lurus ke atas sehingga berputar datar di udara, lalu tangkap di atas kepala.","goodFor":"Lemparan di bidang lantai.","alignmentCues":["Lepas dengan level.","Tangkap di atas kepala."],"props":["tongkat"],"commonMistakes":["Miring saat dilepas.","Melempar ke belakang."]},"double-staff-same-time":{"name":"Tongkat Ganda Sama Waktu","description":"Sebuah staff pendek di setiap tangan, keduanya berputar di depan Anda dengan arah yang sama dan selaras.","goodFor":"Pola staff ganda pertama.","alignmentCues":["Staff berdampingan, satu sedikit di depan.","Kedua tangan dengan kecepatan yang sama."],"props":["dua staff pendek"],"commonMistakes":["Staff saling bertabrakan.","Satu tangan tertinggal."]},"double-staff-split-time":{"name":"Waktu Pemisahan Tongkat Ganda","description":"Kedua tongkat berputar dengan arah yang sama, tetapi satu tertinggal seperempat putaran, sehingga satu tegak saat yang lain sejajar.","goodFor":"Waktu yang terpisah antara kedua tangan.","alignmentCues":["Satu tegak, satu sejajar.","Perbedaan tetap."],"props":["dua tongkat pendek"],"commonMistakes":["Kembali ke waktu yang sama.","Benturan."]},"double-staff-wheels":{"name":"Roda Tongkat Ganda","description":"Sebuah putaran roda di setiap sisi tubuh, keduanya berputar maju bersamaan.","goodFor":"Tongkat ganda di samping tubuh.","alignmentCues":["Setiap roda di luar pinggulnya.","Kecepatan yang sama."],"props":["dua tongkat pendek"],"commonMistakes":["Roda miring ke dalam.","Tangan bergerak menjauh."]},"double-staff-split-wheels":{"name":"Roda Pemisahan Tongkat Ganda","description":"Roda di kedua sisi, berjarak seperempat putaran, seperti kaki yang berjalan.","goodFor":"Waktu terpisah di samping tubuh.","alignmentCues":["Satu atas, satu sejajar.","Perbedaan tetap."],"props":["dua tongkat pendek"],"commonMistakes":["Menyatu.","Miring."]},"double-staff-windmill":{"name":"Kincir Angin Tongkat Ganda","description":"Roda di kedua sisi berputar berlawanan arah, seperti kincir angin yang dilihat dari sisi.","goodFor":"Arah berlawanan di kedua tangan.","alignmentCues":["Satu ke depan, satu ke belakang.","Kecepatan yang sama."],"props":["dua tongkat pendek"],"commonMistakes":["Keduanya melayang ke arah yang sama.","Kecepatan tidak merata."]},"double-staff-reverse":{"name":"Tongkat Ganda Terbalik","description":"Putaran depan dengan waktu terpisah dengan kedua tongkat berjalan mundur.","goodFor":"Kedua arah dengan dua tongkat.","alignmentCues":["Pegang pergeseran.","Bidang yang sama untuk keduanya."],"props":["dua tongkat pendek"],"commonMistakes":["Benturan.","Kehilangan pergeseran."]},"double-staff-helicopters":{"name":"Helikopter Tongkat Ganda","description":"Sebuah helikopter di atas setiap bahu, keduanya berputar selangkah.","goodFor":"Tongkat ganda di atas kepala.","alignmentCues":["Bilah sejajar.","Lengan rileks."],"props":["dua tongkat pendek"],"commonMistakes":["Bilah saling bersentuhan.","Lengan lelah dan turun."]},"double-staff-isolations":{"name":"Isolasi Tongkat Ganda","description":"Isolasi di masing-masing tangan sekaligus, kedua pusat tetap berdampingan.","goodFor":"Dua isolasi sekaligus.","alignmentCues":["Dua titik tetap.","Tangan berputar bersama."],"props":["dua tongkat pendek"],"commonMistakes":["Pusat mengambang.","Satu tangan tertinggal."]},"hoop-waist":{"name":"Hoop Pinggang","description":"Berdiri dengan satu kaki sedikit di depan yang lain. Pegang hoop di bagian belakang bawah, lemparkan di sekitar pinggang Anda dan gerakkan perut ke depan dan ke belakang (bukan dalam lingkaran) setiap kali hoop melewati bagian depan Anda.","goodFor":"Keterampilan hoop pertama; membangun ritme inti.","modifications":["Gunakan hoop yang lebih besar dan lebih berat: berputar lebih lambat."],"alignmentCues":["Goyangkan ke depan dan ke belakang, bukan berputar dalam lingkaran.","Dorong hoop saat melewati perut Anda."],"props":["cincin"],"commonMistakes":["Menggerakkan pinggul seperti penari hula.","Hoop yang terlalu kecil atau ringan."]},"hoop-hand-spin":{"name":"Hand Spin","description":"Pegang hoop di depan Anda dengan tangan di dalamnya, ibu jari menghadap ke atas. Dorong hoop berputar di sekitar jaring tangan Anda, sambil menjaga hoop tetap datar di depan Anda.","goodFor":"Dasar hoop di luar tubuh.","props":["cincin"]},"hoop-chest":{"name":"Hooping Dada","description":"Angkat lengan Anda ke atas dan putar hoop di sekitar dada, goyangkan tulang rusuk ke depan dan ke belakang sambil menjaga pinggul tetap tenang.","goodFor":"Mengisolasi tulang rusuk dan membangun kontrol tubuh bagian atas.","props":["cincin"]},"hoop-lasso":{"name":"Lasso","description":"Pegang lingkaran di atas kepala dan putar secara datar di atas kepala Anda seperti lasso, lingkaran berputar di sekitar tangan Anda.","goodFor":"Kontrol bidang lantai di atas kepala.","props":["lingkaran"]},"hoop-wedgie":{"name":"Wedgie","description":"Putar lingkaran di bidang dinding dan tangkap di sela antara ibu jari dan jari, biarkan berputar dan bergoyang di sana sebelum berputar lagi.","goodFor":"Kontrol genggaman dan pegangan transisi yang halus.","props":["lingkaran"]},"hoop-knees":{"name":"Knee Hooping","description":"Dengan kaki rapat, pertahankan lingkaran berputar di sekitar lutut dengan menggerakkan lutut maju mundur secara berdenyut.","goodFor":"Hooping bagian bawah tubuh dan latihan eskalator.","props":["lingkaran"]},"hoop-pass":{"name":"Pass Tangan-ke-Tangan","description":"Putar lingkaran di depan Anda dan berikan dari satu tangan ke tangan lainnya setiap putaran, pertahankan bidang tetap.","goodFor":"Keterampilan off-body di kedua sisi.","props":["lingkaran"]},"hoop-isolation":{"name":"Isolasi Hoop","description":"Gerakkan tangan Anda di sekitar lingkaran sehingga pusatnya tetap diam di udara di depan Anda sambil lingkaran berputar di sekitar titik itu.","goodFor":"Ilusi lingkaran klasik.","props":["lingkaran"]},"hoop-escalator":{"name":"Escalator","description":"Pertahankan lingkaran berputar sambil berjalan dari pinggang ke lutut dan kembali ke dada, satu zona tubuh setiap bar.","goodFor":"Menggabungkan setiap zona hooping tubuh menjadi satu aliran.","props":["lingkaran"]},"hoop-neck":{"name":"Hooping Leher","description":"Miringkan kepala sedikit dan biarkan lingkaran ringan berputar di sekitar leher, dipandu oleh denyutan kecil kepala dan bahu.","goodFor":"Gerakan pertunjukan yang melatih denyut kecil dan presisi.","avoidIf":["Nyeri leher."],"props":["cincin"]},"hoop-reverse-waist":{"name":"Hooping Pinggang Terbalik","description":"Menggerakkan hoop di pinggang ke arah sebaliknya. Ganti posisi kaki yang di depan, lempar hoop ke arah baru, dan pertahankan denyut depan-ke-belakang yang sama.","goodFor":"Menyeimbangkan kedua arah sehingga setiap trik selanjutnya bisa dilakukan dalam kedua arah.","alignmentCues":["Ganti kaki depan Anda.","Denyut yang sama, arah baru."],"props":["cincin"],"commonMistakes":["Menggerakkan pinggul dalam lingkaran.","Menyerah pada sisi yang lemah terlalu cepat."]},"hoop-hips":{"name":"Hooping Pinggul","description":"Biarkan hoop turun dari pinggang ke tulang pinggul dan pertahankan di sana dengan denyut yang lebih rendah dan lebih kecil dari panggul.","goodFor":"Kontrol di bawah pinggang dan langkah menuju lutut.","alignmentCues":["Lutut lembut.","Denyut dari panggul, bukan perut."],"props":["cincin"],"commonMistakes":["Membiarkannya tergelincir ke bawah.","Denyut terlalu besar."]},"hoop-thighs":{"name":"Hooping Paha","description":"Dengan kaki rapat, pertahankan hoop berputar di sekitar paha atas menggunakan pantulan lutut yang cepat dan kecil.","goodFor":"Ritme kaki dan hubungan antara pinggul dan lutut.","alignmentCues":["Kaki rapat.","Pantulan cepat dan kecil."],"props":["cincin"],"commonMistakes":["Kaki terpisah.","Melompat terlalu lambat."]},"hoop-reverse-chest":{"name":"Hooping Dada Terbalik","description":"Hooping dada ke arah yang berlawanan, lengan terangkat dan tulang rusuk menggerakkan hoop.","goodFor":"Kedua arah tinggi di tubuh.","alignmentCues":["Lengan ke atas dan keluar dari jalan.","Rongga dada bergoyang dari depan ke belakang."],"props":["cincin"],"commonMistakes":["Lengan jatuh ke dalam hoop.","Pinggul melakukan pekerjaan."]},"hoop-shoulder":{"name":"Hooping Bahu","description":"Hoop berputar di sekitar bahu dan dada atas dengan lengan terangkat di atas kepala.","goodFor":"Hooping tubuh bagian atas.","alignmentCues":["Lengan lurus ke atas.","Pulsasi bahu kecil."],"props":["cincin"],"commonMistakes":["Lengan membengkok ke dalam.","Hoop tergelincir ke dada."]},"hoop-arm":{"name":"Hooping Lengan","description":"Angkat satu lengan lurus ke atas dan putar hoop di sekitar lengan bawah, tangan menggambar lingkaran kecil untuk menjaga hoop tetap berputar.","goodFor":"Hooping anggota badan dan perasaan lasso lengan terangkat.","alignmentCues":["Lengan lurus, tangan di atas kepala.","Lingkaran tangan kecil."],"props":["cincin"],"commonMistakes":["Mengelilingi seluruh lengan.","Lengan melayang ke depan."]},"hoop-elbow":{"name":"Hooping Siku","description":"Lengan diangkat ke samping, ditekuk di siku, dan lingkaran berputar di sekitar sendi siku.","goodFor":"Kontrol anggota tubuh jauh dari tubuh.","alignmentCues":["Lengan atas sejajar.","Lingkaran siku kecil."],"props":["cincin"],"commonMistakes":["Siku turun.","Lingkaran meluncur ke bahu."]},"hoop-foot":{"name":"Mengayunkan Kaki","description":"Angkat satu kaki dan putar lingkaran di sekitar kaki, kaki menggambar lingkaran kecil untuk menjaga lingkaran tetap berputar.","goodFor":"Keseimbangan dan kontrol kaki.","alignmentCues":["Kaki yang berdiri kuat.","Lingkaran kaki kecil."],"props":["cincin"],"commonMistakes":["Kehilangan keseimbangan.","Lingkaran terlalu besar."]},"hoop-full-escalator":{"name":"Escalator Penuh","description":"Naikkan lingkaran dari lutut hingga bahu dan turunkan kembali tanpa berhenti.","goodFor":"Rentang tubuh penuh dalam satu gerakan terus menerus.","alignmentCues":["Percepat denyut saat naik.","Lengan naik saat lingkaran naik."],"props":["cincin"],"commonMistakes":["Kehilangan kendali saat melompat dari pinggang ke dada.","Lengan menghalangi."]},"hoop-vortex":{"name":"Vortex","description":"Lasso hoop di atas kepala, biarkan jatuh di sekitar bahu dan dada, lalu tangkap di pinggang dalam satu turunan berputar.","goodFor":"Menghubungkan hooping di luar tubuh dan di dalam tubuh.","alignmentCues":["Jaga kecepatan lasso saat melepaskannya.","Mulai berdenyut sebelum jatuh."],"props":["cincin"],"commonMistakes":["Melepaskan terlalu lambat.","Hoop miring saat turun."]},"hoop-duck-out":{"name":"Bebek Keluar","description":"Berjalan dengan hoop dari pinggang melewati dada, ambil di atas kepala menjadi lasso, lalu turunkan ke putaran tangan di depan.","goodFor":"Keluar dari tubuh dengan bersih.","alignmentCues":["Angkat dengan tulang rusuk.","Ambil di atas kepala sesuai irama."],"props":["cincin"],"commonMistakes":["Mengambil terlalu dini.","Kehilangan kecepatan."]},"hoop-drop-in":{"name":"Masuk","description":"Dari lasso di atas kepala, lepaskan dan tangkap hoop di dada, lalu biarkan jatuh ke pinggang.","goodFor":"Cara paling sederhana dari luar tubuh kembali ke dalam tubuh.","alignmentCues":["Angkat lengan saat jatuh.","Tangkap dengan denyutan."],"props":["cincin"],"commonMistakes":["Mengjatuhkannya terlalu cepat.","Lengan menekan ke bawah."]},"hoop-chest-lift":{"name":"Angkat Dada","description":"Angkat lingkaran dari pinggang ke dada dan kembali dengan denyut yang lebih kuat.","goodFor":"Bergerak antar zona tubuh.","alignmentCues":["Denyut lebih cepat untuk naik.","Lengan naik lebih awal."],"props":["cincin"],"commonMistakes":["Kehilangan kendali saat perubahan.","Lengan turun."]},"hoop-knee-drop":{"name":"Turunkan lutut","description":"Biarkan lingkaran turun dari pinggang ke lutut, tahan di sana, lalu pantulkan kembali ke pinggang.","goodFor":"Transisi bagian bawah tubuh.","alignmentCues":["Kaki rapat untuk lutut.","Pantulan lebih besar untuk naik."],"props":["cincin"],"commonMistakes":["Kaki terpisah.","Kehilangan kendali saat naik."]},"hoop-side-spin":{"name":"Putar Samping","description":"Putaran tangan di samping tubuh dalam bidang roda, lingkaran berputar seperti roda di samping Anda.","goodFor":"Bidang roda untuk lingkaran.","alignmentCues":["Lingkaran datar di samping Anda.","Tangan setinggi pinggul."],"props":["lingkaran"],"commonMistakes":["Lingkaran mengenai kaki.","Bidang miring."]},"hoop-reverse-hand-spin":{"name":"Putar Tangan Terbalik","description":"Putaran tangan berputar ke arah berlawanan di depan Anda.","goodFor":"Kedua arah dari tubuh.","alignmentCues":["Bidang yang sama, arah lain.","Ibu jari tetap ke atas."],"props":["cincin"],"commonMistakes":["Goyang.","Memperlambat."]},"hoop-reverse-lasso":{"name":"Lasso Terbalik","description":"Lasso di atas kepala berputar ke arah yang berlawanan.","goodFor":"Kedua arah lasso.","alignmentCues":["Hoop sejajar.","Lingkaran tangan kecil."],"props":["cincin"],"commonMistakes":["Miring.","Lingkaran lengan besar."]},"hoop-palm-spin":{"name":"Putaran Telapak Tangan Atas","description":"Putaran tangan yang diangkat di atas kepala di telapak tangan terbuka, hoop berputar menghadap ke atas di atas Anda.","goodFor":"Putaran yang mencapai jauh dari tubuh ke atas.","alignmentCues":["Lengan panjang.","Telapak terbuka."],"props":["cincin"],"commonMistakes":["Hoop melayang ke belakang.","Lengan membengkok."]},"hoop-coin-flip":{"name":"Balik Koin","description":"Seimbangkan hoop tegak di ujung jari dan kibaskan sehingga berputar di tengah tegak seperti koin yang dilempar.","goodFor":"Kontrol jari yang halus dan sumbu baru.","alignmentCues":["Cincin tegak.","Kibaskan, lalu biarkan berputar."],"props":["cincin"],"commonMistakes":["Cincin terjatuh.","Menggenggam."]},"hoop-cateye":{"name":"Mata Kucing","description":"Pegang cincin di sisi tepi dan goyangkan di tengah tegaknya, sehingga dari depan terlihat menyempit dan melebar seperti mata kucing.","goodFor":"Gerakan bergoyang dan ilusi yang menarik.","alignmentCues":["Tangan tetap di tepi.","Goyangkan secara merata."],"props":["cincin"],"commonMistakes":["Tangan bergerak.","Goyangan tidak merata."]},"hoop-weave":{"name":"Tenun","description":"Putaran tangan yang meluncur dari satu sisi tubuh ke sisi lainnya, bidangnya berputar bersama dada.","goodFor":"Memindahkan putaran di sepanjang tubuh.","alignmentCues":["Dada berputar bersamanya.","Jaga agar tetap berputar."],"props":["cincin"],"commonMistakes":["Berhenti di tengah.","Miring."]},"hoop-halo":{"name":"Halo","description":"Cincin mengorbit datar di sekitar kepala, tangan terangkat menunggangi tepi di atas Anda.","goodFor":"Orbit di tingkat kepala.","alignmentCues":["Cincin sejajar di sekitar kepala.","Tangan dekat kepala."],"props":["cincin"],"commonMistakes":["Hoop tenggelam di depan.","Membungkuk."]},"hoop-toss":{"name":"Lempar Cincin","description":"Lempar putaran tangan lurus ke atas, tetap berputar, dan tangkap kembali ke dalam putaran.","goodFor":"Melepaskan dan menangkap hoop yang berputar.","alignmentCues":["Lempar lurus ke atas.","Tangkap di tempat Anda melempar."],"props":["cincin"],"commonMistakes":["Melempar ke depan.","Menangkap tepi terlambat."]},"hoop-boomerang":{"name":"Bumerang","description":"Lempar hoop ke bawah dan ke arah belakang dengan backspin sehingga berguling di lantai dan kembali ke arah Anda.","goodFor":"Backspin dan trik lantai yang menyenangkan.","alignmentCues":["Tekuk pergelangan tangan ke belakang.","Lempar rendah dan ke depan."],"props":["cincin"],"commonMistakes":["Backspin tidak cukup.","Melempar terlalu tinggi."]},"hoop-jump-through":{"name":"Lompat Melalui","description":"Pegang hoop dengan kedua tangan seperti tali lompat: ayunkan di atas kepala dan lompati saat melewati di bawah kaki Anda.","goodFor":"Ritme, koordinasi, dan latihan kardio.","alignmentCues":["Lompat kecil, lutut lentur.","Ayunkan dari pergelangan tangan."],"props":["ring"],"commonMistakes":["Melompat terlalu dini.","Ayunan lengan yang besar."]},"hoop-behind-back-pass":{"name":"Pass di Belakang Punggung","description":"Putaran tangan yang dilewatkan di belakang punggung dari satu tangan ke tangan lainnya, lalu kembali melintasi bagian depan.","goodFor":"Mengoperkan seluruh tubuh secara penuh.","alignmentCues":["Jaga agar tetap berputar di belakang.","Tangan yang menunggu meraih ke belakang."],"props":["ring"],"commonMistakes":["Ring terhenti di belakang.","Ring mengenai punggung."]},"hoop-under-leg-pass":{"name":"Pass di Bawah Kaki","description":"Operan tangan-ke-tangan yang menyelip di bawah kaki kanan yang terangkat.","goodFor":"Menambahkan kaki ke dalam operan.","alignmentCues":["Angkat lutut tinggi ke arah ring.","Lipat di pinggul dengan punggung yang panjang dan duduk di lutut yang berdiri.","Bangkit kembali saat ring keluar dari sisi lain."],"props":["ring"],"commonMistakes":["Membungkuk punggung untuk meraih ke bawah alih-alih melipat di pinggul.","Meninggalkan lutut rendah sehingga ring menangkap paha.","Terburu-buru."]},"hoop-corkscrew":{"name":"Sekrup","description":"Sebuah lasso yang berputar turun ke pinggul dan naik kembali, ring menggambar bentuk corkscrew.","goodFor":"Memindahkan lasso melalui berbagai tingkat.","alignmentCues":["Lenturkan lutut untuk turun.","Jaga agar hoop tetap sejajar."],"props":["cincin"],"commonMistakes":["Hoop miring ke bawah.","Putaran melambat."]},"hoop-barrel-roll":{"name":"Roll Barel","description":"Putaran tangan yang berputar sekali di sekitar tubuh setiap empat ketukan, hoop berputar di sekitar Anda.","goodFor":"Aliran penuh lingkaran di luar tubuh.","alignmentCues":["Putar bersama hoop.","Terus berputar sepanjang waktu."],"props":["cincin"],"commonMistakes":["Hoop tersangkut di tubuh.","Putaran terhenti di belakang."]},"hoop-chest-roll":{"name":"Roll Dada","description":"Lepaskan putaran tangan ke dada dan biarkan bergerak ke tangan lainnya.","goodFor":"Putaran hoop pertama.","alignmentCues":["Dada terangkat.","Lengan terbuka saat berputar."],"props":["cincin"],"commonMistakes":["Dada tertekuk.","Mengambil terlalu dini."]},"hoop-back-roll":{"name":"Roll Punggung","description":"Hoop bergerak melintasi bagian belakang bahu dari satu tangan ke tangan lainnya.","goodFor":"Putaran di belakang tubuh.","alignmentCues":["Pisau bahu bersama.","Kepala sedikit ke depan."],"props":["cincin"],"commonMistakes":["Membungkukkan punggung.","Hoop jatuh."]},"hoop-isopop":{"name":"Iso Pop","description":"Sebuah isolasi yang berhenti dan memantulkan hoop ke samping setiap dua ketukan sebelum melanjutkan.","goodFor":"Aksen dan berhenti dalam isolasi.","alignmentCues":["Pantulkan sesuai ketukan.","Isolasi tetap bersih di antara pantulan."],"props":["cincin"],"commonMistakes":["Pantulan terlalu besar.","Pusat mengambang."]},"hoop-wheel-isolation":{"name":"Isolasi Sisi","description":"Sebuah isolasi di samping tubuh dalam bidang roda.","goodFor":"Isolasi dalam bidang kedua.","alignmentCues":["Pusat tetap di samping Anda.","Tangan berputar di sekitarnya."],"props":["cincin"],"commonMistakes":["Pusat mengambang.","Miring."]},"hoop-floor-isolation":{"name":"Isolasi Datar","description":"Sebuah isolasi dengan hoop terletak datar, pusatnya tetap sementara tangan berputar.","goodFor":"Isolasi dalam bidang lantai.","alignmentCues":["Hoop sejajar.","Pusat tetap."],"props":["cincin"],"commonMistakes":["Miring.","Pusat bergeser."]},"doubles-hand-spins":{"name":"Putaran Tangan Ganda","description":"Satu hoop di setiap tangan, keduanya berputar di depan Anda secara cermin.","goodFor":"Gerakan ganda pertama.","alignmentCues":["Hoops berdampingan.","Sesuaikan kecepatannya."],"props":["dua hoop"],"commonMistakes":["Hoops saling bertabrakan.","Satu berkurang kecepatannya."]},"doubles-offset-spins":{"name":"Putaran Offset Ganda","description":"Putaran tangan ganda berputar ke arah yang sama, setengah putaran terpisah.","goodFor":"Waktu yang independen antara kedua tangan.","alignmentCues":["Satu naik saat yang lain turun.","Arah yang sama."],"props":["dua hoop"],"commonMistakes":["Menyinkronkan.","Bertabrakan."]},"doubles-side-spins":{"name":"Putaran Sisi Ganda","description":"Satu hoop berputar di samping setiap pinggul dalam bidang roda.","goodFor":"Doubles dalam bidang roda.","alignmentCues":["Hoops tegak.","Jauh dari kaki."],"props":["dua hoop"],"commonMistakes":["Mengenai kaki.","Miring."]},"doubles-floor-spins":{"name":"Lasso Ganda","description":"Sebuah lasso di atas kepala di masing-masing tangan, gambar cermin.","goodFor":"Doubles overhead.","alignmentCues":["Kedua tingkat.","Lingkaran tangan kecil."],"props":["dua cincin"],"commonMistakes":["Cincin saling bersentuhan.","Lengan lelah."]},"doubles-wedgies":{"name":"Kembar Wedgies","description":"Sebuah wedgie di masing-masing tangan, kedua cincin bergoyang di lipatan ibu jari.","goodFor":"Gerakan bergoyang doubles.","alignmentCues":["Ibu jari keluar.","Goyangan merata."],"props":["dua cincin"],"commonMistakes":["Cincin saling bertabrakan.","Waktu yang tidak merata."]},"doubles-coin-flips":{"name":"Pembalikan Koin Ganda","description":"Sebuah flip koin di masing-masing tangan sekaligus.","goodFor":"Kontrol jari doubles.","alignmentCues":["Kedua tegak.","Kibaskan bersama."],"props":["dua cincin"],"commonMistakes":["Terguling.","Bertabrakan."]},"doubles-isolations":{"name":"Isolasi Ganda","description":"Isolasi di masing-masing tangan, kedua pusat tetap berdampingan.","goodFor":"Dua isolasi sekaligus.","alignmentCues":["Dua pusat tetap.","Tangan berputar bersama."],"props":["dua cincin"],"commonMistakes":["Pusat bergeser.","Cincin saling bertabrakan."]},"doubles-toss":{"name":"Toss Ganda","description":"Lempar kedua cincin berputar ke atas bersamaan dan tangkap kembali ke dalam putaran ganda.","goodFor":"Lepasan ganda.","alignmentCues":["Lempar lurus ke atas bersamaan.","Tangkap di tempat yang kamu lempar."],"props":["dua cincin"],"commonMistakes":["Lemparan tidak merata.","Maju ke depan."]},"doubles-waist-and-hand":{"name":"Putaran Lingkaran Pinggang dan Tangan","description":"Pertahankan satu cincin berputar di pinggang sambil memutar cincin kedua di tangan kiri.","goodFor":"Membagi perhatian antara tubuh dan tangan.","alignmentCues":["Pinggul menjaga denyutnya.","Putaran tangan di depan cincin tubuh."],"props":["dua cincin"],"commonMistakes":["Cincin tubuh melambat.","Cincin tangan mengenai cincin tubuh."]},"doubles-chest-and-hand":{"name":"Putaran Lingkaran Dada dan Tangan","description":"Hooping dada dengan satu lengan terangkat sementara tangan lainnya memutar hoop kedua.","goodFor":"Hooping tubuh tinggi dengan trik tangan.","alignmentCues":["Satu lengan ke atas.","Rusuk menggerakkan hoop tubuh."],"props":["dua hoop"],"commonMistakes":["Lengan jatuh ke dalam hoop dada.","Kehilangan denyut."]},"doubles-waist-and-lasso":{"name":"Waist Hoop dan Lasso","description":"Hooping pinggang di bawah, lasso di atas kepala: dua hoop pada dua tingkat sekaligus.","goodFor":"Dua tingkat hooping bersamaan.","alignmentCues":["Pinggul berdenyut, tangan berputar.","Tingkat lasso di atas kepala."],"props":["dua hoop"],"commonMistakes":["Hooping tubuh jatuh.","Lasso miring."]},"poi-one-hand-spin":{"name":"Putaran Satu Tangan Poi ke Depan","description":"Satu poi berputar di depan Anda seperti jarum jam, kepala menyapu sisi Anda. Pergelangan tangan melakukan lingkaran kecil yang stabil dan tali tetap kencang.","goodFor":"Merasakan tarikan tali dan ritme satu putaran per ketukan.","alignmentCues":["Lingkaran pergelangan tangan kecil, lingkaran poi besar.","Jaga lingkaran tetap datar di depan Anda, seperti kaca jendela."],"props":["satu poi"],"commonMistakes":["Mengayunkan dari bahu.","Membiarkan lingkaran miring ke arah Anda."]},"poi-wall-spin":{"name":"Putaran Dinding Depan","description":"Kedua poi berputar ke depan bersama di depan Anda, satu di samping setiap bahu, berdampingan seperti dua roda pada poros. Gerakan poi dua pertama.","goodFor":"Dua poi seirama satu sama lain dan dengan ketukan.","alignmentCues":["Kedua kepala mencapai puncak bersamaan.","Tangan berjarak sekitar lebar bahu."],"props":["sepasang poi"],"commonMistakes":["Satu poi tertinggal dari yang lain.","Lingkaran saling menyimpang."]},"poi-reverse-wall-spin":{"name":"Putaran Dinding Mundur","description":"Spin dinding yang dibalik arah: kepala naik di luar dan turun di tengah.","goodFor":"Kedua arah sebelum menenun dan bunga.","alignmentCues":["Bidang datar yang sama, hanya arahnya yang berubah.","Pimpin lingkaran dengan bagian belakang pergelangan tangan."],"props":["sepasang poi"],"commonMistakes":["Terpeleset kembali ke spin maju.","Bidang miring ke depan."]},"poi-split-time":{"name":"Putaran Dinding Split-Time","description":"Kedua poi berputar ke arah yang sama, tetapi setengah putaran terpisah: saat satu di puncak yang lain di bawah. Ketukan setiap tenunan dibangun di atasnya.","goodFor":"Ketukan independen di kedua tangan.","alignmentCues":["Atas, bawah, atas, bawah: kepala bergantian.","Hitung setiap puncak poi sesuai ketukan dan dan."],"props":["sepasang poi"],"commonMistakes":["Kembali menyimpang ke waktu yang sama.","Tangan bergerak dengan kecepatan berbeda."]},"poi-butterfly":{"name":"Kupu-Kupu","description":"Tangan dekat satu sama lain di depan, poi berputar berlawanan arah sehingga mereka bertemu di atas dan di bawah seperti sayap kupu-kupu.","goodFor":"Ketukan berlawanan arah dan tangan dekat.","alignmentCues":["Kepala saling menyentuh di bagian atas dan bawah.","Pergelangan tangan hampir saling menyentuh."],"props":["sepasang poi"],"commonMistakes":["Kepala saling bertabrakan saat bidang saling bersilangan.","Tangan bergerak menjauh satu sama lain."]},"poi-reverse-butterfly":{"name":"Kupu-Kupu Terbalik","description":"Kupu-kupu dengan kedua sayap berputar ke arah yang berlawanan: kepala naik bersama di tengah dan turun di sisi luar.","goodFor":"Menyeimbangkan kupu-kupu dalam kedua arah.","alignmentCues":["Bertemu di tengah di bagian atas.","Tangan dekat sama seperti kupu-kupu maju."],"props":["sepasang poi"],"commonMistakes":["Kepala saling kusut di bagian atas.","Satu sayap terkulai."]},"poi-chase-the-sun":{"name":"Kejar Matahari","description":"Tangan bersama di depan dan waktu terpisah: dua kepala mengikuti satu sama lain mengelilingi satu lingkaran besar, selalu setengah putaran terpisah.","goodFor":"Waktu terpisah dengan tangan dekat, siap untuk menenun.","alignmentCues":["Satu kepala selalu berlawanan dengan yang lain.","Tangan bergerak sebagai satu."],"props":["sepasang poi"],"commonMistakes":["Kepala saling mengejar.","Tangan berpisah."]},"poi-wheels":{"name":"Roda Depan","description":"Kedua poi berputar di samping Anda seperti roda sepeda, bagian atas berputar ke depan.","goodFor":"Bidang roda, di samping tubuh.","alignmentCues":["Lingkaran berjalan sejajar dengan sisi Anda.","Siku lembut dan dekat."],"props":["sepasang poi"],"commonMistakes":["Poi mengenai kaki.","Roda menjalar ke luar."]},"poi-reverse-wheels":{"name":"Roda Mundur","description":"Roda berputar mundur di samping Anda, kepala naik di depan dan turun di belakang.","goodFor":"Kedua arah dalam bidang roda.","alignmentCues":["Roda yang sama, terbalik.","Bahu turun dan rileks."],"props":["sepasang poi"],"commonMistakes":["Roda menyimpang di belakang tubuh.","Pergelangan tangan kaku."]},"poi-fountain":{"name":"Air Mancur","description":"Roda dalam waktu terpisah: satu poi naik saat yang lain turun, seperti air dalam air mancur di samping Anda.","goodFor":"Waktu terpisah dalam bidang roda, dasar tenunan berjalan.","alignmentCues":["Satu naik, satu turun.","Jaga ritme tetap antar tangan."],"props":["sepasang poi"],"commonMistakes":["Waktu runtuh menjadi waktu yang sama.","Roda miring ke dalam."]},"poi-opposite-wheels":{"name":"Roda Berlawanan","description":"Satu roda berputar maju sementara yang lain berputar mundur. Kepala saling melewati di bagian atas dan bawah.","goodFor":"Koordinasi dengan tangan berputar berlawanan arah.","alignmentCues":["Keduanya mencapai puncak bersamaan.","Setiap tangan menjaga arahnya sendiri."],"props":["sepasang poi"],"commonMistakes":["Kedua tangan berpindah ke arah yang sama.","Satu roda menyusut."]},"poi-overhead":{"name":"Putaran Lantai Atas","description":"Kedua poi berputar datar di atas kepala Anda seperti baling-baling helikopter, sedikit lebih rendah di sisi luar saat berputar.","goodFor":"Bidang lantai dan bahu yang stabil di atas kepala.","alignmentCues":["Tangan tepat di atas kepala.","Biarkan bidang poi terbuka; jangan memaksanya."],"props":["sepasang poi"],"commonMistakes":["Bahu menganga.","Poi merosot di depan."]},"poi-low-floor":{"name":"Putaran Lantai Pinggang","description":"Bidang lantai diturunkan ke pinggul: poi berputar di tingkat pinggang di samping Anda.","goodFor":"Bidang lantai rendah yang digunakan dalam hibrida lantai-ke-dinding.","alignmentCues":["Tangan di samping pinggul.","Jaga agar lingkaran tetap sejajar."],"props":["sepasang poi"],"commonMistakes":["Poi mengenai paha.","Membungkuk ke depan."]},"poi-three-beat-weave":{"name":"Tenun Tiga Ketukan","description":"Gerakan poi khas: poi berayun dari satu sisi tubuh ke sisi lainnya, lengan saling bersilangan dan membuka saat bidang berpindah sisi.","goodFor":"Gerakan aliran yang dibangun oleh setiap pemain poi.","alignmentCues":["Putar bahu sesuai dengan tenunan.","Bidang miring sedikit ke masing-masing sisi."],"props":["sepasang poi"],"commonMistakes":["Tangan tetap di tengah.","Poi saling mengenai saat bersilangan."]},"poi-reverse-three-beat-weave":{"name":"Tenun Tiga-Ikatan Terbalik","description":"Weave tiga ketukan dengan kedua poi berputar mundur. Lengan bersilangan di atas bukan di bawah.","goodFor":"Weaving ke kedua arah.","alignmentCues":["Pola sisi ke sisi yang sama, spin terbalik.","Jaga agar tangan tetap setinggi dada."],"props":["sepasang poi"],"commonMistakes":["Kepala saling bertabrakan di bagian atas.","Weave menyusut ke satu sisi."]},"poi-two-beat-weave":{"name":"Tenun Dua-Ikatan","description":"Weave yang lebih cepat yang berganti sisi setiap ketukan. Persilangan yang lebih cepat membuatnya lebih sibuk dan lebih kompak.","goodFor":"Perubahan sisi yang cepat.","alignmentCues":["Putaran bahu yang lebih kecil dan cepat.","Bersilanglah di dekat dada."],"props":["sepasang poi"],"commonMistakes":["Kembali ke waktu tiga ketukan.","Kehilangan pembagian."]},"poi-five-beat-weave":{"name":"Tenun Lima-Ikatan","description":"Weave yang lebih panjang dan lebar: poi menghabiskan lebih banyak putaran di setiap sisi sebelum mereka kembali bersilangan.","goodFor":"Menjaga bentuk weave selama frasa yang lebih panjang.","alignmentCues":["Putaran bahu yang lebar.","Jaga agar persilangan tetap halus."],"props":["sepasang poi"],"commonMistakes":["Bersilangan terlalu dini.","Pesawat datar."]},"poi-behind-back-weave":{"name":"Weave Di Belakang Punggung","description":"Setiap pasangan ketukan, poi kanan menyapu di belakang punggung Anda dan kembali ke depan tanpa menghentikan waktu.","goodFor":"Gerakan tubuh yang mengubah tampilan pola sederhana.","alignmentCues":["Jangkau rendah di belakang pinggul.","Lihat ke depan, percaya pada waktunya."],"props":["pasangan poi"],"commonMistakes":["Poi mengenai punggung.","Poi depan berhenti sementara yang belakang bergerak."]},"poi-crossers":{"name":"Crossers","description":"Putaran dinding bersamaan saat lengan saling bersilangan di depan Anda dan membuka kembali, poi saling bertukar sisi pada setiap ketukan.","goodFor":"Saling bersilangan lengan dengan poi yang selaras.","alignmentCues":["Bersilang di pergelangan tangan.","Jaga agar kedua poi tetap selaras."],"props":["pasangan poi"],"commonMistakes":["Tali terjalin saat lengan bersilangan.","Satu poi terhenti."]},"poi-reels":{"name":"Reels","description":"Kedua poi berputar bersama di satu sisi tubuh selama satu bar, lalu berayun ke sisi lain.","goodFor":"Menggerakkan kedua poi sebagai satu kesatuan di sekitar tubuh.","alignmentCues":["Tangan tetap dekat satu sama lain.","Putar tubuh untuk menghadap ke setiap sisi."],"props":["pasangan poi"],"commonMistakes":["Tangan terpisah saat melintasi.","Melintas di luar ketukan."]},"poi-thread-the-needle":{"name":"Masukkan Jarum","description":"Arah berlawanan, waktu terpisah poi dengan lengan saling silang: satu poi menyelip melalui celah yang baru saja ditinggalkan yang lain.","goodFor":"Waktu yang tepat antara kedua tangan.","alignmentCues":["Silangkan saat celah terbuka.","Jaga lingkaran tetap rapat."],"props":["sepasang poi"],"commonMistakes":["Poi bertabrakan di tengah silang.","Waktu terlewat ke waktu yang sama."]},"poi-buzzsaw":{"name":"Gergaji","description":"Tangan ditekuk bersama dan kedua poi berputar sebagai satu, tali sisi-sisi seperti satu bilah berputar tunggal.","goodFor":"Menyelaraskan kedua poi secara tepat.","alignmentCues":["Telapak tangan bersama, pergelangan tangan rileks.","Satu lingkaran, dua kepala."],"props":["sepasang poi"],"commonMistakes":["Kepala terpisah.","Tangan bergerak menjauh."]},"poi-one-hand-isolation":{"name":"Isolasi Satu Tangan Poi","description":"Tangan berputar berlawanan arah dengan kepala dengan kecepatan yang sama, sehingga bagian tengah tali tampak terpaku di udara sementara poi berputar di sekitarnya.","goodFor":"Ilusi pertama: titik tetap di ruang angkasa.","alignmentCues":["Tangan selalu berlawanan arah dengan kepala.","Perhatikan bagian tengah tali, bukan kepala."],"props":["satu poi"],"commonMistakes":["Lingkaran tangan terlalu kecil, sehingga titiknya bergerak-gerak.","Mempercepat di bagian atas."]},"poi-isolation":{"name":"Isolasi","description":"Isolasi di kedua tangan sekaligus, dua titik tetap berdampingan di depan Anda.","goodFor":"Kontrol ilusi dua tangan.","alignmentCues":["Kedua tangan berlawanan arah dengan kepala mereka.","Siku lembut, bahu turun."],"props":["sepasang poi"],"commonMistakes":["Satu tangan kehilangan isolasi.","Titik bergerak ke depan."]},"poi-split-isolation":{"name":"Isolasi Waktu Pemisahan","description":"Isolasi setengah putaran terpisah: satu tangan ke atas sementara yang lain ke bawah, titik tetap tetap stabil.","goodFor":"Waktu isolasi dalam waktu terpisah.","alignmentCues":["Tangan bergantian atas dan bawah.","Titik tetap sejajar satu sama lain."],"props":["sepasang poi"],"commonMistakes":["Tangan sinkron.","Titik tenggelam."]},"poi-wheel-isolation":{"name":"Isolasi Roda-Pesawat","description":"Isolasi di samping Anda dalam bidang roda, titik tetap melayang di sisi Anda.","goodFor":"Isolasi dalam bidang kedua.","alignmentCues":["Titik sejajar dengan pinggul.","Tangan berputar sejajar dengan sisi Anda."],"props":["sepasang poi"],"commonMistakes":["Bidang berputar ke luar.","Tangan terlalu dekat dengan tubuh."]},"poi-extension":{"name":"Ekstensi","description":"Lengan dan tali dalam satu garis lurus, tangan berputar lebar sehingga poi menggambar lingkaran terbesar yang mungkin.","goodFor":"Bentuk besar dan terbuka serta ekstensi setengah cateye.","alignmentCues":["Jangkau dari bahu.","Tangan dan kepala sejajar dari tengah."],"props":["sepasang poi"],"commonMistakes":["Membengkokkan pergelangan tangan.","Lingkaran runtuh di bagian bawah."]},"poi-cateye":{"name":"Mata Kucing","description":"Satu tangan mengisolasi sementara yang lain memanjang. Dua jalur tumpang tindih membentuk bentuk almond, seperti mata kucing.","goodFor":"Menggabungkan dua jalur tangan yang berbeda secara bersamaan.","alignmentCues":["Tangan yang mengisolasi rapat, tangan yang memanjang lebar.","Keduanya dimulai dari atas bersamaan."],"props":["sepasang poi"],"commonMistakes":["Kedua tangan melakukan hal yang sama.","Bentuk tidak simetris."]},"poi-one-hand-antispin":{"name":"Satu-Poi Antispin","description":"Tangan berputar satu arah sementara poi berputar arah berlawanan, tiga putaran untuk setiap putaran tangan, menggambar bunga empat kelopak.","goodFor":"Perasaan antispin sebelum membuat bunga dengan dua poi.","alignmentCues":["Putaran tangan lebar dan lambat.","Setiap ujung kelopak berada di tepi putaran tangan."],"props":["satu poi"],"commonMistakes":["Poi terbalik kembali ke putaran biasa.","Kelopak tidak merata."]},"poi-antispin-flower":{"name":"Empat Kelopak Antispin","description":"Bunga antispin di kedua tangan secara bersamaan, dua bunga empat kelopak mekar berdampingan.","goodFor":"Bunga poi klasik.","alignmentCues":["Tangan berputar bersama.","Kelopak sejajar: atas, sisi, bawah, sisi."],"props":["pasangan poi"],"commonMistakes":["Satu tangan jatuh ke dalam putaran.","Bunga melayang ke depan."]},"poi-split-antispin":{"name":"Waktu Pemisahan Antispin","description":"Bunga empat kelopak dengan poi setengah putaran terpisah, kelopak satu bunga mengisi celah di bunga lainnya.","goodFor":"Waktu kelopak dalam waktu terpisah.","alignmentCues":["Tangan berlawanan arah di lingkaran masing-masing.","Kelopak saling terjalin."],"props":["pasangan poi"],"commonMistakes":["Runtuh menjadi waktu yang sama.","Tangan berputar dengan kecepatan berbeda."]},"poi-three-petal-antispin":{"name":"Tiga Petal Antispin","description":"Bunga tiga kelopak: dua antispin untuk setiap lingkaran tangan, menghasilkan bunga segitiga.","goodFor":"Mengubah jumlah kelopak dengan mengubah kecepatan tangan.","alignmentCues":["Tangan lebih cepat daripada bunga empat kelopak.","Kelopak pada tiga titik yang tersebar merata."],"props":["pasangan poi"],"commonMistakes":["Terpeleset kembali ke empat kelopak.","Lingkaran tangan menyusut."]},"poi-five-petal-antispin":{"name":"Antispin Lima Kelopak","description":"Empat antispin untuk setiap lingkaran tangan, bunga lima kelopak dengan tangan yang lebih lambat dan lebih lebar.","goodFor":"Kontrol halus rasio tangan-ke-poi.","alignmentCues":["Tangan sangat lambat.","Hitung empat putaran poi per lingkaran tangan."],"props":["pasangan poi"],"commonMistakes":["Kehilangan hitungan kelopak.","Tangan berhenti."]},"poi-wheel-antispin":{"name":"Kendaraan-Roda Antispin","description":"Bunga empat kelopak antispin di samping Anda dalam bidang roda.","goodFor":"Bunga dalam bidang roda.","alignmentCues":["Bunga sejajar dengan sisi Anda.","Tangan berputar di samping pinggul."],"props":["sepasang poi"],"commonMistakes":["Bidang miring ke dalam.","Kelopak menyentuh kaki."]},"poi-overhead-antispin":{"name":"Antispin Atas","description":"Bunga antispin datar di atas kepala, kelopaknya terbuka di atas Anda.","goodFor":"Bunga dalam bidang lantai.","alignmentCues":["Tangan tepat di atas kepala.","Kelopak tetap sejajar."],"props":["sepasang poi"],"commonMistakes":["Bunga miring ke depan.","Bahu lelah dan turun."]},"poi-antispin-and-spin":{"name":"Antispin dan Spin","description":"Tangan kanan menggambar bunga empat kelopak antispin sementara tangan kiri menjaga putaran maju biasa.","goodFor":"Kemandirian tangan: dua bentuk berbeda sekaligus.","alignmentCues":["Tangan yang berputar tetap rapat.","Tangan yang menggambar bunga berputar lebar."],"props":["sepasang poi"],"commonMistakes":["Kedua tangan meniru satu sama lain.","Poi berputar melambat."]},"poi-inspin-flower":{"name":"Empat-Petal Inspin","description":"Tangan berputar perlahan dengan arah yang sama dengan poi, lima putaran untuk setiap putaran tangan, menggambar lingkaran yang mengarah ke dalam.","goodFor":"Bunga inspin, lawan dari antispin.","alignmentCues":["Tangan dan poi berputar dengan arah yang sama.","Lingkaran kelopak menghadap ke tengah."],"props":["sepasang poi"],"commonMistakes":["Putaran tangan terlalu cepat.","Lingkaran tidak merata."]},"poi-three-petal-inspin":{"name":"Tiga-Bunga Inspin","description":"Inspin dengan empat putaran untuk setiap putaran tangan, menggambar bunga dengan tiga lingkaran.","goodFor":"Mengubah jumlah kelopak inspin.","alignmentCues":["Tangan sedikit lebih cepat dari empat kelopak.","Tiga lingkaran, tersebar merata."],"props":["sepasang poi"],"commonMistakes":["Menghitung salah.","Lingkaran memipih."]},"poi-wall-wheel-hybrid":{"name":"Hybrid Dinding–Roda","description":"Setiap putaran, poi bertukar bidang, depan lalu samping, berputar saat kepala melewati ke bawah.","goodFor":"Mengubah bidang tanpa menghentikan putaran.","alignmentCues":["Bertukar saat poi mengarah ke lantai.","Putar pergelangan tangan, bukan seluruh lengan."],"props":["sepasang poi"],"commonMistakes":["Bertukar di tengah putaran.","Poi bergoyang antar bidang."]},"poi-wheel-floor-hybrid":{"name":"Hybrid Roda–Lantai","description":"Poi bergantian berputar di samping Anda dan menyapu datar, berubah saat mereka mengarah ke depan.","goodFor":"Hybrid kedua dengan bidang horizontal.","alignmentCues":["Ganti saat poi mengarah ke depan.","Jaga agar tangan tetap setinggi pinggul."],"props":["sepasang poi"],"commonMistakes":["Poi terjatuh saat perubahan.","Kehilangan irama."]},"poi-floor-wall-hybrid":{"name":"Hybrid Lantai–Dinding","description":"Dari atas datar ke tegak di depan dan kembali lagi, berubah saat poi mengarah ke samping.","goodFor":"Menghubungkan bidang atas dan dinding.","alignmentCues":["Ganti saat poi mengarah ke samping.","Angkat dan turunkan tangan secara halus."],"props":["sepasang poi"],"commonMistakes":["Poi mengenai kepala.","Perubahan tidak merata."]},"poi-top-stall":{"name":"Mundur","description":"Poi naik ke atas, berhenti sejenak tepat di atas tangan, lalu turun kembali seperti sumbernya.","goodFor":"Berhenti dan membalik: dasar dari kombinasi stall dan hyperloop.","alignmentCues":["Angkat tangan saat poi mencapai puncak.","Biarkan tergantung, lalu arahkan kembali."],"props":["satu poi"],"commonMistakes":["Tali kendur dan terjalin.","Terburu-buru saat berhenti."]},"poi-stalls":{"name":"Stall Ganda","description":"Kedua poi berhenti bersama di bagian atas dan berbalik, berdampingan.","goodFor":"Kontrol berhenti dua tangan.","alignmentCues":["Kedua puncak pada saat yang sama.","Tangan terangkat bersama."],"props":["sepasang poi"],"commonMistakes":["Satu poi berhenti terlambat.","Poi bertabrakan saat turun."]},"poi-side-stall":{"name":"Mundur Samping","description":"Poi berhenti di sisi bukan di atas, masing-masing berhenti setinggi bahu sebelum berayun kembali.","goodFor":"Berhenti di titik yang berbeda dari lingkaran.","alignmentCues":["Berhenti saat poi mengarah ke samping.","Lengan rileks."],"props":["sepasang poi"],"commonMistakes":["Poi jatuh bukan berhenti.","Waktu bergeser."]},"poi-chasing-stalls":{"name":"Mengejar Kandang","description":"Berhenti setengah ketukan terpisah: satu poi berhenti di atas sementara yang lain masih naik.","goodFor":"Berhenti dalam waktu terpisah.","alignmentCues":["Satu berhenti, lalu yang lain.","Jaga tangan tetap setinggi dada."],"props":["sepasang poi"],"commonMistakes":["Keduanya berhenti bersama.","Terburu-buru saat berhenti kedua."]},"poi-hyperloop":{"name":"Hyperloop","description":"Berhenti di mana pesawat terbalik di bagian atas, sehingga poi berputar dan turun di sisi lain lingkaran.","goodFor":"Loop tiga dimensi dari posisi stall.","alignmentCues":["Putar pergelangan tangan di bagian atas stall.","Jaga agar tali tetap kencang."],"props":["satu poi"],"commonMistakes":["Membalik sebelum poi mencapai puncak.","Tali kendur."]},"poi-arm-wrap":{"name":"Sarung Lengan","description":"Poi melilit lengan lain yang diangkat ke depan, berputar lebih cepat dengan tali yang lebih pendek, lalu melepaskan kembali ke lingkaran penuh.","goodFor":"Lilitan pertama, dan bagaimana lilitan mempercepat poi.","alignmentCues":["Pegang lengan penyangga tetap dan sejajar.","Jaga agar tangan yang berputar berada di belakang penyangga."],"props":["satu poi"],"commonMistakes":["Lengan penyangga bergerak.","Melepaskan lilitan dengan cara yang salah."]},"poi-leg-wrap":{"name":"Kaki Melingkar","description":"Angkat lutut dan biarkan poi melilit paha, lalu turunkan kaki saat melepaskan lilitan.","goodFor":"Lilitan pada tubuh.","alignmentCues":["Lutut dinaikkan saat poi tiba.","Tetap tegak pada kaki yang berdiri."],"props":["satu poi"],"commonMistakes":["Mengangkat lutut terlambat.","Kehilangan keseimbangan."]},"poi-neck-wrap":{"name":"Leher Melingkar","description":"Dari putaran di atas kepala, turunkan tangan sehingga poi melilit bagian belakang leher dan melepaskan kembali ke atas kepala.","goodFor":"Lilitan yang mencolok yang menghubungkan putaran di atas kepala.","avoidIf":["Gunakan poi latihan dengan kepala lembut; jangan pernah belajar wrap leher dengan api."],"alignmentCues":["Dagu sejajar, leher panjang.","Pandu tali ke dasar leher."],"props":["satu poi"],"commonMistakes":["Membungkus di kepala.","Tali terlalu longgar."]},"poi-cord-wrap":{"name":"Tali Melingkar","description":"Dari posisi kupu-kupu, kedua tali melilit satu sama lain di bagian bawah, kepala berputar dengan tali pendek sebelum terlepas.","goodFor":"Lilitan di antara dua poi.","alignmentCues":["Temukan tali di bagian bawah kupu-kupu.","Jaga tangan tetap diam saat mereka melilit."],"props":["pasangan poi"],"commonMistakes":["Tangan menarik terpisah.","Lilitan kusut."]},"poi-toss":{"name":"Lempar Poi","description":"Lepaskan pegangan saat poi berayun ke atas. Ia berputar di udara dan Anda menangkap pegangan saat kembali.","goodFor":"Lepas dan tangkap.","avoidIf":["Latih lemparan dengan poi lembut dan ruang di sekitar Anda."],"alignmentCues":["Lepaskan saat ayunan ke atas.","Perhatikan pegangan, bukan kepala."],"props":["satu poi"],"commonMistakes":["Melepaskan terlambat.","Menangkap tali bukan pegangan."]},"poi-high-toss":{"name":"Toss Tinggi","description":"Lemparan lebih tinggi dengan putaran tambahan di udara sebelum ditangkap.","goodFor":"Tosan yang lebih besar dengan putaran lebih banyak.","alignmentCues":["Dorongan yang lebih kuat saat melepaskan.","Tangkap saat pegangan berputar."],"props":["satu poi"],"commonMistakes":["Tosan melayang ke depan.","Menangkap secara tergesa-gesa."]},"poi-double-toss":{"name":"Toss Ganda","description":"Kedua poi dilempar secara terpisah, satu demi satu, lalu ditangkap kembali ke dalam putaran.","goodFor":"Waktu lempar dengan dua tangan.","alignmentCues":["Lepaskan satu, lalu yang lain.","Tangkap dalam urutan yang sama."],"props":["sepasang poi"],"commonMistakes":["Melepaskan keduanya sekaligus.","Memperhatikan satu poi dan kehilangan yang lain."]},"shake-out":{"name":"Kocok Keluar","description":"Letakkan prop dan goyangkan tangan serta lengan bawah. Biarkan bahu turun.","goodFor":"Pengaturan ulang singkat antara sesi keras."},"breathe":{"name":"Istirahat dan Reset","description":"Letakkan prop, berdiri santai dan biarkan lengan tergantung lepas. Luangkan waktu sejenak sebelum sesi berikutnya.","goodFor":"Menurunkan detak jantung dan menghilangkan frustrasi setelah terjatuh."}}`),t={"warmup-mobility":{name:`Pemanasan Alir`,description:`Pergelangan tangan, bahu, tulang belakang, dan pinggul dilonggarkan dengan irama yang stabil. Gunakan sebelum sesi prop apa pun.`,focus:`Pemanasan · Mobilitas`},"first-throws":{name:`Lemparan Pertama`,description:`Satu bola melengkung dari tangan ke tangan pada ketinggian mata, lalu pertukaran dua bola yang menjadi dasar dari setiap pola.`,focus:`Juggling · fondasi`},"cascade-builder":{name:`Pembuat cascade`,description:`Pertukaran dua bola berurutan hingga bola ketiga bergabung: lari cascade pendek, reset, lari lagi.`,focus:`Juggling · fondasi`},"juggling-tempo-ladder":{name:`Tangga tempo juggling`,description:`Cascade pada tiga tempo, beberapa ketukan lebih cepat setiap tingkat. Lontaran lebih rendah untuk tingkat yang cepat.`,focus:`Juggling · tempo`},"siteswap-sampler":{name:`Sampler siteswap`,description:`Cascade masuk ke 423, 441 dan 531, dengan cascade terbalik dan shower sebagai pembersih mulut. Setiap pola dimulai dan diakhiri dengan cascade.`,focus:`Juggling · pola`},"four-ball-session":{name:`Sesi empat bola`,description:`Dua di satu tangan untuk setiap sisi, air mancur empat bola, lalu air mancur sinkron.`,focus:`Juggling · angka`},"juggling-combo-flow":{name:`Alur kombinasi juggling`,description:`Satu rangkaian panjang yang mengalir: cascade, cascade terbalik, Mills mess dan siteswap disusun menjadi satu bagian musik.`,focus:`Juggling · kombinasi`},"cascade-tricks":{name:`Trik cascade`,description:`Tennis, setengah shower dan cakar, masing-masing dijatuhkan ke dalam cascade yang sedang berjalan dan keluar lagi.`,focus:`Juggling · variasi`},"juggling-body-throws":{name:`Lemparan tubuh`,description:`Di bawah kaki, di belakang punggung, potongan dan penguin: cascade dilempar di sekitar tubuh.`,focus:`Juggling · lemparan tubuh`},"sync-shapes":{name:`Bentuk sinkron`,description:`Kolom, salib pelangi, kotak dan yo-yo: tiga bola dilempar dua per dua.`,focus:`Juggling · pola sinkron`},"club-foundations":{name:`Dasar klub`,description:`Putaran tunggal, pertukaran dua klub, dan tiga-klub cascade, dengan flats untuk menyelesaikan.`,focus:`Juggling · klub`},"passing-with-a-partner":{name:`Melempar dengan pasangan`,description:`Hadapkan diri Anda ke arah pasangan dan lempar: satu bola melintasi, lalu masing-masing dua, lalu enam hitungan, empat hitungan, dan dua hitungan.`,focus:`Juggling · passing`},"club-passing-session":{name:`Pelemparan klub`,description:`Club empat hitungan untuk pemanasan, dua hitungan dan tiga hitungan untuk ritme, lalu lemparan ganda.`,focus:`Juggling · passing klub`},"hoop-juggling-session":{name:`Juggling hoop`,description:`Cincin ukuran penuh dilempar tepi: lemparan tunggal, pertukaran, cascade, dan balikannya.`,focus:`Juggling · cincin`},"staff-first-spins":{name:`Putaran tongkat pertama`,description:`Putaran roda di samping tubuh, lalu putaran depan. Putaran lambat dan merata, satu per ketukan.`,focus:`Staff · fondasi`},"staff-foundations":{name:`Dasar tongkat`,description:`Putaran roda, putaran depan, angka 8, dan lemparan tangan-ke-tangan yang dihubungkan sesuai ketukan.`,focus:`Staff · fondasi`},"staff-flow-weave":{name:`Tenun aliran tongkat`,description:`Angka 8 ke kupu-kupu, putaran satu tangan, dan helikopter, disambungkan agar staf tidak pernah berhenti.`,focus:`Staff · aliran`},"staff-isolation-lab":{name:`Laboratorium isolasi tongkat`,description:`Isolasi dan bunga antispin dengan tempo lebih lambat, dengan lemparan di belakang punggung di antaranya.`,focus:`Staff · teknis`},"staff-advanced-flow":{name:`Aliran tongkat lanjutan`,description:`Kosakata lengkap dalam satu bagian panjang: jalinan, pembungkusan, isolasi, dan putaran leher.`,focus:`Tongkat · aliran`},"staff-both-ways":{name:`Tongkat kedua arah`,description:`Setiap putaran dasar maju lalu mundur, ditambah helikopter dua tangan di atas kepala.`,focus:`Tongkat · arah dan bidang`},"staff-contact-lab":{name:`Laboratorium kontak tongkat`,description:`Kontak tangan terbuka dan tubuh: fishtail, roda kemudi, putaran tangan dan lengan bawah, serta lemparan untuk menyelesaikan.`,focus:`Tongkat · kontak`},"double-staff-session":{name:`Sesi tongkat ganda`,description:`Tongkat pendek di masing-masing tangan: waktu bersamaan, waktu terpisah, roda, dan roda terpisah.`,focus:`Tongkat · dua tongkat`},"hoop-first-spins":{name:`Putaran lingkaran pertama`,description:`Mengelilingi pinggang dengan dorongan depan-belakang, lalu memutar hoop di sekitar satu tangan.`,focus:`Hoop · dasar`},"hoop-body-flow":{name:`Aliran lingkaran pada tubuh`,description:`Memindahkan hoop ke dada dan turun ke lutut lalu kembali ke pinggang, tanpa berhenti.`,focus:`Hoop · di tubuh`},"hoop-off-body":{name:`Lingkaran di luar tubuh`,description:`Putaran tangan, lasso, wedgies, dan passing, diakhiri dengan isolasi yang membuat hoop tetap diam di udara.`,focus:`Hoop · di luar tubuh`},"hoop-full-flow":{name:`Aliran lingkaran penuh`,description:`Di tubuh dan di luar tubuh bersamaan: eskalator, mengelilingi leher, dan trik di luar tubuh dalam satu aliran panjang.`,focus:`Hoop · aliran`},"hoop-body-zones":{name:`Zona tubuh lingkaran`,description:`Pinggang kedua arah, lalu pinggul, paha, dan dada, mengangkat dan menurunkan hoop antar zona.`,focus:`Hoop · pada tubuh`},"hoop-tricks-session":{name:`Trik hoop`,description:`Putaran sisi, flip koin, tenun, lemparan, dan kembali ke tubuh.`,focus:`Hoop · dari tubuh`},"hoop-doubles-session":{name:`Hoop ganda`,description:`Dua hoop: putaran tangan cermin dan bergeser, putaran sisi, dan hoop pinggang dengan putaran tangan.`,focus:`Hoop · ganda`},"poi-foundations":{name:`Dasar poi`,description:`Satu poi, lalu dua: putaran dinding ke depan dan ke belakang, roda di samping Anda, waktu terpisah, dan kupu-kupu.`,focus:`Poi · putaran pertama`},"poi-weave-session":{name:`Tenun poi`,description:`Pembagian waktu menjadi tenun tiga ketukan, kedua arah, lalu tenun dua ketukan, gulungan, dan penyeberangan.`,focus:`Poi · tenun`},"poi-flower-lab":{name:`Lab bunga poi`,description:`Ekstensi dan isolasi, lalu antispin dengan satu poi dan dua, serta bunga inspin untuk menyelesaikan.`,focus:`Poi · bunga`},"daily-mixed-flow":{name:`Aliran campuran harian`,description:`Sedikit dari setiap seni: cascade, putaran tongkat, dan hooping, dengan gerakan mobilitas di antara alat.`,focus:`Campuran · latihan`},"poi-symmetry-lab":{name:`Poi symmetry lab`,description:`Visit vertical-axis (together-opposite), central-point (split-same) and horizontal-axis (split-opposite) patterns with catalog moves.`,focus:`Poi · geometry`},"poi-hybrid-session":{name:`Poi hybrid session`,description:`Cateye, antispin-and-spin and plane hybrids with hide-one-prop study in mind.`,focus:`Poi · hybrids`},"poi-weave-degrees":{name:`Poi weave degrees`,description:`Split foundation into three-beat and five-beat weaves — try degree-of-twist cues in Settings.`,focus:`Poi · weaves`},"staff-symmetry-lab":{name:`Staff symmetry lab`,description:`Together-opposite butterfly, split-same fountain and figure-8 weave — three cells of the timing map on one staff.`,focus:`Staff · geometry`},"staff-flower-lab":{name:`Staff flower lab`,description:`Extensions into isolations, then four-petal antispin and a slower three-petal antispin.`,focus:`Staff · flowers`},"staff-contact-session":{name:`Staff contact session`,description:`Fishtail into hand and forearm rolls, angel roll, then a calm held spin to finish.`,focus:`Staff · contact`},"hoop-plane-lab":{name:`Hoop plane lab`,description:`Visit on-body floor work, off-body wall spins and a horizontal lasso so the plane map sticks.`,focus:`Hoop · planes`},"hoop-isolation-session":{name:`Hoop isolation session`,description:`Hand spin into isolation and cateye, then weave and pass to reconnect with travel.`,focus:`Hoop · isolations`}},n=JSON.parse(`{"start-here":{"title":"Mulai di sini: minggu pertama aliran Anda","summary":"Pilih satu alat, latih sepuluh menit sehari sesuai irama, dan biarkan pohon pembukaan memberi tahu Anda apa yang selanjutnya.","imageAlt":"Figur 3D melempar bola juggling tunggal dari tangan ke tangan","body":["Seni aliran terlihat seperti sihir dari luar: bola menggantung di udara, tongkat berputar menjadi kabur, hoop mengorbit penari yang hampir tidak bergerak. Dari dalam, mereka adalah tumpukan keterampilan kecil, masing-masing bisa dipelajari dalam satu sore, ditumpuk hingga tumpukan itu terlihat mudah. Minggu pertama Anda adalah tentang bagian bawah tumpukan itu.","Pilih satu alat untuk memulai. Juggling mengajarkan waktu dan koordinasi tangan-mata; tongkat mengajarkan bidang dan perubahan tangan yang halus; hoop mengajarkan ritme melalui seluruh tubuh. Anda bisa mempelajari ketiganya, tetapi satu per satu menjaga perhatian Anda pada tempat kemajuan terjadi. Pohon Rewards menampilkan setiap gerakan untuk setiap seni, dari lemparan atau putaran pertama hingga pola lanjutan, dan membuka yang berikutnya saat Anda menguasai apa yang mereka bangun.","Latih sedikit dan sering. Sepuluh menit fokus sehari mengalahkan satu jam pada hari Minggu, karena koordinasi terkonsolidasi di antara sesi, terutama selama tidur. Rutinitas pendek dari halaman Routines, pemanasan, dan beberapa langkah terhitung dari gerakan Anda saat ini adalah latihan lengkap.","Berlatih sesuai irama sejak hari pertama. Setiap gerakan dalam SynthFlow dihitung dalam bar dengan tempo, dengan musik atau perkusi yang dihasilkan yang sesuai. Irama memberi Anda sesuatu untuk dipegang ketika prop tidak bekerja sama, dan membuat kemajuan dapat diukur: jalur bersih dengan 90 BPM minggu ini, 100 minggu depan.","Harapkan kegagalan. Semua orang mengalami kegagalan, termasuk profesional saat latihan. Kegagalan memberi tahu Anda lemparan atau tangkapan mana yang perlu diperhatikan; itu tidak berkaitan dengan bakat. Angkat propnya, tunggu downbeat berikutnya, dan coba lagi. Pada akhir minggu Anda akan memiliki gerakan yang bisa Anda lakukan tanpa berpikir, dan saat itulah aliran dimulai."]},"counting-and-the-beat":{"title":"Hitungan, bar, dan irama","summary":"Mengapa setiap gerakan dihitung dalam bar dengan tempo, dan cara mengunci lemparan dan putaran Anda ke musik.","imageAlt":"Figur 3D memainkan tiga bola dengan tumpukan tiga bola dengan busur di atas tangan","body":["Musik terdiri dari ketukan yang dikelompokkan dalam bar, biasanya empat ketukan per bar. Gerakan Flow terdiri dari siklus: satu lemparan dari setiap tangan, setengah putaran staf, satu orbit hoop. Ketika siklus mendarat pada ketukan, gerakan dan musik menjadi satu. Itulah sebabnya SynthFlow mengukur setiap langkah rutinitas dalam bar bukan detik, dan mengapa setiap gerakan menyebutkan berapa banyak ketukan yang dibutuhkan satu siklus.","Dalam tumpukan tiga bola, setiap lemparan jatuh pada ketukan, bergantian kanan dan kiri. Dalam putaran depan staf, satu setengah putaran biasanya memakan satu ketukan. Berputar di pinggang umumnya satu orbit per ketukan pada tempo santai. Hitungan dalam pemain menyebutkan apa yang terjadi pada setiap ketukan, dan figur 3D bergerak tepat pada jam yang sama dengan audio, sehingga Anda bisa menirunya tepat waktu.","Tempo diukur dalam ketukan per menit (BPM). Setiap gerakan memiliki kisaran yang nyaman: cukup lambat agar tetap bersih, cukup cepat agar prop mempertahankan momentumnya. Di bawah kisaran, prop berputar akan macet dan lemparan akan terlalu tinggi sehingga melayang; di atasnya Anda mulai terburu-buru dan menjatuhkan. Pembuat akan memperingatkan Anda ketika langkah berada di luar kisaran gerakan tersebut.","Mulai setiap langkah pada downbeat, \\"satu\\" dari bar. Hitungan masuk memberi Anda satu bar untuk membuat prop bergerak sebelum bar yang dihitung dimulai. Jika Anda kehilangan irama, jangan mengejarnya: berhenti, dengarkan \\"satu\\" berikutnya, dan kembali lagi. Musisi menyebutnya menemukan bagian atas bar, dan ini juga berlaku untuk seniman flow.","Menghitung dengan suara selama beberapa sesi membantu lebih dari yang terlihat. Mengucapkan \\"satu, dua, tiga, empat\\" saat Anda berjuggling menghubungkan ritme dengan napas dan suara Anda, sehingga tetap bertahan saat pola menjadi sulit. Setelah hitungan hidup dalam tubuh Anda, matikan hitungan yang diucapkan di Pengaturan dan biarkan musik membawa Anda."]},"tempo-ladders":{"title":"Tangga tempo: lambat itu lancar, lancar itu cepat","summary":"Naik beberapa BPM sekaligus dari tempo yang bisa Anda lakukan dengan bersih, dan turun segera saat bentuknya rusak.","imageAlt":"Figur 3D memutar tongkat di depan tubuh dalam bidang dinding","body":["Tangga tempo adalah gerakan yang sama diulang pada tempo yang meningkat: delapan bar pada 80 BPM, delapan pada 88, delapan pada 96, dan seterusnya. Ini adalah cara paling andal untuk membuat gerakan lebih cepat tanpa membuatnya berantakan, dan beberapa rutinitas bawaan dibangun di sekitarnya.","Mulai dari tingkat yang bisa Anda lakukan dengan bersih, meskipun terasa terlalu mudah. Tujuan dari tingkat bawah bukanlah tantangan; melainkan berlatih bentuk yang benar sehingga bentuk itulah yang mempercepat. Naikkan sedikit, sekitar lima hingga sepuluh persen. Lonjakan besar mengubah gerakan: lemparan menjadi lebih rendah, putaran menjadi lebih dangkal, dan Anda akhirnya berlatih trik yang berbeda.","Berhenti naik saat bentuknya rusak, bukan saat Anda menjatuhkan. Perhatikan tanda-tanda awal: puncak menjadi tidak rata, tongkat menyimpang dari bidangnya, atau lingkaran naik atau turun. Itulah petunjuk untuk turun satu tingkat dan lakukan lagi. Menyelesaikan tangga dengan jalur bersih pada tempo sedikit di bawah batas Anda mengajarkan tubuh Anda tempo itu; menyelesaikan dengan kegagalan mengajarkan kegagalan.","Tempo lambat lebih sulit dari yang terlihat untuk alat putar, karena alat memiliki momentum lebih sedikit untuk membawanya melalui. Jika tongkat atau lingkaran macet di bagian bawah jangkauannya, pertahankan tempo dan perbesar gerakan sedikit, atau lakukan setengah waktu dengan musik: satu siklus setiap dua ketukan.","Lacak tempo bersih tertinggi Anda untuk setiap gerakan di Kemajuan. Melihat angka itu naik perlahan selama berminggu-minggu adalah motivasi yang baik, dan juga menunjukkan kapan suatu gerakan telah mencapai titik datar dan membutuhkan latihan yang berbeda daripada lebih banyak yang sama."]},"siteswap-notation":{"title":"Siteswap: juggling ditulis sebagai angka","summary":"Setiap angka menunjukkan berapa ketukan kemudian bola dilempar lagi; angka ganjil saling melintasi, angka genap tetap di tempat, dan rata-ratanya adalah jumlah bola.","imageAlt":"Figur 3D berjuggling siteswap 441 dengan dua lemparan tinggi dan satu gerakan cepat","body":["Pola juggling sulit dijelaskan dengan kata-kata dan mudah dijelaskan dengan angka. Siteswap, yang dikembangkan secara independen pada pertengahan 1980-an oleh para juggling di Cambridge, Caltech, dan Santa Cruz, menuliskan pola sebagai urutan angka yang berulang. Ini adalah cara para juggling berbagi pola, memeriksa apakah sebuah ide bisa berhasil, dan menemukan trik yang belum pernah dicoba siapa pun. SynthFlow menggunakannya untuk menganimasikan setiap pola juggling dari mesin yang sama.","Bayangkan tangan melempar secara bergantian pada setiap ketukan: kanan, kiri, kanan, kiri. Setiap angka dalam siteswap menyatakan berapa ketukan dari sekarang bola yang dilempar pada ketukan ini akan dilempar lagi. Angka 3 kembali tiga ketukan kemudian; karena tiga ganjil, bola mendarat di tangan yang lain. Sebuah cascade tiga bola hanyalah 3, 3, 3, 3 selamanya, ditulis sederhana sebagai 3. Angka 4 kembali empat ketukan kemudian di tangan yang sama, yang merupakan fountain empat bola.","Angka-angka kecil memiliki makna khusus. Angka 2 kembali ke tangan yang sama dua ketukan kemudian, yang dalam praktiknya berarti memegang bola sejenak. Angka 1 melintas ke tangan yang lain pada ketukan berikutnya, sebuah lemparan cepat langsung melintasi. Angka 0 adalah tangan kosong. Angka yang lebih besar adalah lemparan yang lebih tinggi: angka 5 adalah lemparan lintas yang tinggi.","Baca pola digit demi digit. Dalam 441, dua lemparan tetap di sisi masing-masing sementara bola ketiga melintas di bawahnya. Dalam 531, lemparan lintas tinggi naik sementara lemparan cascade dan lemparan cepat menjaga dua bola lainnya tetap bergerak. Dalam 423, lemparan setinggi fountain, bola yang dipegang, dan lemparan cascade bergantian.","Teorema rata-rata memberi tahu Anda berapa banyak bola yang dibutuhkan suatu pola: jumlahkan angka-angkanya dan bagi dengan jumlahnya. 441 berjumlah 9 dalam tiga digit, jadi tiga bola. Jika rata-ratanya bukan bilangan bulat, urutan tersebut tidak dapat dijuggling. Pemeriksaan kedua adalah bahwa tidak boleh ada dua bola yang mendarat di tangan yang sama pada ketukan yang sama, yang merupakan cara para juggling mendeteksi pola yang tidak mungkin sebelum mencobanya.","Siteswap juga memiliki notasi untuk kedua tangan melempar bersamaan, ditulis dalam tanda kurung seperti (4,4), dan untuk melempar dua bola dari satu tangan sekaligus, ditulis dalam tanda kurung siku. Anda tidak memerlukan semua ini untuk juggling dengan baik, tetapi begitu angka-angka itu terasa, setiap nama pola baru mulai menjelaskan dirinya sendiri. Buka glosarium Flow untuk angka-angka individu."]},"passing-basics":{"title":"Dasar-dasar passing: juggling dengan pasangan","summary":"Hadapkan diri ke arah pasangan, lempar tangan kanan bersamaan, lempar langsung ke tangan kiri mereka, dan hitung: enam-ketukan, empat-ketukan, dua-ketukan.","imageAlt":"Dua penjuggling 3D saling berhadapan, melempar bola langsung di antara mereka","body":["Passing adalah juggling bersama orang lain. Dua juggler berdiri berhadapan, masing-masing menjalankan cascade, dan sesekali salah satu lemparan dilempar ke arah partner bukan ke diri sendiri. Ini adalah salah satu hal yang paling sosial dalam juggling: passing klub adalah cara banyak juggler menghabiskan malam festival, dan ini mengubah latihan menjadi percakapan.","Berdiri sekitar dua setengah meter terpisah untuk bola, sedikit lebih jauh untuk klub. Kalian berdua mulai juggling pada hitungan yang sama, tangan kanan melempar bersamaan. Pass standar adalah lurus: lepas dari tangan kanan Anda dan mendarat di tangan kiri partner Anda, tepat di seberang Anda. Ini tidak dilempar ke wajah mereka. Arahkan ke pinggul kiri mereka dan berikan busur yang mencapai puncak sedikit di atas tinggi kepala, di tengah-tengah kalian berdua.","Pola passing dinamai berdasarkan seberapa sering Anda melakukan passing. Dalam enam hitungan Anda melakukan passing setiap lemparan keenam, yang menyisakan lima lemparan sendiri di antaranya untuk menetap. Dalam empat hitungan, pemanasan standar, Anda melakukan passing pada setiap lemparan tangan kanan: passing, sendiri, sendiri, sendiri. Dalam dua hitungan setiap lemparan tangan kanan adalah passing dan setiap tangan kiri adalah sendiri. Dalam tiga hitungan passing bergantian tangan, sehingga Anda belajar melakukan passing dari tangan kiri juga. Ultimates, atau satu hitungan, membuat setiap lemparan menjadi passing.","Hitung bersama-sama dengan suara keras pada awalnya. “Pass, dua, tiga, empat” membuat Anda berada pada irama yang sama, dan saat salah satu dari Anda menyimpang, passing tidak akan tiba tepat waktu. Suara hitungan SynthFlow mengatakan “pass” pada saat passing Anda dan “self” pada lemparan lainnya pada irama, sehingga Anda bisa berlatih waktu sendiri sementara partner di layar juggling bersama Anda.","Mulai dengan satu bola. Lempar ke arah lawan, biarkan partner Anda menyerahkannya dari tangan kiri ke tangan kanan dan lemparkan kembali. Kemudian ambil masing-masing dua bola dan lakukan passing tangan kanan bersamaan, serahkan bola yang masuk dari tangan kiri ke tangan kanan. Baru kemudian tambahkan cascade. Sebagian besar kejatuhan passing disebabkan oleh passing yang terlalu panjang atau terlalu datar, dan keduanya lebih mudah diperbaiki dengan satu bola daripada dengan enam.","Dalam notasi SynthFlow, pola passing mencantumkan lemparan Anda dan lemparan partner Anda, satu per ketukan, dengan p menandakan passing: empat hitungan adalah <3p 3 3 3|3p 3 3 3>. Angka-angka memiliki arti yang sama seperti dalam siteswap. 4p adalah passing ganda yang mendarat satu ketukan kemudian, yang merupakan cara pola tujuh klub dibangun."]},"planes-and-geometry":{"title":"Bidang: dinding, roda, dan lantai","summary":"Prop berputar hidup dalam bidang datar; menjaga bidang tetap bersih adalah sebagian besar yang membuat staf atau hoop terlihat tajam.","imageAlt":"Gambar 3D menenun staf dalam bentuk angka 8 di kedua sisi tubuh","body":["Sebuah tongkat atau hoop yang berputar menggambar permukaan datar, yang disebut bidangnya. Seniman aliran menggambarkan tiga bidang dasar relatif terhadap tubuh. Bidang dinding ada di depan Anda, seperti selembar kaca yang bisa Anda tekan dengan telapak tangan. Bidang roda ada di samping Anda, seperti roda gerobak yang berputar di sisi Anda. Bidang lantai adalah horizontal, sejajar dengan tanah, seperti helikopter di atas kepala atau lasso.","Bidang yang bersih adalah apa yang dibaca penonton sebagai keterampilan. Sebuah tongkat yang goyah keluar dari bidangnya terlihat tidak yakin meskipun tidak pernah jatuh; sebuah hoop yang tetap rata sempurna selama operan terlihat mudah. Sebagian besar latihan awal secara diam-diam berkaitan dengan bidang: menjaga pergelangan tangan agar tidak berputar, menjaga siku agar tidak menjalar, dan membiarkan bahu menggerakkan alat bukan tangan.","Banyak trik didefinisikan oleh perubahan bidang. Tenunan angka-8 memindahkan tongkat dari bidang roda di satu sisi ke bidang roda di sisi lain. Kupu-kupu melipatnya di belakang bahu dan kembali. Eskalator menggerakkan hoop naik turun di tubuh sambil bidangnya tetap sejajar. Memahami di mana setiap gerakan dimulai dan berakhir di ruang adalah cara Anda menghubungkannya menjadi aliran.","Pemirsa 3D dapat menggambar bidang saat Anda berlatih. Nyalakan saat belajar putaran baru dan bandingkan: apakah tongkat Anda miring ke arah Anda di bagian atas? Apakah hoop menurun di bagian depan? Cermin atau kamera ponsel menunjukkan hal yang sama. Menonton dari sisi sangat berguna untuk gerakan bidang dinding, karena kemiringan tidak terlihat dari depan.","Bidang juga membantu keamanan dan ruang. Sebelum sesi, periksa bahwa setiap bidang yang akan Anda gunakan bebas: dinding di depan, dinding di samping Anda, dan langit-langit di atas untuk gerakan bidang lantai dan di atas kepala. Bidang yang bersih tanpa halangan adalah bidang yang percaya diri."]},"spin-and-antispin":{"title":"Putar, putar berlawanan arah, dan isolasi","summary":"Bagaimana prop berputar dibandingkan dengan tangan memberi tiga keluarga gerakan: putar, anti-putar, dan isolasi.","imageAlt":"Gambar 3D menarik bunga empat kelopak anti-putar dengan tongkat","body":["Saat Anda menggerakkan prop berputar dalam lingkaran, dua rotasi terjadi sekaligus: tangan Anda bergerak dalam lingkaran, dan prop berputar di sekitar pusatnya sendiri. Teori aliran menamai gerakan berdasarkan hubungan kedua rotasi tersebut. Ini adalah kosakata yang sama untuk tongkat, hoop, dan poi, yang menjelaskan mengapa keterampilan dapat ditransfer antar alat dengan baik.","Dalam putar, kadang disebut inspin, prop berputar dengan arah yang sama dengan lingkaran tangan. Ini adalah arah alami; sebagian besar putaran pertama adalah inspin tanpa ada yang menyebutnya demikian. Bentuk yang dilukis adalah bunga yang kelopaknya mengarah keluar.","Dalam antispin, alat berputar ke arah yang berlawanan dengan lingkaran tangan. Awalnya terasa aneh, seperti menepuk kepala dan menggosok perut, tetapi menghasilkan bunga petal klasik. Jumlah petal tergantung pada berapa kali alat berputar untuk setiap lingkaran tangan: tiga putaran berlawanan per lingkaran menghasilkan empat petal, yang merupakan Four-Petal Antispin dalam pohon tongkat.","Isolasi adalah kasus khusus di mana tangan berputar sehingga satu titik alat tampak membeku di ruang angkasa. Dengan tongkat, pusat tetap diam sementara ujung-ujungnya berputar di sekitarnya; dengan cincin, pusat cincin atau satu titik pada tepinya tetap diam. Isolasi terlihat seperti alat mengambang dan tubuh mengelilinginya. Mereka membutuhkan jalur tangan yang presisi, yang menjadikannya latihan yang sangat baik untuk setiap trik lainnya.","Pelajari ini secara perlahan dan sesuai irama. Antispin terutama mendapat manfaat dari tempo yang jauh di bawah kecepatan berputar normal Anda, dengan hitungan yang menunjukkan di mana alat seharusnya berada: atas, sisi, bawah, sisi. Gunakan hantu dalam penampil 3D untuk melihat posisi pada ketukan berikutnya, dan jejak untuk melihat apakah bunga Anda memiliki petal yang merata.","Setelah spin, antispin, dan isolasi terasa akrab dalam satu bidang, coba di bidang lain. Teorinya tetap sama dan tubuh Anda belajar bahwa bidang hanyalah pengaturan, yang merupakan langkah besar menuju improvisasi aliran."]},"timing-and-direction":{"title":"Timing and direction: the four relationships","summary":"Together or split time, same or opposite direction — four relationships that let spinners name patterns and move between them.","imageAlt":"3D figure spinning a poi butterfly with hands close together","body":["Siteswap gives jugglers a shared language for throws. Spinners have something similar for two hands and two props: timing and direction. Timing asks whether the hands (or prop heads) reach the same place in the circle at the same moment — together — or half a turn apart — split. Direction asks whether they turn the same way around that circle or opposite ways. Combine the two and you get four basic relationships: together-same, together-opposite, split-same and split-opposite.","Together-same is the first wall spin most people learn: both poi or both staff ends travel as a pair. Split-same is the classic weave foundation, where one head is at the top when the other is at the bottom. Together-opposite looks like a butterfly when the hands sit close: the heads kiss at the top and bottom. Split-opposite is the remaining corner, with opposite directions and staggered timing.","These four states are not just labels. They form a small map. Each relationship shares two cardinal positions — top, bottom, or the far sides — with two of its neighbours. At a shared position you can reverse one hand and step into the neighbouring relationship. That is Transition Theory in everyday language: a circle of legal hops, like a musician’s circle of fifths for spinning. The hops that are forbidden are the ones with no shared position, such as jumping straight between together-opposite and split-same without an intermediate stop.","Hand-to-prop speed ratios sit on top of that map. Plain spin, where the hand and the head travel together, is often called a 1:1 CAP. A four-petal antispin flower is a 1:3 relationship: three head turns for each hand circle. A six-petal antispin (or the matching inspin) is 1:5. SynthFlow’s Timing lab lets you switch CAP presets while the 3D coach keeps the beat, so you can see the flower change without leaving offline practice.","Open Learn → Timing & Direction to explore the four cells, hide one prop to read hybrids more clearly, and drill recognition quizzes that stay on your device. The same words appear in the glossary under same time / split time, butterfly, antispin and flower. Once the map clicks, catalog move names stop feeling arbitrary — they become addresses you can travel between on purpose."]},"sequencing":{"title":"Cara membuat rutinitas alir","summary":"Pemanasan, latihan satu fokus dengan tautan yang mengalir, jaga lompatan tempo tetap kecil, dan akhiri dengan pendinginan yang mudah.","imageAlt":"Figur 3D melewatkan cincin dari tangan ke tangan di depan tubuh","body":["Rutinitas aliran yang baik memiliki bentuk yang sama dengan set musik yang baik: pembukaan yang menghangatkan ruangan, bagian tengah yang membangun, dan akhir yang memungkinkan semua orang bernapas. Rutinitas bawaan SynthFlow mengikuti bentuk itu, dan co-pilot pembuat memeriksa rutinitas Anda terhadapnya.","Mulailah dengan pemanasan. Lingkaran pergelangan tangan, lingkaran lengan, dan putaran bahu membawa sendi yang akan Anda bebankan melalui rentangnya dengan tempo yang lembut. Dua atau tiga menit sudah cukup untuk sesi singkat; sesi yang lebih lama dan hari yang dingin membutuhkan waktu lebih lama.","Berikan satu fokus pada blok latihan. Pilih gerakan yang sedang Anda latih dan kelilingi dengan gerakan yang terhubung dengannya. Pembuat menunjukkan bagaimana setiap langkah terhubung dengan yang sebelumnya: mengalir langsung dari posisi tangan yang sama, perubahan genggam kecil, meletakkan alat, atau membangun dari trik sebelumnya. Rutinitas yang mengalir terasa seperti menari; rutinitas yang penuh dengan penempatan terasa seperti daftar.","Jaga perubahan tempo tetap kecil antar langkah. Melompat dari 80 ke 130 BPM mengatur ulang waktu Anda dan memicu kegagalan. Co-pilot akan menandai lompatan lebih dari sekitar seperempat, melipat setengah dan dua kali lipat waktu sehingga langkah hoop 70 BPM dapat berada di samping trek 140 BPM.","Kembali ke gerakan fokus lebih dari sekali. Pengulangan selama sesi, dengan gerakan lain di antaranya, membangun keterampilan lebih baik daripada satu blok panjang, karena setiap kembali adalah upaya baru dari titik awal yang sedikit berbeda.","Selesaikan dengan pendinginan: gerakan mudah dengan tempo lambat, atau istirahat singkat dengan beberapa napas. Ini menurunkan detak jantung dan memberi koordinasi Anda akhir yang tenang untuk diingat. Pratinjau rutinitas sebelum memainkannya dan hapus apa pun yang jelas merupakan ambisi kemarin."]},"effort":{"title":"Kapan harus mempercepat ritme","summary":"Dorong saat bentuk tetap dan Anda segar; kendurkan saat puncak goyah, cengkeraman mengeras atau kegagalan mulai berkerumun.","imageAlt":"Figur 3D menjuggling lima bola dalam alur tinggi","body":["Kemajuan dalam alur datang dari berlatih di tepi kemampuan Anda, tetapi tepi itu bergerak. Beberapa hari lebih jauh dari yang Anda harapkan; beberapa hari telah mundur. Belajar membacanya adalah keterampilan yang bernilai sama dengan trik apa pun.","Dorong saat dasar tetap terjaga. Jika puncak Anda bahkan, tongkat Anda tetap di bidangnya, hoop tetap sejajar dan pernapasan Anda mudah, naikkan tangga tempo berikutnya atau coba latihan berikutnya dalam progresi. Lima belas menit pertama sesi, setelah pemanasan, biasanya waktu terbaik untuk materi baru.","Kendurkan saat kualitas menurun. Kegagalan yang berkerumun, cengkeraman yang mengeras, bahu yang mendekati telinga dan napas yang tertahan semua menandakan sistem saraf Anda lelah. Turunkan tempo, kembali ke gerakan yang Anda kuasai, atau akhiri sesi. Mendorong melalui kelelahan sebagian besar hanya memperlatih kesalahan.","Perhatikan juga peringatan fisik. Melempar dan berputar berulang-ulang membebani pergelangan tangan, lengan bawah, dan bahu. Nyeri yang memudar dalam sehari adalah adaptasi normal. Nyeri tajam, nyeri yang bertambah selama latihan, mati rasa, atau kesemutan adalah alasan untuk berhenti dan beristirahat; gejala yang berkelanjutan perlu ditangani oleh dokter.","Gunakan penilaian usaha setelah setiap sesi. Wizard latihan membacanya: beberapa sesi sulit berturut-turut dan ia menyarankan sesuatu yang lebih lembut, beberapa sesi mudah dan ia menyarankan sedikit lebih banyak. Penilaian jujur membuat saran yang lebih baik."]},"drops-are-data":{"title":"Jatuhnya adalah data","summary":"Kegagalan memberi tahu Anda lemparan atau tangkapan mana yang perlu diperbaiki; memperlakukannya sebagai kegagalan hanya mengajarkan Anda untuk tegang.","imageAlt":"Figur 3D menukar dua bola juggling antar tangan","body":["Setiap juggler pada suatu saat pernah memiliki lantai yang dipenuhi bola. Setiap pemutar staf pernah mendengar bunyi jatuhnya. Perbedaan antara orang yang terus berkembang dan orang yang berhenti jarang terjadi karena bakat; melainkan bagaimana mereka menanggapi jatuhnya.","Jatuhnya bola adalah pengukuran. Ini memberi tahu Anda lemparan mana yang salah, tangkapan mana yang Anda coba ambil, dan saat mana dalam putaran yang kehilangan arahnya. Jika bola yang sama terus jatuh di depan Anda, maka lemparan Anda miring ke depan. Jika jatuhnya terjadi setelah enam lemparan, maka ada yang salah pada lemparan ketiga atau keempat Anda. Perhatikan di mana dan kapan, lalu pilih satu hal untuk diubah.","Menganggap jatuhnya sebagai kegagalan memiliki biaya. Ketakutan mengencangkan bahu dan memendekkan napas, serta ketegangan membuat gerakan menjadi lebih kecil dan lebih cepat, yang menyebabkan lebih banyak jatuhnya. Respons yang tenang — ambil bola, tarik napas, tunggu ketukan, mulai ulang — bukan hanya menyenangkan; itu adalah respons yang secara teknis benar.","Hitung run bersih, bukan jatuhnya. SynthFlow menguasai gerakan ketika Anda memiliki cukup run bersih dan menit latihan, sehingga jatuhnya di sepanjang jalan hanyalah bagian dari menit tersebut. Beberapa hari Anda akan mencatat sepuluh run bersih, beberapa hari dua. Kedua hari itu dihitung.","Jatuhkan bola dengan sengaja sesekali. Saat belajar trik baru, latih lemparan pertama atau setengah putaran pertama dan biarkan jatuh. Lalu tambahkan tangkapan. Mengisolasi momen yang berisiko memperkecilnya, dan Anda belajar bahwa lantai bukanlah musuh Anda. Itu hanya tempat prop jatuh saat Anda sedang belajar."]},"safety":{"title":"Keamanan: ruang, alat peraga, dan tanda bahaya","summary":"Bersihkan ruang Anda, pilih prop yang ramah, pemanasan, dan hentikan jika merasa sakit tajam, mati rasa, atau pusing.","imageAlt":"Figur 3D memutar staf datar di atas kepala dengan ruang yang jelas di sekitarnya","body":["Seni aliran memiliki risiko rendah dibandingkan dengan kebanyakan olahraga, tetapi prop bergerak cepat dan menempuh jarak lebih jauh dari yang Anda duga. Beberapa kebiasaan menjaga latihan tetap aman bagi Anda, orang di sekitar Anda, dan perabotan.","Bersihkan ruang Anda sebelum memulai. Periksa setiap bidang yang akan Anda gunakan: di depan, ke sisi, dan di atas. Staf dan hoop membutuhkan lebih banyak ruang dari yang Anda kira, biasanya lingkaran setidaknya selebar lengan ditambah panjang prop ke segala arah, dengan tidak ada benda yang mudah pecah dalam jangkauan. Di dalam ruangan, perhatikan lampu langit-langit dan kipas angin; di luar ruangan, perhatikan tanah yang tidak rata dan orang yang lewat.","Gunakan prop yang ramah saat belajar. Bola juggling berbentuk beanbag tidak akan berguling jauh. Staf dengan ujung yang empuk atau busa lebih tidak menyakitkan saat mengenai kepala Anda, yang pasti akan terjadi. Hoop yang lebih besar dan berat berputar lebih lambat dan lebih mudah dijaga. Tingkatkan ke prop yang lebih cepat atau lebih mencolok setelah dasar-dasarnya sudah otomatis.","Pemanasan sebelum setiap sesi dan tingkatkan volume secara bertahap. Melempar dan berputar adalah gerakan berulang, dan beban berulang pada jaringan yang kedinginan adalah penyebab umum nyeri pergelangan tangan dan siku. Jika Anda menambahkan banyak latihan secara tiba-tiba, tambahkan juga hari istirahat.","Berhenti jika muncul tanda-tanda bahaya: rasa sakit tajam atau seperti tersengat listrik, mati rasa atau kesemutan di tangan, rasa sakit yang semakin memburuk saat Anda melanjutkan, pusing, atau benturan pada kepala dengan gejala yang tersisa. Gerakan leher dan gulungan kontak memerlukan perhatian ekstra; pelajari secara perlahan dengan alat bantu yang empuk.","Aplikasi ini mengajarkan teknik, bukan perawatan medis. Kehamilan, cedera baru-baru ini, kondisi sendi, dan segala hal yang mengkhawatirkan Anda adalah alasan untuk bertanya kepada profesional yang memenuhi syarat sebelum menambah beban baru. Pertunjukan api adalah disiplin terpisah dengan pelatihan keselamatan sendiri; SynthFlow tidak mengajarkannya."]},"warm-up":{"title":"Mengapa pemanasan penting untuk latihan prop","summary":"Dua hingga lima menit mobilitas pergelangan tangan, lengan, bahu, dan pinggul membuat putaran lebih lancar dan melindungi sendi Anda.","imageAlt":"Figur 3D melakukan gerakan lingkaran pergelangan tangan lambat dengan lengan ke depan","body":["Latihan flow terlihat lembut, tetapi meminta banyak dari beberapa sendi. Juggling mengulangi lemparan yang sama ribuan kali; berputarnya tongkat menggerakkan pergelangan tangan melalui rentang penuhnya; hooping menggoyangkan tulang belakang dan pinggul pada setiap orbit. Jaringan yang hangat lebih tahan terhadap pengulangan dibandingkan jaringan yang kedinginan.","Pemanasan flow yang baik singkat dan spesifik. Lingkaran pergelangan tangan ke kedua arah mempersiapkan sendi yang melakukan sebagian besar pekerjaan. Lingkaran lengan dan putaran bahu membangunkan otot-otot rotator cuff dan tulang belikat, yang mengendalikan bidang setiap putaran. Lingkaran pinggul dan putaran tubuh paling penting untuk hooping. Setengah lingkaran leher, jangan sampai putaran penuh, mengurangi ketegangan dari menatap pola di atas.","Geraklah perlahan dan sesuai irama. Langkah pemanasan dalam SynthFlow dihitung seperti hal lainnya, dengan tempo santai, sehingga beberapa menit pertama sesi juga menyesuaikan waktu Anda. Saat alat bantu keluar, Anda sudah bergerak sesuai musik.","Selesaikan pemanasan dengan alat bantu pada kecepatan setengah. Beberapa lemparan lambat, putaran depan yang santai, atau orbit hoop besar yang lambat menghubungkan kerja mobilitas dengan gerakan yang akan Anda latih, dan memberi tahu Anda bagaimana tubuh Anda terasa hari ini.","Pemanasan juga merupakan transisi mental. Tiga menit yang sama di awal setiap sesi menjadi isyarat bahwa latihan telah dimulai. Di hari yang sibuk, pemanasan terkadang merupakan seluruh latihan, dan itu tetap dihitung."]},"anatomy-basics":{"title":"Tubuh di balik prop","summary":"Lengan bawah menggenggam dan melepaskan, bahu mengarahkan bidang, inti menjaga Anda tetap diam: peta bahasa sehari-hari untuk flow.","imageAlt":"Figur 3D berhooping di pinggang dengan tubuh bagian atas rileks","body":["Anda tidak perlu tahu anatomi untuk berjuggling, tetapi peta sederhana membantu Anda memahami apa yang lelah, apa yang perlu dipanaskan, dan apa yang perlu diistirahatkan. Bagian Otot pada Learn memiliki model interaktif; artikel ini adalah tur singkat.","Lengan bawah melakukan sebagian besar pekerjaan halus. Otot di sisi telapak tangan menutup jari dan menekuk pergelangan tangan; otot di bagian belakang lengan bawah membuka jari dan meluruskan pergelangan tangan. Menangkap dan melepaskan, memegang tongkat dan membiarkannya bergulir, semuanya terjadi di sini. Kelelahan lengan bawah adalah perasaan paling umum setelah sesi panjang, dan inilah sebabnya mengapa perintah pegangan rileks sering diberikan.","Bahu mengarahkan. Deltoid mengangkat lengan; otot-otot rotator cuff, empat otot kecil di sekitar sendi, menjaga lengan atas tetap di tengah saat bergerak. Otot di sekitar tulang belikat menjaga keseluruhan sistem tetap stabil. Ketika tongkat menyimpang dari bidangnya, penyebabnya sering kali adalah bahu, bukan tangan.","Inti tubuh membuat Anda tetap tenang. Dalam berjuggling, tubuh bagian atas yang diam menjaga pola tetap stabil. Dalam bermain lingkaran, otot perut dan punggung menggerakkan lingkaran dengan denyutan kecil ke depan dan ke belakang. Pinggul dan kaki adalah dasar Anda: lutut yang lentur menyerap gerakan dan memungkinkan Anda mengalihkan berat tanpa mengganggu alat permainan.","Mata dan telinga dalam Anda juga penting. Berjuggling melatih Anda untuk memperhatikan puncak, bukan tangan; berputar melatih keseimbangan Anda. Sesi singkat dengan istirahat memungkinkan keduanya beradaptasi tanpa pusing. Anggap peta ini sebagai literasi, bukan diagnosis, dan temui profesional jika rasa sakit tidak membaik."]},"biomechanics-safety":{"title":"Pergelangan tangan, bahu, dan beban berulang","summary":"Pegangan rileks, pergelangan tangan netral, dan volume yang bertahap membuat sendi yang melakukan semua pekerjaan tetap nyaman.","imageAlt":"Figur 3D berputar dengan tongkat dengan satu tangan di atas bagian belakang tangan","body":["Cedera akibat aliran jarang dramatis. Hampir selalu merupakan akibat dari penggunaan berlebihan: terlalu banyak repetisi, terlalu banyak pegangan, terlalu sedikit istirahat. Kabar baiknya adalah kebiasaan-kebiasaan kecil yang sama mencegah sebagian besar dari mereka.","Rilekskan pegangan. Bola juggling hanya membutuhkan tekanan yang cukup untuk tetap di tangan; tongkat membutuhkan cincin jari yang longgar yang bisa bergulir di dalamnya. Memegang terlalu erat membuat otot lengan bawah lelah dan membebani tendon di siku. Jika buku jari Anda memutih atau lengan bawah Anda terasa terbakar setelah beberapa menit, kendurkan dan kurangi kecepatannya.","Jaga pergelangan tangan tetap dekat dengan posisi netral bila memungkinkan. Berputar membawa pergelangan tangan melalui rentang besar, yang tidak masalah jika dalam jumlah terbatas. Menahan pergelangan tangan di ujung rentangnya dalam waktu lama, atau memaksa pergelangan tangan yang kaku untuk berputar, adalah yang membuatnya iritasi. Biarkan siku dan bahu berbagi gerakan.","Biarkan bahu bekerja, tetapi jangan membungkuk. Gerakan lingkaran besar berasal dari sendi bahu; bahu yang terangkat akan menyebabkan ketegangan dan cepat lelah. Periksa di cermin atau mode kamera bahwa bahu Anda tetap turun, terutama dalam gerakan di atas kepala seperti helikopter dan lasso.","Bangun volume secara bertahap. Jika Anda biasanya berlatih dua puluh menit, jangan langsung melonjak ke dua jam karena ada festival yang akan datang. Tingkatkan total waktu secara moderat setiap minggu dan pastikan setidaknya ada satu hari yang mudah. Tukar alat untuk membagi beban: kerja hoop akan memberi istirahat pada lengan bawah yang terasa lelah karena juggling.","Nyeri yang hilang dalam sehari adalah adaptasi normal; nyeri yang bertahan, bertambah, atau disertai mati rasa bukanlah hal yang normal. Istirahat, kurangi volume, dan cari saran profesional jika tetap berlanjut. Ini adalah pendidikan, bukan saran medis."]},"choosing-props":{"title":"Memilih prop pertama Anda","summary":"Beanbag untuk juggling, tongkat empuk ringan, dan hoop besar untuk orang dewasa membuat minggu-minggu pertama jauh lebih mudah.","imageAlt":"Figur 3D berputar memutar hoop di sekitar satu tangan","body":["Alat yang baik untuk pemula membuat pembelajaran lebih cepat dan kurang frustasi. Anda tidak perlu peralatan mahal, tetapi beberapa pilihan penting.","Untuk juggling, mulailah dengan tiga bola beanbag seberat sekitar 60 hingga 130 gram masing-masing. Beanbag tidak memantul atau berguling saat jatuh, yang menghemat banyak waktu mengejar. Bola harus pas di telapak tangan Anda. Bola panggung, yang lebih besar, dan bola silikon yang elastis untuk nanti. Warna yang sama membantu Anda melihat pola; tiga warna berbeda membantu Anda melacak bola masing-masing saat belajar siteswap.","Untuk staff, staff putar pemula biasanya sekitar 1,2 hingga 1,5 meter, ringan, dengan ujung yang empuk atau karet. Sebagai panduan kasar, panjangnya harus mencapai antara dada dan bahu saat berdiri tegak. Staff yang lebih panjang dan berat berputar lebih lambat dan halus setelah Anda menguasai dasar-dasarnya, tetapi lebih sulit dimulai dan lebih menyakitkan saat mengenai Anda. Pegangan di tengah membantu.","Untuk hoop, mulailah dengan ukuran lebih besar dan lebih berat dari yang Anda kira. Hoop pemula orang dewasa biasanya mencapai antara pinggang dan dada saat berdiri di lantai. Hoop yang lebih besar berputar lebih lambat, memberi Anda waktu untuk menemukan ritme untuk hoop pinggang. Hoop yang lebih kecil dan ringan cocok untuk trik cepat di luar tubuh setelah Anda merasa nyaman.","Apapun yang Anda pilih, pastikan rentang tempo gerakan sesuai dengan alatnya. Alat yang lebih berat biasanya lebih cocok dengan tempo yang lebih rendah. Jika rentang nyaman aplikasi terasa terburu-buru dengan alat Anda, atur tempo Anda sendiri di pembuat; hitungan akan mengikuti."]},"practice-at-home":{"title":"Berlatih di rumah dan di taman","summary":"Sesi harian singkat, ruang yang jelas, tepi tempat tidur atau sofa untuk menangkap jatuhnya, dan jam di taman saat Anda bisa.","imageAlt":" figur 3D mengibaskan lengan di antara putaran latihan","body":["Sebagian besar seniman aliran belajar di rumah, beberapa menit sekaligus. Sedikit persiapan membuat latihan di rumah lebih mudah dimulai dan lebih mudah dilanjutkan.","Temukan tempat Anda. Untuk juggling, berdiri di depan tempat tidur atau sofa berarti bola yang jatuh akan mendarat setinggi pinggang bukan berguling di bawah perabot, dan juga mencegah Anda berjalan ke depan. Untuk tongkat dan lingkaran, temukan ruang kosong terbesar yang Anda miliki, periksa langit-langit, dan pindahkan benda yang mudah pecah. Taman atau taman kota lebih baik untuk putaran besar.","Jaga agar alat peraga tetap terlihat. Bola di meja akan dijuggling saat panggilan dan istirahat; lingkaran di dekat pintu akan digunakan. Semakin sedikit usaha yang diperlukan untuk memulai, semakin sering Anda melakukannya. Rutinitas lima menit pun penting, dan beberapa sesi pendek sehari akan menumpuk dengan cepat.","Gunakan aplikasi sebagai struktur. Pilih rutinitas atau biarkan wizard menyarankan satu, mainkan, dan catat upaya Anda. Program pendek seperti Zero to Cascade memberi setiap minggu tujuan yang jelas, yang membuat Anda tidak mengambang antar trik.","Latih bersama orang lain bila memungkinkan. Klub juggling, sekolah sirkus, dan jam aliran taman ada di banyak kota. Menonton seseorang yang sedikit lebih maju dari Anda sering kali memperbaiki sesuatu yang tidak bisa diperbaiki oleh tutorial, dan mengajar seseorang yang sedikit di belakang Anda membuat teknik Anda sendiri lebih jelas. Bawa alat peraga Anda, tanyakan apa yang sedang dikerjakan orang lain, dan bagikan apa yang telah Anda pelajari dari hitungan."]},"learning-with-the-app":{"title":"Belajar dengan pelatih 3D","summary":"Perlahan, tiru, nyalakan hantu dan jejak, ubah kamera, dan gunakan mode kamera untuk umpan balik.","imageAlt":"figur 3D melakukan isolasi tongkat dengan jejak menunjukkan jalur","body":["Setiap gerakan dalam SynthFlow dianimasikan dalam 3D dari jam yang sama dengan musik, sehingga figur selalu tepat pada irama. Digunakan dengan baik, penonton adalah guru yang sabar yang tidak pernah bosan menunjukkan lemparan yang sama kepada Anda.","Perlahan dulu. Tangga kemajuan pada setiap gerakan dimulai dengan versi lambat dan parsial, lalu hanya tangan, lalu gerakan penuh sesuai irama. Kecepatan setengah mempertahankan hubungan waktu sambil memberi waktu bagi mata Anda untuk mengikuti.","Tiru figur jika Anda belajar lebih baik menghadap guru, dan ubah kamera bila satu tampilan menyembunyikan sesuatu. Tampilan samping menunjukkan kemiringan tongkat dan pergeseran lemparan; tampilan atas menunjukkan bidang lingkaran dan jalur helikopter. Jejak menggambar di mana setiap alat peraga telah berada, yang mengubah kabur menjadi bentuk yang bisa Anda pelajari. Hantu menunjukkan di mana alat peraga akan berada pada irama berikutnya.","Tonton kesalahan umum. Setiap gerakan dapat menunjukkan kesalahan khasnya, seperti melayang ke depan, ketinggian yang tidak merata, atau terburu-buru, dimainkan salah secara sengaja pada figur, dengan petunjuk yang memperbaikinya. Mengenali kesalahan pada model membuatnya jauh lebih mudah dirasakan dalam tubuh Anda sendiri.","Mode kamera memberikan umpan balik tentang Anda. Dengan izin, kamera melacak tangan dan tubuh Anda saat Anda berlatih dan membandingkan waktu Anda dengan irama. Pemrosesan dilakukan di perangkat Anda. Ini tidak sempurna, dan cahaya yang baik membantu, tetapi bahkan umpan balik kasar tentang apakah Anda terlambat atau terlalu cepat sangat berharga.","Akhirnya, tutup penonton sesekali. Berlatih hanya dengan musik dan percayalah pada hitungan. Tujuannya adalah gerakan yang dapat Anda lakukan tanpa melihat apa pun."]},"music-for-flow":{"title":"Menemukan musik yang cocok","summary":"Tempo terukur, tempo setengah dan dua kali lipat, perkusi yang dihasilkan, dan trek Anda sendiri semuanya menjaga hitungan tetap akurat.","imageAlt":"Figur 3D berputar di dada dengan lengan terangkat","body":["Musik mengubah latihan menjadi aliran, tetapi hanya jika irama dalam musik adalah irama dalam hitungan. Sebuah trek dengan 118 BPM di bawah rutinitas 120 BPM akan berbeda dalam waktu satu menit, dan Anda akhirnya berjuang melawan musik alih-alih mengikuti iramanya.","Trek yang disertakan SynthFlow memiliki tempo dan downbeat yang terukur, sehingga pemutar dapat memulai setiap langkah pada \\"satu\\" musik dan menjaga hitungan tetap selaras. Pembuat daftar trek yang sesuai dengan tempo bagian terlebih dahulu, termasuk trek dengan tempo setengah atau dua kali lipat: trek 140 BPM membawa langkah hoop 70 BPM dengan sangat baik.","Perkusi yang dihasilkan bekerja pada setiap tempo. Pilih kit untuk bagian dan pemutar akan mensintesis irama yang cocok persis, apakah Anda melakukan tangga tempo atau latihan lambat. Ini juga merupakan pilihan terbaik ketika Anda ingin pulsa tanpa melodi yang menarik perhatian Anda.","Anda dapat menganalisis trek dari perangkat Anda sendiri. Aplikasi memperkirakan tempo dan downbeat dan memungkinkan Anda memeriksanya dengan mengetuk mengikuti irama. Trek dengan pulsa elektronik atau akustik yang stabil bekerja paling baik; musik dengan perubahan tempo, rubato, atau intro panjang lebih sulit diukur dan lebih sulit dilatih.","Streaming video dimatikan selama latihan berhitung karena waktunya tidak dapat dikendalikan secara presisi. Gunakan untuk pemanasan atau bermain bebas, di mana tidak ada yang perlu selaras."]},"plateaus":{"title":"Dataran tinggi dan bagian tengah yang panjang","summary":"Setiap seniman aliran mengalami minggu-minggu di mana tidak ada perbaikan; ubah latihan, tempo, atau alat sebelum mengubah tujuan.","imageAlt":"Figur 3D memainkan Mills Mess dengan lengan saling bersilangan","body":["Awal aliran sangat indah: sesuatu yang baru setiap sesi. Kemudian, seringkali sekitar waktu Anda bisa menjuggling cascade yang stabil atau menjaga hoop tetap berputar tanpa henti, kemajuan tampaknya berhenti. Bagian tengah yang panjang inilah tempat kebanyakan orang berhenti, dan tempat pembelajaran yang paling menarik terjadi.","Plateau biasanya merupakan masa konsolidasi. Sistem saraf Anda sedang mengatur ulang gerakan sehingga membutuhkan perhatian lebih sedikit, yang tidak terlihat sebagai trik baru. Seringkali keterampilan yang terasa macet selama dua minggu tiba-tiba muncul di suatu pagi. Teruslah berlatih melewati masa yang datar ini.","Ubah latihannya, bukan tujuannya. Jika cascade tidak mau lebih cepat, latihlah dengan tempo lebih rendah dengan puncak sempurna, lalu dengan mata mengarah ke titik di atas pola, lalu dengan satu tangan saja. Jika gerakan tongkat tidak muncul, bagi menjadi dua bagian dan latih masing-masing sesuai irama. Latihan baru memberi otak informasi baru tentang keterampilan yang sama.","Latihan silang. Belajar prop kedua sering membuka kunci yang pertama. Hooping meningkatkan ritme di balik juggling; latihan tongkat mengajarkan bidang-bidang yang membuat trik hoop menjadi bersih. Pohon Hadiah untuk setiap seni bersifat independen, sehingga variasi tidak pernah menghambat kemajuan.","Bersikap baik terhadap diri sendiri. Bandingkan diri Anda dengan bulan lalu, bukan dengan pemain online yang telah berlatih selama sepuluh tahun. Halaman Kemajuan menyimpan catatan jujur tentang menit, tempo tertinggi, dan gerakan yang dikuasai. Di minggu yang datar, lihatlah dan lihat seberapa jauh garis sudah naik."]},"history-of-juggling":{"title":"Sejarah singkat juggling","summary":"Dari lukisan makam Mesir hingga jongleur abad pertengahan, teater variasi, dan matematika modern.","imageAlt":"Tokoh 3D menjuggling tiga bola shower dalam lingkaran","body":["Juggling sangat tua. Salah satu gambar tertua yang diketahui adalah lukisan dinding di makam Kerajaan Tengah di Beni Hasan di Mesir, berusia sekitar empat ribu tahun, menampilkan wanita melempar bola. Catatan dan gambar dari Tiongkok, Yunani, Roma, dan Pasifik menunjukkan bahwa orang-orang di banyak budaya menemukan cara mereka untuk melempar dan menangkap untuk pertunjukan dan permainan.","Di Eropa abad pertengahan, kata jongleur, dari mana kata \\"juggler\\" berasal, menggambarkan penghibur keliling yang bernyanyi, menceritakan kisah, melakukan akrobat, dan melempar benda. Juggling adalah salah satu keterampilan di antara banyak, bagian dari peralatan pemain daripada seni tersendiri.","Berbagai teater dan sirkus pada abad kesembilan belas dan awal abad kedua puluh menjadikan juggling sebagai pertunjukan utama. Para pemain berspesialisasi: juggling pria dengan topi dan tongkat, juggling klub, dan juggling angka yang mendorong hingga tujuh, delapan, dan lebih banyak bola. Enrico Rastelli, pada awal abad kedua puluh, masih sering disebut sebagai salah satu yang terhebat.","Sejak tahun 1970-an, budaya juggling sebagai hobi tumbuh di sekitar klub, festival, dan konvensi, dengan orang-orang yang saling berbagi trik secara bebas. Matematika bergabung pada tahun 1980-an ketika notasi siteswap memberi para juggling cara untuk menuliskan pola sebagai angka, yang mengarah pada penemuan trik baru di atas kertas sebelum siapa pun melemparkannya.","Saat ini, juggling berada di persimpangan sirkus, olahraga, tari, dan matematika. Beberapa juggling bersaing berdasarkan jumlah dan daya tahan, yang lain menampilkan koreografi dengan musik, yang lain mengeksplorasi pola demi pola itu sendiri. Setiap jalur dimulai dengan pertukaran dua bola yang sama, yang bisa Anda pelajari minggu ini."]},"history-of-staff":{"title":"Pemintalan tongkat: dari senjata ke aliran","summary":"Tongkat seni bela diri, twirling baton, dan pertunjukan api semuanya memberi kontribusi pada tongkat putar modern.","imageAlt":"Figur 3D melakukan gerakan kupu-kupu tongkat di belakang bahu","body":["Tongkat adalah salah satu alat tertua yang ada, dan memutar satu adalah keterampilan yang sudah tua. Banyak tradisi bela diri melatih dengan tongkat panjang, di antaranya bō Okinawa, gun Cina, dan pertarungan quarterstaff Eropa, dan latihan mereka mencakup putaran cepat dan pergantian tangan baik untuk pertahanan maupun pameran.","Twirling pertunjukan juga memiliki akar lain. Twirling baton berkembang menjadi disiplin kompetitif di abad kedua puluh, dengan lemparan, gulungan, dan putaran yang masih dipinjam oleh para pemutar. Teater, parade, dan pertunjukan jalanan di seluruh dunia telah menggunakan tongkat dan tiang yang diputar jauh sebelum siapa pun menyebutnya flow.","Adegan tongkat flow modern tumbuh dari akhir abad kedua puluh bersamaan dengan pertunjukan api dan budaya festival. Tongkat api, dengan sumbu di setiap ujungnya, membuat memutar terlihat dalam kegelapan dan mendorong seni menuju gerakan yang halus dan berkelanjutan daripada pukulan. Tongkat LED kemudian membawa visual yang sama ke dalam ruangan.","Sekitar waktu yang sama, para seniman flow mulai menggambarkan memutar dengan teori bersama: bidang, putaran dan antiputar, isolasi, waktu, dan arah. Sebagian besar dikembangkan dalam komunitas poi dan dibawa ke tongkat, lingkaran, dan alat lainnya, itulah sebabnya kata-kata yang sama muncul di seluruh aplikasi ini.","Contact staff, di mana staf berguling di atas tubuh alih-alih digenggam, berkembang menjadi gaya tersendiri dengan berguling di leher, bahu, dan lengan. Saat ini, putaran staf berkisar dari demonstrasi bela diri hingga aliran kontak yang lambat dan meditatif, semuanya dibangun di atas putaran roda pertama yang sama."]},"history-of-hoop":{"title":"Cincin: dari mainan kuno hingga seni aliran","summary":"Cincin telah menjadi mainan dan alat selama ribuan tahun; kegemaran tahun 1950-an dan kebangkitan festival menjadikan tarian cincin sebagai sebuah seni.","imageAlt":"Figur 3D berjalan dengan cincin berputar di atas tubuh","body":["Cincin adalah salah satu mainan tertua. Anak-anak di Mesir kuno, Yunani, dan Roma digambarkan atau digambarkan berguling cincin dengan tongkat dan memutar mereka di sekitar tubuh, dan permainan cincin muncul di banyak budaya sejak itu.","Cincin juga membawa makna budaya yang mendalam dalam beberapa tradisi. Tarian Cincin yang dilakukan di banyak komunitas Amerika Asli menggunakan beberapa cincin untuk membentuk bentuk seperti binatang dan bumi, menceritakan kisah melalui gerakan. Ini adalah tradisi yang hidup dengan sendirinya, berbeda dari adegan aliran modern, dan layak dipelajari dari para praktisinya sendiri.","Gelombang hula hoop plastik akhir tahun 1950-an, didorong oleh cincin yang diproduksi massal di Amerika Serikat, membuat cincin ada di jutaan rumah hampir dalam semalam. Selama beberapa dekade setelahnya, cincin sebagian besar dilihat sebagai mainan anak-anak dan alat kebugaran.","Dari akhir tahun 1990-an dan 2000-an, para penari cincin dewasa di festival dan komunitas online mulai memperlakukan cincin sebagai pasangan tari. Cincin yang lebih besar dan lebih berat buatan tangan memudahkan cincin di atas tubuh bagi orang dewasa, sementara cincin yang lebih kecil membuka trik cepat di luar tubuh. Video yang dibagikan menyebarkan kosakata seperti isolasi, wedgies, dan eskalator jauh melampaui satu kota pun.","Tarian cincin modern meminjam teori dari staf dan poi serta ritme dari segala jenis musik. Ini mudah diakses, menyenangkan, dan mendalam: seorang pemula dapat menemukan ritme pinggang dalam sehari, dan seorang ahli dapat menghabiskan bertahun-tahun untuk menyempurnakan satu isolasi."]},"fire-and-led":{"title":"Api, LED, dan alat pertunjukan","summary":"Alat pertunjukan berubah berat, kecepatan, dan risiko; pelajari setiap gerakan dengan alat latihan terlebih dahulu dan latih api secara terpisah.","imageAlt":"Figur 3D mengelilingi cincin datar di atas kepala seperti lasso","body":["Menonton staf api atau cincin LED di malam hari sering kali menarik orang ke dalam aliran. Alat pertunjukan sangat luar biasa, tetapi tidak sama dengan alat latihan, dan beralih ke mereka membutuhkan rencana.","Prop LED biasanya lebih berat daripada versi latihan karena baterai dan elektronik. Hal ini mengubah momentum: putaran berjalan lebih jauh, lemparan terasa berbeda, dan pergelangan tangan bekerja lebih keras. Pelajari setiap gerakan dengan prop latihan terlebih dahulu, lalu siapkan diri untuk masa penyesuaian singkat saat menggunakan LED. Kurangi tempo untuk sesi pertama.","Pertunjukan api adalah disiplin terpisah. Penanganan bahan bakar, area berputar yang aman, penonton pengawas dengan selimut api, pakaian yang sesuai, dan aturan setempat semuanya penting, dan yang terbaik adalah dipelajari secara langsung dari penampil api berpengalaman. SynthFlow tidak mengajarkan api, dan tidak ada yang dalam aplikasi ini yang boleh dipraktikkan dengan prop yang menyala.","Aturan yang baik yang digunakan di banyak komunitas aliran adalah hanya melakukan gerakan dengan prop pertunjukan setelah Anda bisa melakukannya secara konsisten, berkali-kali berturut-turut, dengan prop latihan. Di bawah lampu atau api, tidak ada ruang untuk percobaan.","Pertunjukan juga mengubah cara Anda menyusun gerakan. Penonton membaca gerakan besar, transisi bersih, dan momen diam yang jelas. Bangun rutinitas pertunjukan di pembuat seperti yang lainnya, pratinjau, dan latih dengan musik yang sama setiap kali agar hitungan menjadi koreografi."]},"cap-notation":{"title":"Speed ratios and CAP-style notation","summary":"Read hand:head speed ratios and the Θ1 Θ2 ; ρ1 ρ2 shorthand used in community CAP papers — without confusing speed ratio with assembly CAPs.","imageAlt":"3D figure drawing a four-petal antispin flower with poi","body":["Spinners share two related languages that are easy to mix up. The first is a simple speed ratio: how many times the prop head turns for each hand circle. Plain forward spin is 1:1. A three-petal antispin flower is often 1:2, a four-petal flower is 1:3, and a six-petal flower is 1:5. SynthFlow’s Timing lab and viewer chip show this as a speed ratio so you can compare flowers without memorising petal counts alone.","The second language comes from community papers on Continuous Assembly Patterns. A pattern is written as two harmonic turns and two length moduli: Theta1 Theta2 ; Rho1 Rho2. Theta1 is usually the arm’s turn rate; Theta2 is the relative turn of the head. Rho1 and Rho2 are relative lengths of the arm path and the tether path. When the two lengths match, Rho1 equals Rho2, and the curve is a rosette — the familiar even flower. When the lengths are tuned so tip and hand appear to move at the same audience speed, the curve is a cycloid. SynthFlow shows a derived readout such as 1 −3 ; 1 1 for four-petal antispin; it does not yet let you free-edit Rho while keeping petal math intact.","Hybrid and assembly CAP are different ideas that both use the word CAP in older writing. A hybrid here means two hands running different elementary patterns in parallel — for example one hand isolating while the other extends (a cateye). An assembly CAP means chaining elementary patterns in series on one prop into one longer cycle. SynthFlow’s catalog already ships many parallel hybrids; serial assembly remains a future explorer. Quizzes ask you to tell those ideas apart so the vocabulary stays sharp.","Use the Timing lab Notation panel while you change speed-ratio presets. Watch the Θ2 sign flip for antispin, stay positive for inspin, and land on 1 1 for plain spin. Link that picture to the Transition Theory map: the same flower can sit in together-same or split-same, and legal hops still follow shared cardinals. For deeper reading, community HTML references are linked from Credits and from the Timing page footer — SynthFlow ships original coaching copy offline and does not bundle third-party PDFs.","Practice tip: pick one speed ratio for a whole practice block. Name it out loud on the downbeat — “one to three” — before you change petals. When the ratio is stable, change timing or direction instead. That separation of concerns is what makes the four-cell map and the flower language work together instead of fighting in your head."]},"spinning-geometry":{"title":"Spinning geometry: symmetry to timing and direction","summary":"Choose a symmetry — central point, vertical axis, or horizontal axis — and land on the matching timing and direction cell.","imageAlt":"3D figure in a poi butterfly, opposite direction same time","body":["One way to invent poi patterns is to start from geometry instead of from move names. Pick a shape that has a clear symmetry, then ask which rotation of the hands respects that symmetry. Community writing (often summarised as a “symmetry method”) maps three everyday symmetries onto the same Timing and Direction grid SynthFlow already uses.","Central-point symmetry means the pattern looks the same if you rotate it around a centre in the plane. That configuration lands on same direction with split time — the split-same cell, the foundation under weaves and chase patterns. Vertical-axis symmetry mirrors left and right across a vertical line through the body; that wants opposite direction with same (together) time — the butterfly family. Horizontal-axis symmetry mirrors across a waist-high line and wants opposite direction with split time — the remaining opposite corner of the map.","Together-same, the first wall spin many people learn, is not forced by those three symmetries alone. It still matters as a neighbour on the transition map: you can hop into it from together-opposite at the top or bottom, or from split-same at the sides. Thinking in symmetries does not replace Transition Theory; it gives you a reason to visit three of the four cells on purpose.","Open Learn → Timing → Symmetry and tap each symmetry while watching the coach. Hide one prop if the picture is busy. Then take the built-in poi-symmetry-lab routine and visit vertical, central, and horizontal cells with catalog moves you already own. The quiz bank asks both directions: given a clip, name the symmetry; given a symmetry label, recognise the timing and direction.","When you improvise, try one constraint per phrase: “this phrase is vertical-axis only.” Stay in together-opposite until the phrase ends, then hop legally into a neighbour. Geometry becomes a compositional tool instead of a trivia fact, and your transitions stay clean because you already know which cardinals you share with the next cell."]},"hybrid-math":{"title":"Hybrid drivers: spin, isolation, extension, cateye","summary":"Treat each hand as a driver on a unit circle where poi length matches an isolation diameter, then mix same and split timing.","imageAlt":"3D figure performing a poi cateye hybrid","body":["A hybrid in this sense is two hands doing different elementary jobs at once. One hand may spin while the other isolates; one may extend while the other draws a cateye almond; both may isolate in split time. Community hybrid maths treat those jobs as drivers on a shared configuration space. A useful picture is a unit circle where the poi length is about the diameter of an isolation — the hand path of a cateye or extension variant sits on that scale so the two shapes can nest cleanly.","SynthFlow already encodes many of these pairs. Petal tuples such as [4, 0] mean the right hand draws a four-petal antispin while the left keeps plain spin. Extension flags and isolation petals build cateyes and iso–spin pairs. Plane hybrids swap wall, wheel and floor mid-cycle. The Hybrids tab in the Timing lab lays a small grid of timing (same or split) against drivers (spin, isolation, extension, cateye) so you can see the live coach without hunting the catalog first.","Hide one prop when the pattern is asymmetric. Your eyes need a clean read of each driver’s path before you put both back. Count slowly. Name the right hand’s job on the odd beats and the left hand’s job on the even beats until the labels stick. Then restore both props and keep the same names — the hybrid is still two simple patterns, not one mysterious blob.","Quizzes ask which hand is isolating versus spinning, and whether the timing is same or split. The poi-hybrid-session routine and the progression week after antispin start give you a practice path that stays offline. For plane-change hybrids such as wall-to-wheel, remember the switch wants a shared line between planes; for driver hybrids, the switch is about roles, not planes.","Keep vocabulary honest: parallel hybrids are not the same as serial assembly CAPs. If you are chaining stalls into flowers on one hand over time, that is assembly thinking. If both hands run different drivers in the same cycle, that is hybrid thinking. The glossary entries for hybrid, assembly CAP, and speed ratio keep those three ideas separated so coaching cues stay short."]},"degrees-and-weaves":{"title":"Degree of twist and weave counts","summary":"Count weaves in beats or in degree-of-twist labels such as −1_0_+1 for three-beat and −2…+2 for five-beat patterns.","imageAlt":"3D figure in a three-beat poi weave","body":["Weaves sit on split timing: one poi is high when the other is low, and the planes trade sides of the body. The classic three-beat weave crosses after three beats of that split foundation; the two-beat weave crosses faster; the five-beat weave stays longer on each side. SynthFlow already ships these as catalog moves. Degree-of-twist language adds another counting layer without changing how long a beat is.","In that language a three-beat phrase can be written with labels that step through minus one, zero, and plus one — compactly −1_0_+1. A five-beat phrase stretches to −2_-1_0_+1_+2. The signs describe facing and twist relative to the body line: facing inside versus facing outside, outswing versus inswing. Advanced inversions and introversions belong in the glossary as future vocabulary; this pass does not add new inversion generators to the catalog.","In Settings → Timing you can choose weave count style: beats (the default spoken one–two–three) or degrees (the pattern index spoken while the degree labels are what the theory names). The beat clock length does not change — only the cue mapping. Use degrees when you are studying notation; use beats when you are linking to music phrases.","Practice the poi-weave-degrees routine after you own the three-beat weave. Add the five-beat week on the weave ladder progression when the longer side stays clean. On the Timing lab, remember that weaves live in the split-same neighbourhood of the map; legal hops out of a weave still want shared cardinals, just like any other split-same pattern.","Quiz items ask you to match a notation string or a weave clip to two-beat, three-beat or five-beat families. Say the degree string once before you spin, then spin without talking. When the string and the body agree, you can improvise crossings without losing the split foundation underneath."]},"staff-vtg":{"title":"Staff theory: two ends, timing and direction","summary":"How Vulcan Tech Gospel timing and direction apply when both ends of a staff are visible, plus snapshots and speed ratios.","imageAlt":"3D figure drawing a four-petal antispin flower with a staff","body":["Siteswap gives jugglers digits for throws. Staff spinners share a different language with poi and clubs: timing and direction. Timing asks whether the two ends (or two hands on double staff) reach matching places in the circle together or half a turn apart. Direction asks whether they turn the same way or opposite ways. Those four relationships — together-same, together-opposite, split-same, split-opposite — are the backbone of community spin theory often summarised as Vulcan Tech Gospel.","A staff shows both ends at once. When you isolate the centre, one end extends while the other draws the complementary path. Clubs show only one end, so isolation and extension feel like separate moves even when the underlying geometry is the same. In the Timing lab, switch the prop to staff and watch both tips leave trails; that picture is the snapshot idea — a still of arms and props across an axis that you can compare between patterns.","Speed ratios sit on top of the map. Plain spin is 1:1. Four-petal antispin is a 1:3 relationship; six-petal is 1:5. SynthFlow’s lab presets flip those ratios while the beat clock stays steady. Legal transitions still hop only between cells that share a cardinal — top, bottom, or the sides — just as in the poi Timing map.","Double staff borrows the same four cells with one short staff in each hand. Same-time wheels and split-time wheels are addresses on that map, not separate mysteries. Choreography systems such as The Kinetic Alphabet write sequences as pictographs on this geometry; SynthFlow links out for that sheet-music layer and does not ship letter charts.","Open Learn → Timing, choose staff, and drill the quiz in staff mode. Then take a flower or symmetry routine from the catalog. Name the cell out loud before you change petals. When the map and the ends agree, improvisation stops feeling like a list of trick names and starts feeling like travel between addresses."]},"contact-staff-map":{"title":"Contact staff: rolls, wraps and open hands","summary":"A map of contact classes — fishtail, rolls, angel, palm — by body point and plane, without inventing a siteswap for contact.","imageAlt":"3D figure performing a staff fishtail on the open hand","body":["Contact staff means the prop travels across skin and clothing instead of living in a tight grip. There is no community-wide digit system like siteswap for contact. What teachers share is a taxonomy: what kind of contact (roll, wrap, stall, fishtail), where on the body it happens, and which plane the staff sits in while it travels.","Fishtails keep the staff pivoting on an open hand or wrist while the ends draw linked circles front and back. Hand rolls and forearm rolls send the staff across a surface without a catch in the middle. Angel rolls carry that idea across the upper back from arm to arm. Palm spins and steering-wheel turns keep contact but stay more held. Neck and shoulder rolls need padding and clear space — learn them slowly with a soft staff.","Entries and exits matter as much as the middle. Many contact phrases start from a held spin, open the hand at a known beat, ride the roll, then catch again. SynthFlow’s contact explorer lets you preview catalog contacts by class and plane offline so you can see the family before you drill. The quiz asks you to name the family from a short clip.","Treat contact as a second language beside tech spinning. Timing and direction still describe held patterns; contact adds body points and roll direction. Do not force one notation to cover both. Community research notes and forum taxonomies are linked from Credits for operators; the app ships original coaching copy only.","Practice tip: pick one contact class for a week. Fishtail until both hands feel even, then add a hand roll on the same plane. Use the staff-contact-session routine after foundations. Stop when the staff chatters or your wrists tighten — contact rewards soft hands more than ambition."]},"hoop-on-off-body":{"title":"Hoop map: on-body, off-body and planes","summary":"Hoop has no siteswap. Learn the teaching map — on-body versus off-body, horizontal versus vertical planes, and the transitions between them.","imageAlt":"3D figure waist hooping with a relaxed upper body","body":["Juggling has siteswap. Staff and poi share timing and direction. Hoop dance’s closest “theory” is a map, not a digit string. The first axis is on-body versus off-body: is the hoop riding a body zone (waist, chest, knees) or spinning in the hands away from the torso? The second axis is plane: horizontal work parallel to the floor (lasso, vortex, waist orbits) versus vertical work in the wall or wheel plane (weaves, hand spins, many isolations).","Most beginner curricula walk that map on purpose. Waist hooping both ways, then hips and chest, builds on-body rhythm. Off-body vertical weaves and hand spins free the torso. Horizontal tricks above the head open a second plane. Transitions such as escalators, spirals and hinges are the roads between cells — not decorations.","SynthFlow’s Hoop lab lays those axes over live catalog moves. Pick on-body or off-body, pick a plane, pick a family, and watch the coach. Quizzes ask you to classify a clip. Routines such as hoop-plane-lab force you to visit more than one cell in a session so the map sticks in your body as well as your head.","Unit-circle thinking from spinning props still helps. A hoop cateye nests isolation and extension-like paths so the rim draws an almond; the same isolation diameter idea appears in poi hybrids. You do not need equations to use the picture — keep the hoop’s path size matched when you combine floating isolations with open extensions.","Further reading lives on community curriculum sites linked from Credits. SynthFlow does not ship paid course video. Use the lab offline, then take one transition — waist to escalator, or weave to lasso — and repeat it until the change feels boring. Boring transitions are the ones you can dance with."]},"hoop-isolations-and-breaks":{"title":"Hoop isolations and breaks","summary":"Isolations make the hoop look frozen or floating; breaks intentionally interrupt spin to change direction or plane.","imageAlt":"3D figure holding a hoop isolation in the wall plane","body":["An isolation is the illusion that one point of the hoop stays still in space while the rest of the rim turns. Linear isolations slide that freeze point along a line; circular or centred isolations keep the float in one place. Cateyes close the rim toward the audience so the hoop reads as a narrow almond before it opens again. Ghosting traces with the free hand to sell the float.","A break is different. Instead of keeping continuous spin, you interrupt the hoop’s path — a paddle, a pinch, a shoulder break — so direction, plane or body zone can change. Off-body breaks train timing with the hands first; on-body breaks ask the core and shoulders to catch the same idea. Reversals flip the spin direction without dropping the phrase.","In SynthFlow, isolation and cateye modes already exist on the hoop generator. The Hoop lab groups them under the isolation family next to body spins, weaves, escalators and passes. Quizzes ask isolation-versus-spin and family identification. The hoop-isolation-session routine drills float before you stack breaks.","Keep cues short. For isolations: “freeze the far point, walk the hands.” For breaks: “stop the circle on purpose, then choose the next plane.” Tempo should drop when you first learn either skill; momentum hides mistakes until the hoop falls behind the beat.","Link isolations to the shared geometry article trail — hoop cateye and poi/staff isolation diameter are cousins. Link breaks to sequencing: a break is a punctuation mark in a counted phrase. Once both feel clean, on–off-body transitions stop being scary because you already own the ways to interrupt and restart the hoop’s story."]}}`),r=JSON.parse(`{"the-day-the-cascade-clicked":{"title":"Hari ketika kaskade itu berbunyi","summary":"Tiga minggu mengejar bola di lantai berakhir saat saya berhenti memperhatikan tangan saya dan mulai menghitung.","body":["Selama tiga minggu, tiga bola saya hanya bertahan empat lemparan. Kanan, kiri, kanan, lalu bola ketiga berada di belakang sofa. Saya menonton video, saya memperlambat, saya mempercepat. Saya berdiri di depan tempat tidur seperti yang dikatakan setiap tutorial. Tidak ada yang berubah, kecuali kosakata saya.","Solusinya, ketika datang, sangat sederhana. Saya memutar lagu 90 BPM dan mengucapkan hitungan dengan keras: satu, dua, tiga, empat, lemparan di setiap ketukan. Tiba-tiba lemparan punya tempat untuk pergi. Alih-alih melempar saat tangan merasa siap, yang berarti kapan pun ketakutan mengatakan untuk melakukannya, setiap lemparan menunggu ketukannya. Polanya menjadi lebih lambat, lebih tinggi, dan lebih tenang.","Solusi kedua adalah di mana saya melihat. Saya telah menatap tangan saya, yang seperti membaca buku sambil memperhatikan kelopak mata Anda. Ketika saya mengangkat pandangan ke puncak, dua titik di bagian atas busur, tangan saya mulai menangkap secara otomatis. Puncak memberi tahu saya apakah lemparan itu merata; tangan tidak perlu pengawasan.","Dua belas lemparan menjadi dua puluh, lalu lima puluh. Suatu malam saya menjuggling selama seluruh langkah delapan tanpa jatuh dan tersenyum ke langit-langit seperti orang bodoh. Aplikasi menyebutnya jalur bersih. Saya menyebutnya pertama kali menjuggling terasa seperti musik, bukan pertarungan.","Jika kamu terjebak di empat lemparan, coba apa yang berhasil untukku: hitung dengan keras, lempar sesuai irama, lihat puncaknya. Dan lepaskan tanpa drama. Lantai adalah tempat setiap cascade dimulai."]},"why-we-count-in-bars":{"title":"Mengapa kami menghitung dalam bar, bukan detik","summary":"Pegangan selama empat puluh detik masuk akal untuk peregangan; pola juggling hidup berdasarkan irama, jadi kami mengukur latihan dalam bar.","body":["Ketika kami mulai membangun SynthFlow, keputusan besar pertama adalah bagaimana mengukur langkah rutinitas. Aplikasi saudara kami SynthYoga menghitung pegangan dalam detik dan napas. Itu cocok untuk pose yang kamu pegang. Tapi tidak cocok untuk pola yang berulang sesuai irama.","Lemparan juggling, setengah putaran tongkat, dan orbit lingkaran semuanya adalah siklus. Jika musik berjalan pada 100 BPM dan cascade-mu berjalan pada 103, kamu tidak juggling mengikuti musik; kamu juggling di dekatnya, dan dalam satu menit kamu tertinggal satu irama. Mengukur langkah dalam bar pada tempo berarti musik, hitungan, angka 3D, dan langkah berikutnya semuanya dimulai pada downbeat yang sama.","Bar juga membuat kemajuan menjadi konkret. \\"Juggling selama satu menit\\" terdengar kabur: satu menit dari apa, dengan kecepatan berapa? \\"Delapan bar cascade pada 96 BPM\\" adalah tantangan yang spesifik dan bisa diulang. Jika kamu berhasil melakukannya dengan bersih, sesi berikutnya bisa meminta 104. Itulah cara kerja tangga tempo, dan mengapa penguasaan dalam aplikasi bergantung pada jalannya yang bersih daripada sekadar waktu.","Ini membutuhkan rekayasa yang serius. Setiap animasi didorong oleh jam audio yang sama dengan musik, dijadwalkan terlebih dahulu agar tidak terhenti. Lagu yang dikemas memiliki tempo dan downbeat yang terukur. Perkusi yang dihasilkan mengisi setiap tempo yang kamu pilih. Lagu dari perangkatmu dianalisis dan diperiksa dengan uji ketukan. Video streaming dimatikan dalam latihan yang dihitung karena kami tidak bisa menjaganya tetap sesuai irama.","Hasilnya adalah irama menjadi guru. Saat kamu menyimpang, kamu mendengarnya. Saat kamu terkunci, kamu merasakannya. Menghitung dalam bar ternyata menjadi pilihan desain terpenting yang kami buat."]},"staff-hit-me-in-the-head":{"title":"Tongkat itu mengenai kepalaku (dan pelajaran lainnya)","summary":"Setiap pemutar tongkat pasti pernah dipukul; bantalan, bidang, dan kesabaran mengubah pukulan itu menjadi kemajuan.","body":["Figure-8 pertamaku berakhir dengan tongkat memantul dari tengkorakku dan anjing pergi dari ruangan. Yang kedua berakhir dengan cara yang sama, tanpa anjing. Jika kamu belajar memutar tongkat, kamu akan terpukul. Pertanyaannya adalah seberapa keras, dan apa yang kamu pelajari darinya.","Pelajaran pertama: bantalan bukanlah pengecutan. Tongkat latihan dengan ujung lembut mengubah pukulan dari jeritan menjadi anggukan. Anggukan itu penting, karena rasa takut membuatmu mengelak, dan pergelangan tangan yang mengelak menarik tongkat keluar dari bidangnya, yang menyebabkan pukulan berikutnya.","Pelajaran kedua: sebagian besar pukulan datang dari bidang yang miring. Ketika saya merekam diri sendiri dari sisi, saya bisa melihat tongkat itu miring ke arah wajah saya di bagian atas setiap putaran. Pergelangan tangan saya berputar ke dalam. Tampilan bidang di penampil 3D menunjukkan versi yang bersih: tongkat dalam bentuk lembaran datar di samping tubuh, tidak pernah miring ke dalam. Memperbaiki pergelangan tangan memperbaiki pukulan-pukulan itu.","Pelajaran ketiga: lambat dan dihitung, cepat dan penuh harapan. Saya menurunkan tempo ke bagian bawah rentang gerakan angka delapan dan menghitung \\"sisi kanan, sisi kiri\\" sesuai musik. Pada kecepatan itu saya bisa merasakan perubahan tangan dan menjaga bidang tetap datar. Seminggu kemudian saya bisa kembali mempercepat.","Pelajaran keempat: tertawa. Memutar tongkat itu konyol dan luar biasa. Pukulan-pukulan itu adalah bagian dari cerita yang dibagikan semua orang di tempat itu. Pakailah topi jika perlu, bersihkan lampu langit-langit, dan teruslah memutar."]},"hooping-for-people-who-cant-hoop":{"title":"Hooping untuk orang yang berpikir mereka tidak bisa hooping","summary":"Kebanyakan orang dewasa yang \\"tidak bisa mengelilingi\\" diberi lingkaran berukuran mainan; lingkaran yang lebih besar dan denyut maju-mundur memperbaiki sebagian besar masalah.","body":["\\"Saya tidak bisa mengelilingi\\" adalah sesuatu yang sering didengar guru mengelilingi, biasanya dari seseorang yang terakhir mencoba dengan lingkaran mainan anak-anak. Lingkaran kecil dan ringan berputar cepat dan jatuh cepat. Mereka membutuhkan pinggul yang cepat dan panik. Orang dewasa dengan lingkaran berukuran dewasa sering menemukan bahwa itu jauh lebih mudah dikelola.","Mulailah dengan yang besar. Lingkaran yang mencapai sekitar antara pinggang dan dada saat diletakkan di lantai berputar cukup lambat sehingga Anda bisa merasakan ritme. Lingkaran yang lebih berat juga membawa lebih banyak momentum. Anda bisa memperkecil ukurannya nanti untuk kecepatan dan trik di luar tubuh.","Pulsasi, bukan lingkaran. Kesalahan paling umum adalah mencoba membuat lingkaran besar dengan pinggul. Mengelilingi pinggang biasanya merupakan gerakan kecil maju-mundur, atau sisi ke sisi, selaras dengan lingkaran. Satu kaki sedikit ke depan membantu. Lingkaran menyentuh bagian depan dan belakang Anda; Anda mendorong dengan lembut saat berputar.","Hitunglah. Tempo yang santai, satu orbit per ketukan, memberi tubuh ritme untuk menetap. Aplikasi ini memulai mengelilingi pinggang dengan lambat, lalu memungkinkan Anda naik. Jika lingkaran jatuh, tambahkan sedikit kecepatan pada denyut Anda, bukan gerakan yang lebih besar.","Harapkan lingkaran jatuh banyak selama beberapa sesi, lalu tiba-tiba tidak jatuh lagi. Mengelilingi adalah salah satu keterampilan yang tiba-tiba terasa masuk akal. Setelah itu, ada dunia penuh aliran di dalam dan di luar tubuh yang menunggu, dan banyak di antaranya bahkan tidak memerlukan pinggang."]},"unlocking-is-not-a-race":{"title":"Unlocking bukan perlombaan","summary":"Pohon hadiah membuka gerakan yang lebih sulit saat Anda menguasai dasarnya; intinya adalah dasar-dasarnya.","body":["Hadiah SynthFlow adalah gerakan. Kuasai cascade dan reverse cascade akan terbuka; kuasai front spin dan figure-8 akan muncul. Sangat memuaskan melihat pohonnya menyala, dan kami merancangnya agar begitu. Namun ada jebakan dalam setiap sistem pembukaan, dan perlu disebutkan.","Jebakannya adalah memperlakukan penguasaan sebagai kotak yang harus dicentang. Anda secara teknis bisa mencatat jalur bersih untuk sebuah gerakan pada hari yang baik, membuka yang berikutnya, dan melanjutkan dengan fondasi yang hanya bekerja saat semuanya berjalan lancar. Kemudian gerakan yang lebih sulit terasa mustahil, karena mereka mengasumsikan fondasi bekerja saat sesuatu salah.","Penguasaan dalam aliran berarti gerakan tetap bertahan di tengah gangguan: sedikit kelelahan, tempo yang berbeda, seseorang berjalan lewat. Itulah sebabnya penguasaan meminta jalur bersih di berbagai sesi, bukan hanya dalam satu sesi. Dan itulah sebabnya kami menyarankan untuk kembali ke gerakan yang sudah dikuasai secara teratur. Cascade bukan level yang Anda selesaikan; itu adalah dasar di mana seluruh pohon juggling berdiri.","Gerakan yang terkunci tetap memiliki halaman. Anda bisa membacanya, menontonnya dalam 3D dan melihat apa yang dibutuhkan. Melihat ke depan memotivasi. Berlatih ke depan tanpa fondasi, sebagian besar hanya menimbulkan kekecewaan.","Jadi nikmati pembukaannya, tetapi ukur diri Anda berdasarkan seberapa mudah gerakan tertua Anda terasa. Ketika cascade membosankan, Anda siap untuk Mills Mess. Ketika Mills Mess membosankan, pohon itu masih punya lebih banyak yang ditawarkan."]},"practice-in-ten-minutes":{"title":"Praktik nyata dalam sepuluh menit","summary":"Pemanasan, satu gerakan fokus, satu tautan, pendakian tempo singkat, dan pendinginan: sepuluh menit, setiap hari.","body":["Alasan paling umum yang diberikan orang untuk tidak berlatih adalah waktu. Kenyataannya, keterampilan aliran merespons dengan sangat baik terhadap sesi singkat dan sering. Berikut adalah bentuk sepuluh menit yang kami gunakan sendiri.","Menit satu hingga dua: pemanasan. Lingkaran pergelangan tangan, lingkaran lengan, putaran bahu, beberapa lingkaran pinggul jika Anda menggunakan ring. Dihitung, dengan tempo santai, agar waktu Anda terbangun bersama sendi Anda.","Menit tiga hingga lima: gerakan fokus Anda. Satu gerakan yang sedang Anda latih, dengan tempo yang bisa Anda lakukan dengan bersih. Beberapa langkah pendek yang dihitung, bukan satu langkah panjang, dengan napas di antaranya.","Menit enam hingga tujuh: satu tautan. Padukan gerakan fokus dengan sesuatu yang mengalir masuk atau keluar darinya. Cascade ke reverse cascade. Front spin ke figure-8. Pinggang ke dada. Tautan adalah yang membuat latihan terasa seperti aliran alih-alih latihan rutin.","Menit delapan hingga sembilan: kenaikan tempo kecil. Dua atau tiga tingkat, beberapa BPM masing-masing, berhenti sebelum bentuknya rusak. Akhiri dengan tingkat yang bersih.","Menit kesepuluh: pendinginan. Gerakan lambat dan mudah atau istirahat singkat. Catat upaya Anda. Selesai.","Sepuluh menit sehari adalah lebih dari satu jam seminggu latihan terfokus, tersebar dengan cara yang paling disukai koordinasi. Wizard latihan membuat sesi sebesar ini ketika Anda memberi tahu bahwa waktu Anda terbatas, dan rutinitas pendek yang terpasang mengikuti bentuk yang sama."]},"antispin-broke-my-brain":{"title":"Antispin membuat otakku kacau (selama seminggu)","summary":"Mengubah tongkat melawan lingkaran tangan terasa mustahil sampai hitungan memberi setiap kelopak satu ketukan.","body":["Antispin adalah tempat di mana pemintalan tongkat mulai terasa seperti pekerjaan rumah geometri. Tangan Anda menggambar lingkaran ke satu arah sementara tongkat berputar ke arah lain, dan ujung-ujungnya melukis bunga. Pertama kali saya mencoba, saya menghasilkan sesuatu yang lebih mirip dandelion layu.","Yang membantu adalah membuat bentuknya bisa dihitung. Antispin empat kelopak memiliki empat momen di mana ujungnya mengarah langsung keluar dari lingkaran. Saya memberi setiap momen satu ketukan: atas, sisi, bawah, sisi. Kemudian saya memperlambat musik jauh di bawah tempo pemintalan normal saya dan hanya bertujuan mencapai posisi pada ketukan tersebut.","Hantu di penampil 3D, yang menunjukkan di mana tongkat seharusnya berada pada ketukan berikutnya, adalah sahabat terbaik saya minggu itu. Begitu pula jejaknya, yang menggambar bunga saya sehingga saya bisa melihat kapan kelopaknya tidak merata. Biasanya kelopak bawah terhimpit, karena saya terburu-buru di bagian bawah lingkaran.","Setelah sekitar seminggu, sesuatu berubah. Saya berhenti memikirkan tangan dan tongkat sebagai dua hal terpisah dan mulai merasakan bunga sebagai satu bentuk. Tempo kembali naik dengan sendirinya.","Jika antispin membuat otak Anda kacau, itu memang seharusnya. Beri setiap kelopak satu ketukan, perlahan musiknya, dan biarkan tubuh Anda menyelesaikannya. Ini salah satu perasaan terbaik dalam aliran ketika berhasil."]},"siteswaps-for-the-maths-shy":{"title":"Siteswaps untuk yang tak suka matematika","summary":"Anda tidak perlu menyukai matematika untuk menggunakan siteswap; Anda hanya perlu tahu bahwa angka yang lebih besar melambangkan lemparan yang lebih tinggi.","body":["Notasi siteswap memiliki reputasi menakutkan orang. Para pemain juggling akan dengan riang berkata \\"coba 531\\" seolah-olah itu menjelaskan sesuatu. Memang begitu, tetapi hanya setelah Anda tahu beberapa hal, dan hal-hal itu lebih sederhana dari yang terlihat.","Berikut hampir semua yang Anda butuhkan. Setiap angka adalah lemparan. Angka yang lebih besar melambangkan lemparan yang lebih tinggi. Angka ganjil melintasi ke tangan lain; angka genap kembali ke tangan yang sama. Angka 3 adalah lemparan cascade normal. Angka 1 adalah zip cepat melintasi. Angka 2 biasanya hanya memegang bola.","Itu sudah cukup untuk membaca 441: dua lemparan tinggi yang tetap di sisi masing-masing, lalu zip melintasi. Anda sekarang bisa mencobanya tanpa membaca kata lain. Lempar, lempar, zip, sesuai ketukan.","Jika Anda ingin satu bagian lagi: tambahkan angka-angka tersebut dan bagi dengan jumlahnya, maka Anda akan mendapatkan jumlah bola. 4 + 4 + 1 = 9, dibagi 3 adalah 3 bola. Jika jawabannya bukan bilangan bulat, maka pola tersebut tidak bisa dijuggling. Itulah seluruh isi dari teorema rata-rata yang terkenal.","Di SynthFlow, setiap gerakan juggling memiliki siteswap, dan mesin 3D menganimasikannya langsung dari sana. Artinya, gerakan selalu melempar pada ketinggian yang tepat sesuai angka yang dijelaskan, pada ketukan yang tepat. Menonton siteswap yang dianimasikan secara perlahan adalah cara tercepat yang kami tahu untuk membuat angka-angka tersebut masuk akal. Tidak perlu gelar matematika."]},"music-that-fights-you":{"title":"Ketika musik melawan Anda","summary":"Sebuah lagu yang bergerak melawan hitungan membuat setiap gerakan menjadi lebih sulit; tempo yang terukur dan ketukan yang dihasilkan memperbaikinya.","body":["Anda mungkin pernah merasakannya: sebuah lagu yang Anda sukai, sebuah gerakan yang Anda ketahui, dan entah bagaimana semuanya terasa salah. Anda terburu-buru, Anda menjatuhkan, Anda menyalahkan diri sendiri. Seringkali masalahnya bukan Anda. Tapi karena tempo lagu tidak sesuai dengan gerakan.","Setiap gerakan flow memiliki rentang tempo yang nyaman. Di bawahnya, alat putar akan terhenti; di atasnya, lemparan menjadi rendah dan panik. Sebuah lagu dengan 128 BPM di bawah gerakan hoop yang menyukai 90 meminta Anda untuk memilih antara musik dan hoop. Kabar baiknya adalah bahwa tempo setengah dan dua kali lipat membantu: 128 bisa membawa gerakan pada 64, satu siklus setiap dua ketukan.","Drift adalah masalah yang lebih halus. Jika musik mengatakan 120 tetapi hitungan mengatakan 116, keduanya akan berpisah selama satu menit, dan tubuh Anda tidak bisa mengikuti keduanya. Inilah sebabnya SynthFlow menggunakan tempo yang terukur untuk lagu-lagu yang disertakan, menghasilkan perkusi pada tempo yang tepat, dan memeriksa lagu dari perangkat Anda dengan uji ketukan.","Ketika sebuah lagu melawan Anda, jangan melawan balik. Ganti ke ketukan yang dihasilkan untuk langkah tersebut, atau biarkan pembuat menyarankan lagu dalam rentang yang tepat. Simpan lagu-lagu yang Anda sukai untuk bermain bebas, di mana tidak ada yang perlu selaras.","Musik seharusnya terasa seperti pasangan. Jika terasa seperti lawan, ganti musiknya, bukan gerakan Anda."]},"learning-alongside-my-kid":{"title":"Belajar juggling bersama anak saya","summary":"Dua pemula, satu tas bola dan satu aturan: kami merayakan jatuh sekeras merayakan tangkapan.","body":["Putri saya meminta untuk belajar juggling, dan saya menyadari bahwa saya juga tidak bisa juggling. Jadi kami belajar bersama, sepuluh menit setelah makan malam, dengan masing-masing tiga tas kacang dan satu aturan: kami bersorak atas jatuh sekeras bersorak atas tangkapan.","Aturan itu terdengar konyol. Ternyata itu adalah bagian yang paling penting. Anak-anak, dan orang dewasa, menjadi tegang ketika mereka berpikir kesalahan itu memalukan. Ketegangan membuat lemparan menjadi lebih buruk. Bersorak atas setiap jatuh mengubah lantai menjadi bagian dari permainan dan membuat kami berdua tetap rileks.","Kami mulai dengan satu bola, melemparkannya dari tangan ke tangan mengikuti irama, dengan puncak lemparan setinggi mata. Rasanya terlalu mudah selama sekitar tiga sesi, lalu tiba-tiba menjadi penting, karena pertukaran dua bola hanya berhasil jika lemparan tunggalnya konsisten. Dia berhasil melakukan pertukaran sebelum saya, dan sangat sombong tentang hal itu.","Musik yang dihitung membantu kami berlatih bersama. Tempo yang sama, ketukan yang sama, dua orang melempar secara sinkron. Ketika salah satu dari kami kehilangan pola, yang lain terus melanjutkan, dan orang yang melempar terlewat akan kembali pada \\"satu\\" berikutnya.","Empat minggu kemudian, kami berdua sudah bisa melakukan cascade yang goyah. Yang lebih penting, kami punya kebiasaan yang sama-sama kami nantikan. Jika Anda punya anak yang ingin belajar sesuatu, pelajarilah bersama mereka. Menjadi pemula bersama-sama sering dianggap remeh."]},"why-your-throws-drift-forward":{"title":"Mengapa lemparan Anda melayang ke depan","summary":"Jika Anda menyelesaikan setiap cascade tiga langkah dari tempat Anda mulai, lemparan Anda miring menjauh dari Anda. Inilah cara membawanya kembali ke tempat asal.","body":["Setiap pesulap tahu yang namanya berjalan. Anda memulai cascade di tengah ruangan dan menyelesaikannya dengan hidung menempel dinding, mengejar pola satu langkah demi satu langkah. Rasanya seperti bola-bola itu menarik Anda. Tidak. Anda melempar bola ke depan, beberapa sentimeter sekaligus, lalu berjalan untuk menangkapnya.","Penyebabnya hampir selalu dari siku. Saat Anda tegang, lengan bawah miring ke depan dan tangan melepaskan bola sedikit di depan tubuh. Setiap lemparan jatuh sedikit lebih jauh, sehingga tangkapan berikutnya terjadi lebih jauh, sehingga lemparan berikutnya dimulai lebih jauh. Ini cepat menumpuk.","Solusi yang saya ajarkan pertama adalah menarik siku. Pertahankan siku dekat tulang rusuk, lengan bawah kira-kira sejajar, dan lemparkan bola lurus ke atas melewati mata Anda, bukan ke depan. Rasanya sempit selama sehari. Lalu rasanya tenang.","Solusi kedua adalah dengan menggunakan dinding. Berdirilah menghadap dinding, sekitar satu lengan jauhnya, dan berjugglinglah. Jika lemparan miring, dinding akan segera memberi tahu Anda, dan dengan keras. Sepuluh menit berlatih di depan dinding mengajarkan tubuh bagaimana rasanya pola yang tegak lebih cepat daripada apa pun yang bisa saya katakan.","Mode kamera SynthFlow juga memantau kemiringan. Ia melacak seberapa besar tubuh Anda terlihat lebih besar ke kamera dalam satu langkah, yang berarti Anda berjalan ke arahnya, dan memberi Anda isyarat singkat. Pelatih 3D juga bisa menampilkan bayangan lemparan ke depan di samping lemparan yang bersih, sehingga Anda bisa melihat perbedaannya daripada hanya mendengarnya.","Kemiringan bukanlah kekurangan karakter. Ini adalah kebiasaan ketegangan, dan kebiasaan berubah dengan pengulangan. Tarik siku, lempar ke atas bukan ke depan, dan biarkan dinding membuat Anda tetap jujur."]},"practising-to-a-click":{"title":"Berlatih dengan bunyi klik","summary":"Metronom terdengar seperti hal yang paling tidak menyenangkan di dunia. Ternyata, hal itulah yang membuat alur saya terasa seperti menari.","body":["Saya menolak click selama bertahun-tahun. Musik adalah inti dari flow arts bagi saya, dan metronom terasa seperti pekerjaan rumah. Lalu seorang teman yang bermain drum melihat saya berjuggling dan berkata dengan ramah, bahwa saya selalu mempercepat setiap kali bersemangat dan memperlambat setiap kali merasa takut. Dia benar, dan saya tidak menyadarinya.","Jadi saya mencoba seminggu latihan hanya dengan click. Penemuan pertama adalah bahwa pulsa yang stabil lebih sulit daripada terdengar. Pola dua di satu tangan saya ingin terburu-buru. Pola angka delapan tongkat saya ingin terhambat di sisi yang lemah. Click tidak peduli bagaimana perasaan saya; ia hanya terus mengatur waktu.","Penemuan kedua adalah bahwa click membuat musik lebih mudah. Setelah seminggu, ketika saya memutar lagu asli kembali, saya bisa merasakan di mana irama berada di dalam suara. Saya berhenti melawan lagu dengan waktu yang longgar dan mulai memilih bagian dari groove mana yang ingin saya ikuti.","Pertunjukan perkusi yang dihasilkan oleh SynthFlow adalah versi yang lebih ramah dari click. Anda memilih satu set perkusi, dari click polos hingga drum tangan, dan itu bermain pada setiap tempo, sehingga pola bisa hidup pada kecepatan yang tepat yang bisa Anda pertahankan. Ia juga bisa berjalan secara pelan di bawah lagu sebagai panduan. Saya masih menggunakannya sendiri selama beberapa menit pertama setiap sesi.","Jika Anda ingin mencoba ini, pilih satu pola dan satu tempo yang terasa sedikit terlalu lambat. Hitung dengan keras selama empat bar, lalu berhenti menghitung dan hanya dengarkan. Ketika pola dan click terasa seperti satu suara, tambahkan empat BPM. Itulah seluruh metodenya."]},"staff-in-a-small-apartment":{"title":"Staf di apartemen kecil","summary":"Tongkat 1,4 meter dan langit-langit 2,4 meter bisa hidup berdampingan. Anda hanya perlu memilih bidangnya.","body":["Apartemen saya memiliki langit-langit yang rendah, lampu yang saya sukai, dan tetangga di bawah yang bekerja malam. Tak satu pun dari itu ideal untuk berputar tongkat. Saya berlatih di taman selama setahun sebelum menyadari bahwa sebagian besar latihan saya bisa dilakukan di dalam ruangan.","Rahasianya adalah bidang. Putaran bidang roda, yang besar di samping tubuh, membutuhkan ketinggian penuh tongkat di atas kepala Anda. Pekerjaan bidang dinding di depan tubuh membutuhkan lebar tetapi lebih sedikit ketinggian. Putaran bidang lantai, seperti helikopter, membutuhkan ruang di atas kepala Anda tetapi tidak ada di sekitar pergelangan kaki Anda. Setiap ruangan mendukung gerakan yang berbeda.","Di ruang tamu saya bisa melakukan isolasi, putaran depan, dan gerakan angka 8 lambat dengan lengan rendah. Di lorong saya tidak bisa melakukan apa pun, jadi lorong digunakan untuk pemanasan pergelangan tangan. Kamar tidur memiliki langit-langit tertinggi, jadi latihan wheel-plane dilakukan di sana, perlahan, dengan lampu dikeluarkan dan disimpan di laci.","Tongkat pendek juga membantu. Tongkat latihan yang lebih pendek satu panjang tangan dari tongkat pertunjukan saya mengubah banyak kegagalan hampir menjadi keberhasilan yang mudah. Waktunya berubah sedikit, jadi saya memeriksa tongkat panjang saya di luar sekali seminggu.","Untuk tetangga: tikar latihan dan tongkat dengan ujung lembut. Jatuh ke tikar yoga menghasilkan suara letupan yang lembut, bukan suara retak. Saya juga membatasi sesi dalam ruangan menjadi rutinitas terhitung selama sepuluh menit, yang membuat suara pendek dan latihan tetap fokus.","SynthFlow memungkinkan Anda menandai gerakan yang tidak bisa Anda lakukan di rumah sebagai tidak disukai sehingga generator mengabaikannya dalam rutinitas dalam ruangan. Ruang kecil tidak menghentikan kemajuan. Mereka hanya membuat Anda sangat mahir dalam isolasi."]},"hooping-after-40":{"title":"Hooping setelah 40","summary":"Saya mengambil hoop untuk pertama kalinya di usia 43. Punggung, lutut, dan harga diri saya semua punya pendapat. Inilah yang berhasil.","body":["Saya membeli hoop dewasa pertama saya secara spontan setelah festival, yakin saya akan buruk. Saya memang buruk. Namun, dalam waktu sebulan, saya sudah bisa menggiring hoop di pinggang selama lagu penuh, dan dalam enam bulan melakukan gerakan sederhana di luar tubuh. Usia tidak menghentikan saya. Itu hanya mengubah cara saya berlatih.","Pelajaran besar adalah melakukan pemanasan dengan benar. Lingkaran pinggul, putaran tubuh, dan lompatan lutut lembut memakan waktu tiga menit dan membuat hoop pertama sesi terasa halus, bukan kaku. SynthFlow menempatkan pemanasan di awal setiap rutinitas karena alasan tertentu, dan saya berhenti melewatkan pemanasan setelah satu pagi yang kaku.","Pelajaran kedua adalah ukuran hoop. Hoop yang lebih besar dan sedikit lebih berat berputar lebih lambat, yang memberi Anda lebih banyak waktu dan meminta sedikit usaha dari punggung bawah. Saya mulai dengan hoop yang mencapai antara pinggang dan dada saat berdiri di lantai, dan saya masih menggunakannya untuk sesi latihan panjang.","Ketiga: pulsasi, bukan lingkaran. Pemula sering mengayunkan pinggul dalam lingkaran, yang membuat tulang belakang berputar lebih dari yang dibutuhkan. Pulsasi ke depan-ke belakang, atau sisi-ke-sisi jika hoop berputar seperti itu untuk Anda, menjaga hoop tetap naik dengan lebih sedikit ketegangan. Pelatih 3D menunjukkan ini dengan jelas jika Anda mengamati pinggul daripada hoop.","Terakhir, singkat dan sering mengalahkan panjang dan sesekali. Sepuluh menit empat kali seminggu lebih berdampak bagi saya daripada satu jam pada hari Minggu. Tubuh saya pulih di antara sesi, dan gerakan-gerakan itu tertanam.","Jika Anda berusia di atas 40 dan penasaran, mulailah. Hoop tidak tahu berapa usia Anda."]},"fire-and-the-beginner":{"title":"Api dan Pemula","summary":"Pemutaran api adalah bagian paling terlihat dari seni aliran dan bagian yang paling sering ditanyakan pemula. Jawaban yang jujur adalah: belum, dan tidak sendirian.","body":["Setiap minggu seseorang bertanya kepada kami kapan SynthFlow akan mengajarkan pemutaran api. Ini pertanyaan yang wajar. Api itu indah, dan banyak pemutar masuk ke dunia ini setelah melihat lingkaran api di malam hari. Tapi kami tidak akan pernah melatih siapa pun untuk menyalakan alat, dan posting ini menjelaskan alasannya.","Api menambahkan bahaya yang tidak ada hubungannya dengan keterampilan: penanganan bahan bakar, pakaian, angin, penonton, luka bakar, dan pemadaman. Ini dipelajari dari orang yang berpengalaman secara langsung, dengan orang yang terlatih dalam keselamatan hadir dan peralatan yang tepat siap. Sebuah aplikasi tidak bisa memeriksa tempat pembuangan bahan bakar Anda, pakaian katun Anda, atau handuk keselamatan Anda.","Apa yang bisa dilakukan aplikasi adalah membantu Anda membangun keterampilan yang dibutuhkan api sebelum Anda pernah mendekatinya. Artinya gerakan yang bisa Anda lakukan secara konsisten selama satu lagu penuh, dengan tempo yang stabil, tanpa jatuh. Jika pola masih mengejutkan Anda di rumah dengan alat latihan, itu belum siap untuk api.","Ujian yang berguna dari komunitas api: dapatkah Anda melakukan rutinitas dengan mata setengah tertutup, dalam kegelapan, sambil seseorang berbicara kepada Anda? Api itu terang, panas, dan berisik, dan itu menarik perhatian Anda. Tubuh Anda harus tahu gerakan tanpa pengawasan.","Alat LED adalah langkah yang bagus di antaranya. Mereka memberi Anda tampilan malam hari, jejak, dan reaksi penonton tanpa risiko. Paket gaya LED SynthFlow menunjukkan tampilan pola Anda saat dinyalakan, yang juga merupakan cara yang baik untuk mengenali bidang yang ceroboh.","Ketika Anda siap, temukan jam api lokal, perkenalkan diri Anda, dan minta untuk belajar keselamatan terlebih dahulu. Putar alat latihan sampai saat itu. Api masih akan ada."]},"four-balls-taught-me-patience":{"title":"Empat Bola Mengajarku Kesabaran","summary":"Beralih dari tiga bola ke empat membutuhkan waktu lebih lama daripada mempelajari tiga bola pada awalnya, dan itu mengubah cara saya berpikir tentang latihan.","body":["Tiga bola membutuhkan waktu lima minggu bagi saya. Empat butuh waktu lima bulan. Tidak ada yang memperingatkan saya tentang ini, jadi saya memperingatkan Anda: empat bola bukan tiga bola ditambah satu. Ini adalah pola yang sama sekali berbeda, dan tubuh Anda harus mempelajarinya dari awal.","Dalam air mancur empat bola, masing-masing tangan menjuggling dua bola sendiri, dan bola-bola tidak pernah saling bersilangan. Tangan biasanya bergantian, tetapi tidak ada pertukaran sama sekali di antara mereka. Semua yang saya pelajari tentang menangkap bola dari tangan lain tiba-tiba menjadi tidak berguna.","Jadi saya kembali ke satu tangan. Dua bola di tangan kanan, dalam kolom, lalu lingkaran, sampai saya bisa melakukan lima puluh lemparan tanpa berpikir. Kemudian tangan kiri, yang memakan waktu tiga kali lebih lama. Lalu kedua tangan bersama, pertama sinkron, lalu bergantian. Tangga tempo di SynthFlow membantu di sini: saya memulai setiap minggu di bagian bawah rentang air mancur dan hanya naik setelah menjalankan dengan lancar.","Pelajaran kesabaran datang dari titik datar. Beberapa minggu tidak ada perbaikan. Saya tetap mencatat jatuh dan lemparan bersih, dan grafik menunjukkan kemajuan perlahan meskipun terasa tidak ada. Data membuat minggu-minggu yang membosankan bisa ditanggung.","Pelajaran lainnya adalah tentang istirahat. Empat bola membuat lengan bawah saya lelah dengan cara yang tidak pernah terjadi dengan tiga bola. Ketika saya berlatih setiap hari, saya menjadi lebih buruk. Ketika saya berlatih setiap dua hari sekali, saya menjadi lebih baik. Otot pegangan membutuhkan pemulihan seperti otot lainnya.","Jika Anda terjebak antara tiga dan empat, pecah masalahnya, percayalah pada minggu-minggu yang lambat, dan beri istirahat pada lengan bawah Anda. Itu akan datang."]},"the-escalator-and-hand-traffic":{"title":"Escalator dan seni lalu lintas tangan","summary":"Gerakan tangan hoop terlihat seperti sihir sampai Anda melihat bahwa itu hanyalah manajemen lalu lintas yang hati-hati antara dua tangan.","body":["Pertama kali saya melihat eskalator, hoop tampaknya naik di lengan pengoper dan turun lagi, tanpa henti, tanpa pegangan yang jelas. Saya mengira itu membutuhkan bertahun-tahun latihan. Ternyata hanya sekitar tiga minggu, setelah saya memahami bahwa itu hanyalah pola serah terima.","Hampir semua gerakan hoop di luar tubuh adalah tentang tangan mana yang memegang hoop, kapan melepaskannya, dan di mana tangan lain menangkapnya. Jika waktu antar tangan kabur, hoop akan goyah keluar dari bidangnya dan gerakan itu akan runtuh. Jika waktunya bersih, hoop terlihat seperti bergerak sendiri.","Jadi saya mulai menamai serah terima. Di atas hitungan SynthFlow, saya mengucapkan tangan secara lisan alih-alih angka: kanan, kiri, kanan, kiri, satu di setiap ketukan. Mengucapkannya dengan musik memaksa saya untuk memperhatikan ketika tangan kiri saya menangkap lebih awal. Tangkapan dini adalah sumber dari hampir semua goyangan.","Kunci kedua adalah menjaga hoop tetap dalam bidangnya. Tangan yang berputar saat memegang akan memiringkan hoop, dan hoop yang miring akan jatuh setengah detik kemudian. Lapisan bidang membantu di sini, begitu juga berlatih di depan cermin dengan tempo lambat.","Setelah eskalator terasa andal, gerakan tangan lainnya datang lebih cepat. Isolasi, lemparan, dan lasso semuanya menggunakan ide yang sama: serah terima yang jelas, bidang datar, waktu yang stabil. Keajaibannya hanyalah manajemen lalu lintas."]},"behind-the-back-without-fear":{"title":"Di belakang punggung tanpa rasa takut","summary":"Passing staff di belakang punggung adalah saat kebanyakan pemutar terhenti. Masalahnya biasanya bukan karena kurangnya keterampilan, melainkan keinginan untuk melihat.","body":["Selama berbulan-bulan, passing di belakang punggung saya adalah passing depan dengan sentuhan harapan. Saya memulai gerakan, panik saat staff keluar dari pandangan, lalu membawanya kembali di depan saya. Staff sebenarnya tidak pernah melewati punggung saya. Otak saya tidak membiarkannya.","Terobosan datang dari penerimaan bahwa saya tidak bisa melihat gerakan tersebut. Anda tidak bisa menonton passing di belakang punggung. Anda harus merasakan posisi staff dari tangan yang melepaskan dan mempercayai tangan yang menunggu.","Saya melatih perasaan itu secara perlahan. Tanpa memutar sama sekali, saya melewatkan staff di belakang punggung, tangan ke tangan, dengan mata menghadap ke depan. Kemudian dengan setengah putaran lambat terlebih dahulu. Lalu pada bagian bawah rentang tempo gerakan, saya menghitung. Setiap langkah terasa konyol. Setiap langkah berhasil.","Pelatih 3D ternyata sangat membantu karena saya bisa memutar tampilan dan menonton gerakan dari belakang. Melihat di mana kedua tangan bertemu, dan bagaimana staff tetap berada dalam bidang dinding saat berputar, memberi tubuh saya peta yang tidak bisa didapat dari depan.","Ketakutan kedua adalah memukul diri sendiri. Staff latihan dengan ujung lembut dan ruang yang luas dan jelas menyelesaikan masalah itu. Setelah saya tahu kesalahan hanya akan menyebabkan benturan ringan bukan memar, saya berhenti mengelak, dan ketakutan itulah yang menyebabkan kegagalan.","Jika passing di belakang punggung masih membuat Anda takut, perlahanlahanlah, hilangkan putarannya, dan tetapkan mata menghadap ke depan. Tangan Anda tahu lebih banyak dari yang Anda kira."]},"why-reverse-feels-wrong":{"title":"Mengapa cascade terbalik terasa salah","summary":"Cascade terbalik menggunakan tangan yang sama, bola yang sama, dan ritme yang sama dengan cascade. Lalu mengapa terasa seperti memulai dari awal?","body":["Ketika saya belajar cascade terbalik, saya mengharapkan itu memakan waktu setengah hari. Ini adalah tiga bola yang sama, tangan bergantian yang sama, dan tempo yang sama dengan cascade. Butuh tiga minggu, dan saya tidak bisa memahami alasannya.","Jawabannya adalah arah. Dalam cascade normal, setiap bola dilempar dari bagian dalam pola dan ditangkap di bagian luar. Dalam cascade terbalik, bola dilempar dari luar, di atas bola yang datang, dan ditangkap di bagian dalam. Tangan Anda membuat ritme yang sama tetapi bentuk yang sangat berbeda.","Bentuk baru ini mengacaukan timing Anda. Dalam cascade, Anda melempar tepat saat bola yang datang mulai jatuh. Dalam terbalik, Anda perlu melempar sedikit lebih awal agar bola Anda melewati atas bola lainnya. Melempar pada saat lama dan bola-bola akan bertabrakan.","Saya memperbaikinya dengan dua bola terlebih dahulu. Dua bola, arah terbalik, dihitung sesuai irama, sampai terasa otomatis. Kemudian tiga bola dengan tempo lambat sambil mengucapkan hitungan. Overlay hantu SynthFlow menunjukkan kesalahan umum, yaitu lemparan yang terlalu rendah dan menyentuh bola lainnya, dan saya bisa melihat bahwa saya memang melakukan hal yang sama.","Setelah terasa, banyak hal terbuka. Menggabungkan cascade dan reverse adalah dasar dari banyak trik, dan bentuk reverse muncul lagi dalam Mills Mess. Tidak mahir selama tiga minggu ternyata sepadan."]},"making-a-prop-stand-still":{"title":"Isolasi: membuat prop berdiri diam","summary":"Isolasi adalah gerakan di mana prop tampak tetap di satu tempat sementara Anda bergerak di sekitarnya. Ini adalah ilusi paling memuaskan dalam seni aliran.","body":["Pertama kali saya berhasil melakukan isolasi tongkat, teman saya bertanya bagaimana tongkat itu bisa melayang. Tentu saja tidak melayang. Tangan saya bergerak dalam lingkaran yang hati-hati sehingga satu titik pada tongkat tetap diam di udara. Tapi dari luar terlihat mustahil, dan perasaan itulah yang membuat saya menyukai isolasi.","Setiap isolasi bekerja dengan cara yang sama. Pilih titik pada prop, biasanya di tengah atau salah satu ujung, dan jaga titik itu tetap diam sementara bagian lain prop berputar. Tangan Anda harus bergerak secara terbalik dengan arah yang diinginkan prop. Ini tidak masuk akal dan sedikit memikat.","Bagian tersulitnya adalah tubuh Anda juga bergerak. Pinggul bergeser, bahu berputar, dan setiap gerakan kecil terlihat sebagai goyangan pada titik tetap. Saya berlatih di depan cermin dengan selembar pita di kaca yang menandai di mana titik tetap seharusnya berada. Jika pusat prop meninggalkan pita, saya tahu.","Isolasi hoop mengikuti ide yang sama. Di SynthFlow saya mengaktifkan jejak di penampil 3D dan mengamati pelatih: dalam isolasi yang bersih, jejak di sekitar titik tetap tetap kecil. Ketika saya memperlambat tempo dan menirunya, saya bisa merasakan tangan saya melayang di bagian atas setiap lingkaran.","Isolasi juga membangun kontrol yang membantu segala hal lainnya. Setelah Anda bisa menahan prop tetap diam, Anda bisa menempatkannya di mana pun yang Anda pilih. Bidang menjadi lebih rata, transisi menjadi lebih bersih, dan alur Anda mulai terlihat sengaja daripada kebetulan.","Mulailah perlahan, tandai titik tetap, dan amati seakan-akan seekor elang. Lalu tunjukkan kepada teman dan nikmati ekspresi mereka."]}}`),i={"zero-to-cascade":{name:`Nol hingga Cascade dalam 4 minggu`,description:`Satu bola, lalu dua, lalu yang ketiga bergabung. Sesekali sesi pendek sehari sudah cukup: selesaikan rutinitas mingguan untuk menguasai gerakannya dan membuka yang berikutnya.`,weeks:[{label:`Minggu 1 · Satu bola`},{label:`Minggu 2 · Dua bola`},{label:`Minggu 3 · Bola ketiga`},{label:`Minggu 4 · Cascade`}]},"beyond-the-cascade":{name:`Di luar Cascade`,description:`Empat minggu variasi tiga bola: tenis dan cakar, lalu lemparan tubuh, lalu pola sinkron dua bola sekaligus.`,weeks:[{label:`Minggu 1 · Tenis dan cakar`},{label:`Minggu 2 · Setengah pancaran`},{label:`Minggu 3 · Lontaran tubuh`},{label:`Minggu 4 · Kolom`}]},"first-clubs":{name:`Tongkat pertama`,description:`Dari satu klub berputar ke tiga klub cascade yang stabil, lalu ganda untuk kontrol ketinggian dan putaran.`,weeks:[{label:`Minggu 1 · Satu tongkat`},{label:`Minggu 2 · Pertukaran`},{label:`Minggu 3 · Cascade`},{label:`Minggu 4 · Ganda`}]},"passing-with-a-partner":{name:`Pertukaran dengan pasangan`,description:`Dua juggler, berhadapan. Satu bola saling lempar, lalu dua masing-masing pada irama bersama, lalu enam hitungan, empat hitungan, dan dua hitungan dengan masing-masing tiga bola.`,weeks:[{label:`Minggu 1 · Satu bola melintasi`},{label:`Minggu 2 · Dua bola masing-masing`},{label:`Minggu 3 · Enam hitungan dan empat hitungan`},{label:`Minggu 4 · Dua hitungan`}]},"staff-foundations":{name:`Dasar tongkat`,description:`Putaran roda dan putaran depan, angka delapan dan lewat: empat gerakan yang hampir semua alur tongkat dibangun dari.`,weeks:[{label:`Minggu 1 · Putaran roda`},{label:`Minggu 2 · Putaran depan`},{label:`Minggu 3 · Angka 8`},{label:`Minggu 4 · Lintas`}]},"staff-contact":{name:`Kontak tongkat`,description:`Kendurkan pegangan minggu demi minggu: roda kemudi dan ekor ikan, lalu gulungan tangan, lalu tongkat berputar di lengan bawah.`,weeks:[{label:`Minggu 1 · Roda kemudi`},{label:`Minggu 2 · Ekor ikan`},{label:`Minggu 3 · Putaran tangan`},{label:`Minggu 4 · Putaran lengan bawah`},{label:`Week 5 · Angel / session`}]},"double-staff-start":{name:`Awal tongkat ganda`,description:`Dari dua tongkat dalam langkah ke waktu terpisah dan roda di kedua sisi.`,weeks:[{label:`Minggu 1 · Pada waktu yang sama`},{label:`Minggu 2 · Waktu terpisah`},{label:`Minggu 3 · Roda`},{label:`Minggu 4 · Roda terpisah`}]},"hoop-body-ladder":{name:`Tangga hoop tubuh`,description:`Hoop pinggang kedua arah, lalu turun ke pinggul dan paha dan naik ke dada.`,weeks:[{label:`Minggu 1 · Kedua arah`},{label:`Minggu 2 · Pinggul`},{label:`Minggu 3 · Paha`},{label:`Minggu 4 · Angkat dada`}]},"hoop-doubles-start":{name:`Awal hoop ganda`,description:`Satu hoop di setiap tangan: putaran cermin, putaran bergeser, putaran samping, lalu satu di pinggang dan satu di tangan.`,weeks:[{label:`Minggu 1 · Putaran cermin`},{label:`Minggu 2 · Putaran bergeser`},{label:`Minggu 3 · Putaran sisi`},{label:`Minggu 4 · Pinggang dan tangan`}]},"off-body-hoop":{name:`Hoop luar tubuh`,description:`Dari memutar hoop di satu tangan ke lasso, passing, wedgie, dan isolasi yang membuat hoop tampak mengambang.`,weeks:[{label:`Minggu 1 · Putaran tangan`},{label:`Minggu 2 · Lasso dan lempar`},{label:`Minggu 3 · Wedgie`},{label:`Minggu 4 · Isolasi`},{label:`Week 5 · Planes + on↔off`}]},"first-poi":{name:`Poi pertama`,description:`Satu poi, lalu sepasang: putaran dinding ke dua arah, roda di sisi Anda, lalu waktu terpisah.`,weeks:[{label:`Minggu 1 · Satu poi`},{label:`Minggu 2 · Putaran dinding`},{label:`Minggu 3 · Roda`},{label:`Minggu 4 · Waktu terpisah`}]},"poi-weave-ladder":{name:`Tangga tenun poi`,description:`Dari chase the sun ke tenunan tiga ketukan ke kedua arah, lalu tenunan dua ketukan yang lebih cepat.`,weeks:[{label:`Minggu 1 · Kejar matahari`},{label:`Minggu 2 · Tenun tiga ketukan`},{label:`Minggu 3 · Tenun terbalik`},{label:`Minggu 4 · Tenun dua ketukan`},{label:`Week 5 · Five-beat / degrees`}]},"poi-antispin-start":{name:`Awal antispin`,description:`Ekstensi dan isolasi terlebih dahulu, lalu antispin dengan satu poi dan bunga empat kelopak dengan dua.`,weeks:[{label:`Minggu 1 · Ekstensi`},{label:`Minggu 2 · Isolasi`},{label:`Minggu 3 · Antispin satu poi`},{label:`Minggu 4 · Bunga antispin`},{label:`Week 5 · Hybrids`}]},"staff-tech-map":{name:`Staff tech map`,description:`Timing cells and flowers: symmetry lab, then isolation and antispin flower work.`,weeks:[{label:`Week 1 · Symmetry cells`},{label:`Week 2 · Figure 8`},{label:`Week 3 · Isolation`},{label:`Week 4 · Antispin flower`}]},"hoop-isolation-ladder":{name:`Hoop isolation ladder`,description:`Float isolations and cateyes, then reconnect with weave and pass.`,weeks:[{label:`Week 1 · Isolation`},{label:`Week 2 · Cateye`},{label:`Week 3 · Weave`},{label:`Week 4 · Pass link`}]}},a={"sf-ambient-70":{name:`Orbit Lambat`},"sf-world-75":{name:`Langkah Pasar`},"sf-ambient-80":{name:`Berkeliling Lentera`},"sf-world-85":{name:`Roda Gurun`},"sf-handdrum-90":{name:`Drum Lingkaran`},"sf-funk-95":{name:`Pergelangan Tangan Longgar`},"sf-handdrum-100":{name:`Tangan Api`},"sf-world-105":{name:`Bells Sungai`},"sf-funk-110":{name:`Kaskade Saku`},"sf-handdrum-115":{name:`Groove Halaman`},"sf-electronic-120":{name:`Staf Neon`},"sf-funk-125":{name:`Pola Pantul`},"sf-electronic-130":{name:`Cincin Pixel`},"sf-handdrum-135":{name:`Djembe Matahari Terbenam`},"sf-electronic-140":{name:`Jejak LED`},"sf-funk-145":{name:`Siklus Putar`},"sf-electronic-150":{name:`Aliran Strobo`},"sf-handdrum-155":{name:`Telapak Tangan Cepat`},"sf-electronic-160":{name:`Pemintal Malam`}},o={poses:e,routines:t,learn:n,blog:r,progressions:i,music:a};export{r as blog,o as default,n as learn,a as music,e as poses,i as progressions,t as routines};